window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s50-27","number":27,"surah":50,"verses":[10],"references":[{"surah":50,"verses":[10]}],"verseLabel":"ق: 10","question":"ما سر تخصيص النخل بالذكر بعد الجنات والحب؟","answer":"هو تخصيص للنوع بعد دخوله في عموم الجنات، لإبراز ما للنخل من فضل ومنافع كثيرة. فتجتمع قيمته في غذاء الناس مع جمال خلقته وتنوع ما ينتفعون به منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص121، تحت عنوان «توجيه عطف الخاص على العام»","url":""}]},{"id":"s50-28","number":28,"surah":50,"verses":[10],"references":[{"surah":50,"verses":[10]}],"verseLabel":"ق: 10","question":"ما دلالة وصف النخل بـ﴿بَاسِقَاتٍ﴾؟","answer":"البسوق هو الطول والارتفاع، فيلفت الوصف إلى جمال هيئة النخل وعظمة صنعته. وتلك القامة الممتدة شاهد على العناية والتقدير، مع ما تحمله من الثمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص121–122، تحت عنوان «سر التقييد بالحال المفردة»","url":""}]},{"id":"s50-29","number":29,"surah":50,"verses":[10],"references":[{"surah":50,"verses":[10]}],"verseLabel":"ق: 10","question":"ما سر التعبير بـ﴿لَهَا طَلْعٌ نَضِيدٌ﴾، وما الذي يضيفه وصف الطلع بالنضيد؟","answer":"النضيد متراكب منضم بعضه إلى بعض بانتظام، فيصف هيئة الطلع قبل تفرقه. وتظهر في هذا الضم دقة الصنعة وحسن الترتيب مع غزارة ما يخرج من الثمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص122–123، تحت عنوان «فائدة الوصف بنضيد»","url":""}]},{"id":"s50-30","number":30,"surah":50,"verses":[11],"references":[{"surah":50,"verses":[11]}],"verseLabel":"ق: 11","question":"لماذا قيل ﴿رِزْقًا لِلْعِبَادِ﴾ بدل «رزقًا لكم»؟","answer":"لأن لفظ العباد يعم المخاطبين وسائر من ينتفعون بالنبات والماء، ويذكّر الجميع بعبوديتهم للرازق؛ فتحول العبارة النعمة المشاهدة إلى دعوة للشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص127، تحت عنوان «نكتة صيغة الجمع»","url":""}]},{"id":"s50-31","number":31,"surah":50,"verses":[11],"references":[{"surah":50,"verses":[11]}],"verseLabel":"ق: 11","question":"ما دلالة وصف البلدة بـ﴿ميتًا﴾ في الاستدلال على البعث؟","answer":"يصور اليبس والخلو من النبات بالموت، ثم يجعل خروج النبات إحياءً ظاهرًا للعيان. فتقرب الاستعارة دليل البعث من مشهد يتكرر أمام الناس، وتقرر أن القادر على هذا الإحياء قادر على إحياء الموتى.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص128، تحت عنوان «بلاغة الاستعارة في الصفة»","url":""}]},{"id":"s50-32","number":32,"surah":50,"verses":[11],"references":[{"surah":50,"verses":[11]}],"verseLabel":"ق: 11","question":"ما سر التعبير بـ﴿كَذَلِكَ الْخُرُوجُ﴾ بدل «كذلك البعث»؟","answer":"الخروج أنسب بالدليل السابق؛ إذ يشبه خروج الأجساد من الأرض بخروج النبات منها. أما البعث فيبرز الإرسال والإثارة، فجاء الخروج هنا ليربط النتيجة بالمشهد الذي أقيمت به الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص130، تحت عنوان «بلاغة ذكر الخروج»","url":""}]},{"id":"s50-33","number":33,"surah":50,"verses":[12],"references":[{"surah":50,"verses":[12]}],"verseLabel":"ق: 12","question":"ما سر تقديم قوم نوح في سلسلة الأمم المكذبة؟","answer":"قدم قوم نوح لأنهم أول الأقوام المذكورين تكذيبًا لرسولهم، فجرى العرض بحسب السبق في هذا المقام. وافتتاح القائمة بهم يضع تكذيب المخاطبين في سلسلة معروفة العواقب.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص135، تحت عنوان «نكتة تقديم ﴿قوم نوح﴾»","url":""}]},{"id":"s50-34","number":34,"surah":50,"verses":[13],"references":[{"surah":50,"verses":[13]}],"verseLabel":"ق: 13","question":"ما سر التعبير بـ﴿إِخْوَانُ لُوطٍ﴾ هنا، مع ورود «قوم لوط» في مواضع أخرى؟","answer":"التعبير بالأخوة، بدل الاكتفاء باسم القوم، يبرز شدة الملازمة والصلات بينهم وبين لوط، فتشتد دلالة الجحود مع القرب. ويذكر المبحث احتمال أخوة المعاشرة، واحتمال صلة النسب من جهة المصاهرة، فلا يلزم منها أنهم إخوته لأب وأم.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص137، تحت عنوان «دلالة التعبير بإخوان لوط»","url":""}]},{"id":"s50-35","number":35,"surah":50,"verses":[14],"references":[{"surah":50,"verses":[14]}],"verseLabel":"ق: 14","question":"لماذا ذُكر فرعون وحده من غير قومه في عداد المكذبين؟","answer":"لأنه رأس طغيان قومه وصاحب السلطان الذي قادهم، فكان ذكره يغني عنهم ويحمّله تبعة الصد عن الحق، مع أن العذاب شمل أتباعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص136، تحت عنوان «دلالة ذكر فرعون دون قومه»","url":""}]},{"id":"s50-117","number":117,"surah":50,"verses":[14],"references":[{"surah":50,"verses":[14]}],"verseLabel":"ق: 14","question":"لماذا نُسب قوم سبأ إلى ﴿تُبَّعٍ﴾؟","answer":"لأن تُبّعًا لقب ملكهم المعروف، فنسبوا إليه ليدل الاسم على الأمة التي تبعته واجتمعت تحت سلطانه؛ وفي الإضافة إيجاز يستحضر القوم وملكهم وتاريخ تكذيبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص138، تحت عنوان «دلالة الإضافة إلى ﴿تبع﴾»","url":""}]},{"id":"s50-36","number":36,"surah":50,"verses":[14],"references":[{"surah":50,"verses":[14]}],"verseLabel":"ق: 14","question":"ماذا يفيد قوله عن الأمم السابقة ﴿كُلٌّ كَذَّبَ الرُّسُلَ﴾؟","answer":"يفيد أن كل أمة من المذكورين شاركت في أصل التكذيب، مع اختلاف أزمانها ورسلها؛ فتتكرر الجريمة ويستحق الجميع الوعيد نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص139، تحت عنوان «دلالة استعمال ﴿كل﴾ منونًا»","url":""}]},{"id":"s50-37","number":37,"surah":50,"verses":[15],"references":[{"surah":50,"verses":[15]}],"verseLabel":"ق: 15","question":"ما دلالة الاستفهام في ﴿أَفَعَيِينَا بِالْخَلْقِ الْأَوَّلِ﴾؟","answer":"هو إنكار لتوهم العجز عن الإعادة؛ فالخلق الأول واقع يشهد بتمام القدرة، ومن لم يعجز عن البدء لا يعجز عن بعث الناس بعد موتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص143، تحت عنوان «غرض الاستفهام وبلاغته»","url":""}]},{"id":"s50-118","number":118,"surah":50,"verses":[15],"references":[{"surah":50,"verses":[15]}],"verseLabel":"ق: 15","question":"لماذا عُرّف ﴿الْخَلْقِ الْأَوَّلِ﴾؟","answer":"لأنه الخلق المعهود المشاهد الذي يعرفونه في أنفسهم والعالم من حولهم؛ فالتعريف يحيلهم إلى دليل حاضر لا يمكن إنكاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص144، تحت عنوان «دلالة التعبير بالخلق معرفًا»","url":""}]},{"id":"s50-38","number":38,"surah":50,"verses":[15],"references":[{"surah":50,"verses":[15]}],"verseLabel":"ق: 15","question":"كيف صوّر قوله ﴿فِي لَبْسٍ مِنْ خَلْقٍ جَدِيدٍ﴾ إنكارهم للبعث؟","answer":"صوّر الاشتباه كأنه وعاء يحيط بهم، ثم استعير اللبس لاختلاط الأمر عليهم؛ فهم لا يملكون حجة، وإنما غمرتهم حيرة صنعها استبعادهم للخلق الجديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص146–147، تحت عنوان «بلاغة التعبير بقوله: ﴿في لبس من خلق جديد﴾»","url":""}]},{"id":"s50-39","number":39,"surah":50,"verses":[16],"references":[{"surah":50,"verses":[16]}],"verseLabel":"ق: 16","question":"لماذا خُصّ الإنسان بالذكر في قوله ﴿وَلَقَدْ خَلَقْنَا الْإِنْسَانَ﴾؟","answer":"لأنه المقصود بالمحاسبة والبعث، ولأن تكوينه من أعجب دلائل الخلق؛ فتخصيصه يمهد للحديث عن علم الله بباطنه ومراقبة أقواله وأعماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص150–151، تحت عنوان «توجيه تخصيص الإنسان بالذكر»","url":""}]},{"id":"s50-40","number":40,"surah":50,"verses":[16],"references":[{"surah":50,"verses":[16]}],"verseLabel":"ق: 16","question":"لماذا عُبّر عما تحدّث به النفس بأنه ﴿تُوَسْوِسُ﴾؟","answer":"لأن الوسوسة صوت خفي متكرر، فاستعيرت للخواطر الدقيقة التي تتردد في النفس ولا يسمعها أحد؛ وفي اللفظ تصوير لدقة علم الله حتى بأخفى حديث باطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص152، تحت عنوان «بلاغة الاستعارة في التعبير بالوسوسة»","url":""}]},{"id":"s50-119","number":119,"surah":50,"verses":[16],"references":[{"surah":50,"verses":[16]}],"verseLabel":"ق: 16","question":"لماذا أعقب علم الله بوسوسة النفس قوله ﴿وَنَحْنُ أَقْرَبُ إِلَيْهِ﴾؟","answer":"ليقرر أن علمه لا يقف عند الخواطر، بل هو إحاطة لا يخفى معها شيء من حال الإنسان؛ فالعطف ينقل من العلم بسر النفس إلى تأكيد شمول المراقبة والقرب العلمي.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص154، تحت عنوان «دلالة واو ﴿ونحن﴾»","url":""}]},{"id":"s50-41","number":41,"surah":50,"verses":[16],"references":[{"surah":50,"verses":[16]}],"verseLabel":"ق: 16","question":"لماذا اختير ﴿حَبْلِ الْوَرِيدِ﴾ لتصوير القرب من الإنسان؟","answer":"لأن الوريد شديد الاتصال بالحياة ومن أقرب ما في البدن إلى صاحبه، فتصور العبارة إحاطة علم الله بالإنسان تصويرًا لا يترك خاطرًا أو حالًا خارج المراقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص156، تحت عنوان «لطيفة التصوير بـ﴿حبل الوريد﴾»","url":""}]},{"id":"s50-42","number":42,"surah":50,"verses":[17],"references":[{"surah":50,"verses":[17]}],"verseLabel":"ق: 17","question":"ما سر التعبير بالمثنى في ﴿الْمُتَلَقِّيَانِ﴾؟","answer":"التثنية تبين توزيع التلقي والكتابة على جهة اليمين وجهة الشمال. ويعرض المبحث أن المراد قد يكون ملكين، أو طائفتين تتعاقبان على الوظيفة؛ فالمقصود بيان إحكام الحفظ وتوزيع مهمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص160، تحت عنوان «فائدة تثنية ﴿المتلقيان﴾»","url":""}]},{"id":"s50-43","number":43,"surah":50,"verses":[17],"references":[{"surah":50,"verses":[17]}],"verseLabel":"ق: 17","question":"ما سر تقديم ﴿عَنِ الْيَمِينِ﴾ على ﴿عَنِ الشِّمَالِ﴾؟","answer":"جرى التقديم على تشريف اليمين وتقديمها على الشمال في نظائرها، مع تقرير أن كلا الملكين قائم بوظيفته. فلا يلغي فضل الجهة كمال الحفظ في الجانبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص161–162، تحت عنوان «علة تقديم ﴿اليمين﴾»","url":""}]},{"id":"s50-44","number":44,"surah":50,"verses":[17],"references":[{"surah":50,"verses":[17]}],"verseLabel":"ق: 17","question":"ما سر إفراد ﴿قَعِيدٌ﴾ مع أن المذكور ملكان عن اليمين وعن الشمال؟","answer":"يدل المفرد على أن كل واحد منهما قعيد، فيقدر: عن اليمين قعيد وعن الشمال قعيد. ويذكر المبحث أيضًا أن صيغة فعيل قد تستعمل للواحد والمتعدد؛ والمقصود ملازمة الحفظ وتأكيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص162، تحت عنوان «بلاغة إفراد ﴿قعيد﴾ وتنكيره»","url":""}]},{"id":"s50-45","number":45,"surah":50,"verses":[18],"references":[{"surah":50,"verses":[18]}],"verseLabel":"ق: 18","question":"لماذا عُبّر عن كلام الإنسان بقوله ﴿يَلْفِظُ﴾؟","answer":"لأن أصل اللفظ طرح الشيء من الفم، فاستعير لخروج الكلام ليصوره كشيء يخرجه الإنسان ثم لا يستطيع استرداده، وتأتي صيغة المضارع لاستحضار كل مرة يتكلم فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص164، تحت عنوان «دلالة مضارعة فعل اللفظ»","url":""}]},{"id":"s50-120","number":120,"surah":50,"verses":[18],"references":[{"surah":50,"verses":[18]}],"verseLabel":"ق: 18","question":"ماذا يفيد قوله ﴿مِنْ قَوْلٍ﴾ في تسجيل كلام الإنسان؟","answer":"يفيد العموم، فلا تخرج كلمة من جنس القول عن التسجيل مهما صغرت؛ فيستحضر السامع رقابة تلازم كلامه كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص164، تحت عنوان «دلالة قوله: ﴿من قول﴾»","url":""}]},{"id":"s50-46","number":46,"surah":50,"verses":[18],"references":[{"surah":50,"verses":[18]}],"verseLabel":"ق: 18","question":"ماذا يوحي تنكير ﴿رَقِيبٌ﴾ في وصف الملك الملازم للإنسان؟","answer":"يوحي بأن على كل إنسان رقيبًا من جنس عظيم الشأن، حاضرًا لا يفوته قول ولا عمل. فالتنكير يفخم وظيفة المراقبة ويجعل استحضارها باعثًا على الحذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص166–167، تحت عنوان «بلاغة استعمال لفظ الرقيب منكرًا»","url":""}]},{"id":"s50-121","number":121,"surah":50,"verses":[18],"references":[{"surah":50,"verses":[18]}],"verseLabel":"ق: 18","question":"ماذا يضيف وصف الملك بأنه ﴿عَتِيدٌ﴾؟","answer":"يدل على أنه حاضر مهيأ ملازم لأداء مهمته، لا يغيب ولا يتأخر عن تسجيل ما يصدر من الإنسان. فالوصف يجمع الحضور والاستعداد.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص167، تحت عنوان «نكتة الوصف بالعتيد»","url":""}]},{"id":"s50-47","number":47,"surah":50,"verses":[19],"references":[{"surah":50,"verses":[19]}],"verseLabel":"ق: 19","question":"ما سر إفراد ﴿سَكْرَةُ الْمَوْتِ﴾ هنا، مع ورود الحديث عن «سكرات الموت» في الاستعمال؟","answer":"الإفراد يبرز السكرة الواحدة في شدتها وهولها، حتى كأن كل سكرة منها تستحق أن تذكر مستقلة. فهو للتفخيم والتهويل، ولا ينفي تعاقب سكرات عند الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص172، تحت عنوان «نكتة إفراد ﴿سكرة﴾»","url":""}]},{"id":"s50-48","number":48,"surah":50,"verses":[19],"references":[{"surah":50,"verses":[19]}],"verseLabel":"ق: 19","question":"لماذا قيل ﴿كُنْتَ مِنْهُ تَحِيدُ﴾ بالماضي، مع أن الإنسان يظل يحاول الحيد عن الموت؟","answer":"يستحضر الماضي طول محاولته في الدنيا كأنها صفحة أغلقت، بينما جاء حضور سكرة الموت واقعًا لا يمكن دفعه. فتتقابل محاولة الفرار الماضية مع الحقيقة الحاضرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص175، تحت عنوان «دلالة المغايرة بين الماضي والمضارع»","url":""}]},{"id":"s50-49","number":49,"surah":50,"verses":[20],"references":[{"surah":50,"verses":[20]}],"verseLabel":"ق: 20","question":"ما سر بناء ﴿نُفِخَ فِي الصُّورِ﴾ للمفعول مع عظمة الحدث؟","answer":"وجه البناء للمفعول الاهتمام إلى النفخ نفسه وما يحدثه من الانتقال إلى الحياة بعد الموت والجزاء، دون أن يكون تعيين النافخ هو المقصود. وصيغة الماضي تجعل الحدث المستقبل في حكم الواقع المحقق.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص178، تحت عنوان «نكتة التعبير بالفعل ﴿نفخ﴾»","url":""}]},{"id":"s50-50","number":50,"surah":50,"verses":[20],"references":[{"surah":50,"verses":[20]}],"verseLabel":"ق: 20","question":"ماذا تفيد إضافة اليوم إلى الوعيد في ﴿ذَلِكَ يَوْمُ الْوَعِيدِ﴾؟","answer":"تجعل اليوم معروفًا بأنه الموعد الذي يتحقق فيه كل ما هُدد به المكذبون، فتربط زمن القيامة مباشرة بإنجاز الوعيد وتفخيم هوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص179–180، تحت عنوان «دلالة التعبير بالإضافة»","url":""}]},{"id":"s50-122","number":122,"surah":50,"verses":[20],"references":[{"surah":50,"verses":[20]}],"verseLabel":"ق: 20","question":"لماذا اكتفى بقوله ﴿يَوْمُ الْوَعِيدِ﴾ ولم يذكر تفاصيل ما وُعِدوا به؟","answer":"لأن لفظ الوعيد يجمع كل ما سبق من التهديدات ويستحضرها دفعة واحدة؛ فالإيجاز أبلغ في التهويل، إذ يترك الذهن يستعيد صور العذاب المتعددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص180، تحت عنوان «بلاغة الاكتفاء بذكر الوعيد»","url":""}]},{"id":"s50-51","number":51,"surah":50,"verses":[19,21],"references":[{"surah":50,"verses":[19,21]}],"verseLabel":"ق: 19، 21","question":"ما الصورة في قوله ﴿وَجَاءَتْ سَكْرَةُ الْمَوْتِ﴾؟","answer":"صُورت سكرة الموت كشيء مقبل يصل إلى الإنسان، فتتحول الحالة المعنوية إلى حقيقة مهاجمة لا يستطيع ردها أو الابتعاد عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص170، تحت عنوان «بلاغة الاستعارة في المجيء»","url":""}]},{"id":"s50-123","number":123,"surah":50,"verses":[19,21],"references":[{"surah":50,"verses":[19,21]}],"verseLabel":"ق: 19، 21","question":"لماذا عُبّر عن مجيء سكرة الموت بالماضي مع أنه مشهد مستقبل؟","answer":"لتنزيل المستقبل منزلة الواقع المتحقق؛ فالموت آت لا محالة، والتعبير بالماضي يقرب صورته ويؤكد وقوعه حتى كأنه حدث وانقضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص170، تحت عنوان «بلاغة الاستعارة في الفعل الماضي»","url":""}]},{"id":"s50-124","number":124,"surah":50,"verses":[19,21],"references":[{"surah":50,"verses":[19,21]}],"verseLabel":"ق: 19، 21","question":"لماذا اختير فعل ﴿جَاءَتْ﴾ في قوله ﴿وَجَاءَتْ كُلُّ نَفْسٍ﴾؟","answer":"ليصور حضور كل نفس إلى موقف الحساب بنفسها ومعها سائق وشهيد؛ فالمجيء يبرز انقيادها وانتقالها الحتمي إلى الموقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص180، تحت عنوان «بلاغة اختيار مادة المجيء»","url":""}]},{"id":"s50-52","number":52,"surah":50,"verses":[21],"references":[{"surah":50,"verses":[21]}],"verseLabel":"ق: 21","question":"ماذا يقرر التعبير بـ﴿كُلُّ نَفْسٍ﴾ في مشهد الحساب؟","answer":"يقرر شمول الحضور لجميع النفوس بلا استثناء، بارة كانت أو فاجرة؛ فلا تختفي نفس ولا تستثنى من السوق والشهادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص180–181، تحت عنوان «فائدة التعبير بقوله: ﴿كل نفس﴾»","url":""}]},{"id":"s50-125","number":125,"surah":50,"verses":[21],"references":[{"surah":50,"verses":[21]}],"verseLabel":"ق: 21","question":"ماذا تفيد المعية في قوله ﴿مَعَهَا سَائِقٌ وَشَهِيدٌ﴾؟","answer":"تفيد ملازمة السائق والشهيد للنفس في موقفها؛ أحدهما يقودها إلى المحشر والآخر يشهد عليها، فتبدو محاطة بما يمنع الفرار والإنكار.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص182، تحت عنوان «غرض الإضافة في ﴿معها﴾»","url":""}]},{"id":"s50-126","number":126,"surah":50,"verses":[21],"references":[{"surah":50,"verses":[21]}],"verseLabel":"ق: 21","question":"لماذا سُمّي الملك المصاحب للنفس ﴿سَائِقًا﴾؟","answer":"لأنه يدفعها إلى موقف الحساب ويقودها إليه قسرًا، وفي لفظ السوق تصوير لانتفاء الاختيار وسرعة الانتقال إلى المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص182، تحت عنوان «بلاغة استعمال لفظ السائق»","url":""}]},{"id":"s50-53","number":53,"surah":50,"verses":[22],"references":[{"surah":50,"verses":[22]}],"verseLabel":"ق: 22","question":"ما الصورة في قوله ﴿فَكَشَفْنَا عَنْكَ غِطَاءَكَ﴾؟","answer":"صُور الانتقال من الغفلة إلى اليقين بكشف غطاء يحجب العين؛ فإذا زال ظهر ما كان مستورًا من حقائق البعث والحساب ظهورًا لا مجال لإنكاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص189، تحت عنوان «بلاغة الاستعارة في كشف الغطاء»","url":""}]},{"id":"s50-127","number":127,"surah":50,"verses":[22],"references":[{"surah":50,"verses":[22]}],"verseLabel":"ق: 22","question":"لماذا صُورت الغفلة عن الآخرة بأنها ﴿غِطَاءٌ﴾؟","answer":"لأنها تحجب البصيرة عن إدراك الحق كما يحجب الغطاء العين عن رؤية المحسوس، حتى إذا جاءت القيامة زال الحاجب وبقيت الحقيقة مكشوفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص190، تحت عنوان «بلاغة الاستعارة في الغطاء»","url":""}]},{"id":"s50-54","number":54,"surah":50,"verses":[22],"references":[{"surah":50,"verses":[22]}],"verseLabel":"ق: 22","question":"لماذا قيل ﴿فَبَصَرُكَ الْيَوْمَ حَدِيدٌ﴾ ولم يقل «فنظرك»؟","answer":"لأن البصر يدل على قوة الرؤية التي انكشفت بها حقائق الآخرة، أما النظر فقد يقع دون إبصار. فاللفظ يقرر رؤية يقينية لا مجرد توجيه العين.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص191، تحت عنوان «لطيفة في استعمال لفظ ﴿البصر﴾»","url":""}]},{"id":"s50-128","number":128,"surah":50,"verses":[22],"references":[{"surah":50,"verses":[22]}],"verseLabel":"ق: 22","question":"ماذا يوحي وصف البصر يوم القيامة بأنه ﴿حَدِيدٌ﴾؟","answer":"يوحي بحدة نافذة لا يخفى معها شيء، وقد نُكّر الوصف لتفخيم هذه القوة المفاجئة بعد غفلة الدنيا؛ فالمكذب يرى الحقيقة شاخصة أمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص191–192، تحت عنوان «لطيفة صيغة ﴿حديد﴾ وتنكيره»","url":""}]},{"id":"s50-55","number":55,"surah":50,"verses":[23],"references":[{"surah":50,"verses":[23]}],"verseLabel":"ق: 23","question":"إلام يشير قول القرين ﴿هَذَا مَا لَدَيَّ عَتِيدٌ﴾؟","answer":"يحتمل أن يشير إلى الشخص الكافر الذي أحضره قرينه، أو إلى سجل أعماله المهيأ؛ وفي الوجهين يقدم القرين ما لديه حاضرًا كاملًا أمام الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص196، تحت عنوان «تعيين مرجع اسم الإشارة»","url":""}]},{"id":"s50-129","number":129,"surah":50,"verses":[23],"references":[{"surah":50,"verses":[23]}],"verseLabel":"ق: 23","question":"ماذا يفيد تنكير ﴿عَتِيدٌ﴾ في قول القرين ﴿هَذَا مَا لَدَيَّ عَتِيدٌ﴾؟","answer":"يفيد تمام الحضور والاستعداد مع تفخيم شأن ما أُحضر؛ فلا نقص في الشخص أو السجل المقدم، ولا غياب لما تقوم به الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص197، تحت عنوان «دلالة تنكير ﴿عتيد﴾»","url":""}]},{"id":"s50-56","number":56,"surah":50,"verses":[24],"references":[{"surah":50,"verses":[24]}],"verseLabel":"ق: 24","question":"ما دلالة الأمر للمثنى في ﴿أَلْقِيَا فِي جَهَنَّمَ﴾، ومن المخاطبان؟","answer":"الظاهر أن الخطاب للملكين الموكلين بالكافر: السائق والشهيد. ويذكر المبحث وجهًا آخر على استعمال العرب خطاب الاثنين للواحد، يكون فيه التثنية مؤكدة للأمر؛ فلا ينحصر التوجيه في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص201، تحت عنوان «توجيه تثنية المخاطب»","url":""}]},{"id":"s50-57","number":57,"surah":50,"verses":[24],"references":[{"surah":50,"verses":[24]}],"verseLabel":"ق: 24","question":"ما سر الجمع بين وصفي ﴿كَفَّارٍ عَنِيدٍ﴾؟","answer":"كفار مبالغة في الكفر والإصرار عليه، وعنيد يضيف معاندة الحق مع وضوحه. فالجمع يبين رسوخ الرفض ومكابرة صاحبه، ويهيئ لما يأتي من أفعال المنع والاعتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص202–203، تحت عنوان «دلالة التعبير بالمبالغة»","url":""}]},{"id":"s50-58","number":58,"surah":50,"verses":[25],"references":[{"surah":50,"verses":[25]}],"verseLabel":"ق: 25","question":"ما سر ترتيب الصفات في ﴿مَنَّاعٍ لِلْخَيْرِ مُعْتَدٍ مُرِيبٍ﴾؟","answer":"تتدرج الصفات من منع الخير إلى تجاوز الحد ثم إثارة الريب. ويعرض المبحث ترتيبًا يبدأ بالكفر والضلال، ثم العناد، ثم منع الخير، فالاعتداء وإيقاع غيره في الشك؛ فتتكامل صورة الفساد في نفسه وأثره على الآخرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص204، تحت عنوان «نكتة ترتيب الأوصاف»","url":""}]},{"id":"s50-59","number":59,"surah":50,"verses":[25],"references":[{"surah":50,"verses":[25]}],"verseLabel":"ق: 25","question":"لماذا قيل ﴿مَنَّاعٍ لِلْخَيْرِ﴾ بصيغة المبالغة؟","answer":"لتصوير رسوخ المنع وتكرره؛ فهو لا يمنع خيرًا عارضًا مرة واحدة، بل اعتاد صد الناس عن الإيمان والمال والإحسان وبالغ فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص202–203، تحت عنوان «دلالة التعبير بالمبالغة»","url":""}]},{"id":"s50-130","number":130,"surah":50,"verses":[25],"references":[{"surah":50,"verses":[25]}],"verseLabel":"ق: 25","question":"ماذا يشمل تعريف ﴿الْخَيْرِ﴾ في وصف ﴿مَنَّاعٍ لِلْخَيْرِ﴾؟","answer":"يشمل أجناس الخير كلها، وفي مقدمتها الإيمان ثم المال وأعمال البر؛ فيكشف أن منعه لم يكن محصورًا في باب واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص203، تحت عنوان «معنى تعريف ﴿الخير﴾»","url":""}]},{"id":"s50-60","number":60,"surah":50,"verses":[25],"references":[{"surah":50,"verses":[25]}],"verseLabel":"ق: 25","question":"ما الفرق بين ﴿مُعْتَدٍ﴾ و﴿مُرِيبٍ﴾، وما الذي يضيفه اجتماعهما؟","answer":"المعتدي يتجاوز الحدود في القول والفعل، والمريب يوقع الشك والريبة في الحق أو يتلبس بها. فاجتماعهما يضيف إلى أذى الاعتداء إفساد التصور وإثارة الشبهات، ويبين تعدد جهات جنايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص203، تحت عنوان «فائدة الوصف بـ﴿معتد مريب﴾»","url":""}]},{"id":"s50-61","number":61,"surah":50,"verses":[26],"references":[{"surah":50,"verses":[26]}],"verseLabel":"ق: 26","question":"ما سر التعبير بالجعل في ﴿جَعَلَ مَعَ اللَّهِ إِلَهًا آخَرَ﴾؟","answer":"التعبير بالجعل يصور اتخاذه إلهًا آخر على أنه فعل صدر عن اختياره واعتقاده الفاسد، لا حقيقة ثابتة لذلك المعبود. وهو من صرف الفطرة عن التوحيد إلى الشرك، فتظهر مسؤوليته عن هذا الانحراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص205، تحت عنوان «دلالة استعمال مادة الفعل»","url":""}]},{"id":"s50-62","number":62,"surah":50,"verses":[26],"references":[{"surah":50,"verses":[26]}],"verseLabel":"ق: 26","question":"لماذا تكرر الأمر بالإلقاء في قوله ﴿فَأَلْقِيَاهُ فِي الْعَذَابِ الشَّدِيدِ﴾؟","answer":"لزيادة الإهانة والتنكيل بعد الأمر الأول بإلقائه في جهنم؛ فالتكرار يصعد المشهد من إدخاله النار إلى مباشرة أشد ألوان عذابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص207، تحت عنوان «نكتة تكرار الأمر بالإلقاء»","url":""}]},{"id":"s50-131","number":131,"surah":50,"verses":[26],"references":[{"surah":50,"verses":[26]}],"verseLabel":"ق: 26","question":"ماذا يضيف وصف العذاب بأنه ﴿شَدِيدٌ﴾؟","answer":"يقرر أنه عذاب بالغ القوة لا تخفيف فيه ولا راحة، ويبرز تناسب شدته مع عناد الكافر ومبالغته في الكفر والصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص208، تحت عنوان «فائدة الوصف بـ﴿الشديد﴾»","url":""}]},{"id":"s50-63","number":63,"surah":50,"verses":[27],"references":[{"surah":50,"verses":[27]}],"verseLabel":"ق: 27","question":"ما سر مجيء قول القرين بلا واو في ﴿قَالَ قَرِينُهُ رَبَّنَا مَا أَطْغَيْتُهُ﴾؟","answer":"جاء القول جوابًا مستأنفًا لاتهام مقدر من الكافر لقرينه، كأنه قال: رب إنه أطغاني، فقال القرين: ما أطغيته. فالفصل يرسم حوار الخصومة من غير حاجة إلى التصريح بكل ما حذفه السياق لدلالة الجواب عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص210، تحت عنوان «علة فصل الجملة»","url":""}]},{"id":"s50-64","number":64,"surah":50,"verses":[27],"references":[{"surah":50,"verses":[27]}],"verseLabel":"ق: 27","question":"لماذا أكد القرين نفي إطغائه لصاحبه بقوله ﴿مَا أَطْغَيْتُهُ﴾؟","answer":"ليدفع عن نفسه مسؤولية إجباره على الطغيان، ويقرر أن صاحبه اختار الضلال بإرادته؛ فالقرين وسوس وزين ولم يسلبه الاختيار.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص212، تحت عنوان «دلالة التوكيد على النفي بالفعل»","url":""}]},{"id":"s50-132","number":132,"surah":50,"verses":[27],"references":[{"surah":50,"verses":[27]}],"verseLabel":"ق: 27","question":"ما دلالة قول القرين ﴿مَا أَطْغَيْتُهُ﴾ مع أنه كان يوسوس له؟","answer":"الإطغاء هنا مجاز عن التسبب في الطغيان؛ فنفيه يعني أنه لم يخلق الضلال فيه ولم يجبره، وإن كان قد دعاه وزينه له.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص212، تحت عنوان «بلاغة المجاز المرسل»","url":""}]},{"id":"s50-65","number":65,"surah":50,"verses":[27],"references":[{"surah":50,"verses":[27]}],"verseLabel":"ق: 27","question":"ما الصورة في قوله عن المكذب ﴿كَانَ فِي ضَلَالٍ﴾؟","answer":"صُور الضلال كحيز يحيط به ويستغرقه، فلا يرى منفذًا إلى الهدى؛ وهي صورة لتمكن الانحراف منه لا لوقوعه في خطأ عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص213–214، تحت عنوان «بلاغة استعارة ﴿في ضلال﴾»","url":""}]},{"id":"s50-133","number":133,"surah":50,"verses":[27],"references":[{"surah":50,"verses":[27]}],"verseLabel":"ق: 27","question":"لماذا وُصف ضلاله بأنه ﴿بَعِيدٍ﴾؟","answer":"لتصوير شدة مفارقته للحق وصعوبة رجوعه، كمن أوغل في مكان بعيد عن الطريق؛ فالبعد يقيس عمق الانحراف ورسوخه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص214–215، تحت عنوان «بلاغة وصف الضلال بالبعد»","url":""}]},{"id":"s50-66","number":66,"surah":50,"verses":[28],"references":[{"surah":50,"verses":[28]}],"verseLabel":"ق: 28","question":"ماذا يفيد قوله ﴿قَدَّمْتُ إِلَيْكُمْ بِالْوَعِيدِ﴾ بدل «أنذرتكم»؟","answer":"يفيد أن الوعيد سبقهم ووصل إليهم قبل الحساب، فقامت به الحجة ولم يفاجؤوا بالعقوبة. وفي التقديم معنى الادخار لما يلقونه في موعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص220، تحت عنوان «معنى التقديم»","url":""}]},{"id":"s50-67","number":67,"surah":50,"verses":[29],"references":[{"surah":50,"verses":[29]}],"verseLabel":"ق: 29","question":"ما دلالة بناء ﴿مَا يُبَدَّلُ الْقَوْلُ لَدَيَّ﴾ للمفعول؟","answer":"حذف الفاعل يعمم نفي القدرة على التبديل، فلا يغير القول أحد أيًا كان. ويتجه الاهتمام إلى ثبات الحكم نفسه وانقطاع مطمع المتخاصمين في تغييره.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص222، تحت عنوان «فائدة البناء للمفعول»","url":""}]},{"id":"s50-68","number":68,"surah":50,"verses":[29],"references":[{"surah":50,"verses":[29]}],"verseLabel":"ق: 29","question":"كيف ينفي قوله ﴿وَمَا أَنَا بِظَلَّامٍ لِلْعَبِيدِ﴾ كل ظلم مع أنه نفى صيغة المبالغة؟","answer":"لأن ظلم الله لعباده الكثيرين لو وقع لتكرر بتعددهم فكان ظلمًا عظيمًا؛ فنفي ﴿ظلّام﴾ ينفي هذا اللازم وينزه الله عن أصل الظلم كله، قليلًا أو كثيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص225، تحت عنوان «نكتة صيغة المبالغة»","url":""}]},{"id":"s50-69","number":69,"surah":50,"verses":[30],"references":[{"surah":50,"verses":[30]}],"verseLabel":"ق: 30","question":"ما غرض سؤال جهنم ﴿هَلِ امْتَلَأْتِ﴾؟","answer":"ليس سؤال جهل، بل تقرير لوعد الله وتهويل للمشهد وإظهار لسعة جهنم وهي تستقبل أفواج المجرمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص230، تحت عنوان «غرض التعبير بأسلوب الاستفهام»","url":""}]},{"id":"s50-134","number":134,"surah":50,"verses":[30],"references":[{"surah":50,"verses":[30]}],"verseLabel":"ق: 30","question":"هل سؤال جهنم وجوابها في ﴿هَلِ امْتَلَأْتِ وَتَقُولُ هَلْ مِنْ مَزِيدٍ﴾ حقيقيان؟","answer":"الأصل حملهما على الحقيقة؛ فالله ينطق جهنم فتجيب بما يشاء، ولا يمنع العقل كلامها في الآخرة. وحملهما على التمثيل ممكن لكنه ليس لازمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص231، تحت عنوان «حقيقة السؤال والجواب»","url":""}]},{"id":"s50-70","number":70,"surah":50,"verses":[30],"references":[{"surah":50,"verses":[30]}],"verseLabel":"ق: 30","question":"ماذا يفيد استفهام جهنم ﴿هَلْ مِنْ مَزِيدٍ﴾؟","answer":"يصور شدة طلبها للمزيد وعدم امتلائها بمن ألقي فيها، فيزيد المشهد تخويفًا وتهويلًا، سواء كان السؤال طلبًا للمزيد أو تقريرًا لعدم بقاء موضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص232، تحت عنوان «غرض الاستفهام وبلاغته»","url":""}]},{"id":"s50-71","number":71,"surah":50,"verses":[30,35],"references":[{"surah":50,"verses":[30,35]}],"verseLabel":"ق: 30، 35","question":"ماذا يوحي تنكير ﴿مَزِيدٌ﴾ في نعيم الجنة: ﴿وَلَدَيْنَا مَزِيدٌ﴾؟","answer":"يوحي بنعيم زائد عظيم لا تحده رغبات أهل الجنة ولا يخطر لهم على بال؛ فالمزيد عند الله فوق كل ما يشاؤونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص250–251، تحت عنوان «غرض تنكير المبتدأ»","url":""}]},{"id":"s50-72","number":72,"surah":50,"verses":[31],"references":[{"surah":50,"verses":[31]}],"verseLabel":"ق: 31","question":"ماذا يصور التعبير بإزلاف الجنة في ﴿وَأُزْلِفَتِ الْجَنَّةُ لِلْمُتَّقِينَ﴾؟","answer":"يصور تقريب الجنة وإحضارها للمتقين إكرامًا لهم وتعجيلًا للبشرى، حتى تبدو مهيأة لاستقبالهم لا يقطعون إليها مسافة شاقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص235، تحت عنوان «دلالة استعمال مادة الإزلاف»","url":""}]},{"id":"s50-135","number":135,"surah":50,"verses":[31],"references":[{"surah":50,"verses":[31]}],"verseLabel":"ق: 31","question":"لماذا بُني فعل ﴿أُزْلِفَتِ الْجَنَّةُ﴾ للمفعول؟","answer":"لأن المقصود إبراز الجنة وهي تقرّب لهم، مع العلم بأن الله هو الذي قرّبها؛ فحذف الفاعل يعظم الحدث ويجعل المشهد كله موجهًا إلى تكريم المتقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص235، تحت عنوان «دلالة التعبير بالمبني للمفعول»","url":""}]},{"id":"s50-73","number":73,"surah":50,"verses":[30,31],"references":[{"surah":50,"verses":[30,31]}],"verseLabel":"ق: 30–31","question":"ماذا تضيف عبارة ﴿غَيْرَ بَعِيدٍ﴾ بعد تقريب الجنة للمتقين؟","answer":"تؤكد أن الوعد صار قريب التحقق والمنال، وتزيل من نفوسهم توهم التأخر أو المشقة؛ فكأن الجنة حاضرة أمامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص236–237، تحت عنوان «فائدة التقييد بـ﴿غير بعيد﴾»","url":""}]},{"id":"s50-74","number":74,"surah":50,"verses":[31],"references":[{"surah":50,"verses":[31]}],"verseLabel":"ق: 31","question":"ما سر إظهار وصف ﴿الْمُتَّقِينَ﴾ بدل أن يقال «لهم»؟","answer":"يبرز وصف التقوى سبب هذا الإكرام، فيربط قرب الجنة بما اتصف به أهلها من العمل والاتقاء. ويذكر المبحث أن الوصف قد يراد به أصحاب الدرجة العليا، أو جنس أهل الإيمان والعمل الصالح بحسب وجه التعريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص236، تحت عنوان «نوع تعريف ﴿المتقين﴾»","url":""}]},{"id":"s50-75","number":75,"surah":50,"verses":[32],"references":[{"surah":50,"verses":[32]}],"verseLabel":"ق: 32","question":"ماذا يكشف وصف المتقي بأنه ﴿أَوَّابٍ﴾؟","answer":"يكشف كثرة رجوعه إلى الله بالتوبة والطاعة كلما عرض له تقصير، فهو دائم الإنابة لا يصر على الذنب.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص239، تحت عنوان «دلالة التعبير بـ﴿أواب﴾»","url":""}]},{"id":"s50-136","number":136,"surah":50,"verses":[32],"references":[{"surah":50,"verses":[32]}],"verseLabel":"ق: 32","question":"ماذا يضيف وصف المتقي بأنه ﴿حَفِيظٍ﴾؟","answer":"يدل على شدة محافظته على حدود الله وعهوده وأوامره، فيجمع إلى كثرة الرجوع ثباتًا عمليًا يحفظ به الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص239، تحت عنوان «نكتة الوصف بـ﴿حفيظ﴾»","url":""}]},{"id":"s50-137","number":137,"surah":50,"verses":[32],"references":[{"surah":50,"verses":[32]}],"verseLabel":"ق: 32","question":"لماذا قُدّم وصف ﴿أَوَّابٍ﴾ على ﴿حَفِيظٍ﴾؟","answer":"لأن الرجوع إلى الله وتنقية القلب أساس يعقبه حفظ الحدود والاستقامة؛ فصلاح الباطن يسبق دوام العمل ويحمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص240، تحت عنوان «نكتة تقديم الوصف بـ﴿أواب﴾»","url":""}]},{"id":"s50-76","number":76,"surah":50,"verses":[33],"references":[{"surah":50,"verses":[33]}],"verseLabel":"ق: 33","question":"ما سر اختيار اسم ﴿الرَّحْمَنَ﴾ في مقام الخشية: ﴿مَنْ خَشِيَ الرَّحْمَنَ بِالْغَيْبِ﴾؟","answer":"استحضار الرحمة مع الخشية يبين أن الخوف ناشئ عن معرفة الله وتعظيمه، ولا تلغيه سعة رحمته. فتقترن خشية المتقي بالرجاء والأنس، ويأتي الاسم كذلك تعريضًا بمن أنكروا اسم الرحمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص244، تحت عنوان «بلاغة انتقاء اسم ﴿الرحمن﴾»","url":""}]},{"id":"s50-77","number":77,"surah":50,"verses":[33],"references":[{"surah":50,"verses":[33]}],"verseLabel":"ق: 33","question":"ماذا يضيف قوله ﴿بِالْغَيْبِ﴾ إلى خشية الرحمن؟","answer":"يبين أنهم يخشونه في خلواتهم وحين لا يراهم الناس، ويؤمنون بوعده ووعيده الغائبين؛ فهي خشية صادقة لا رهبة مظهرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص244–245، تحت عنوان «سر التقييد بالجار والمجرور»","url":""}]},{"id":"s50-138","number":138,"surah":50,"verses":[33],"references":[{"surah":50,"verses":[33]}],"verseLabel":"ق: 33","question":"لماذا جُمع بين خشية الرحمن بالغيب والمجيء بقلب منيب؟","answer":"لأن الخشية الباطنة تثمر قلبًا راجعًا إلى الله، فاجتمع أصل الشعور الإيماني وأثره الدائم في التوبة والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص245، تحت عنوان «معنى الواو ودلالتها»","url":""}]},{"id":"s50-139","number":139,"surah":50,"verses":[33],"references":[{"surah":50,"verses":[33]}],"verseLabel":"ق: 33","question":"ماذا يصور قوله عن صاحب القلب المنيب إنه ﴿جَاءَ﴾ به؟","answer":"يصور حضوره يوم القيامة مصاحبًا لقلبه السليم، وكأنه يحمل أثمن ما قدمه؛ فالقلب الذي عاش بالإنابة يبقى له عند اللقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص245، تحت عنوان «دلالة التعبير بالفعل ﴿جاء﴾»","url":""}]},{"id":"s50-78","number":78,"surah":50,"verses":[33],"references":[{"surah":50,"verses":[33]}],"verseLabel":"ق: 33","question":"ما دلالة تنكير ﴿قَلْبٍ مُنِيبٍ﴾؟","answer":"التنكير للتفخيم والتعظيم، إبرازًا لشأن القلب الذي يصلح به العمل. فالقلب المنيب ليس وصفًا عارضًا، بل مدار الاستقامة، والثبات عليه توفيق عظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص246، تحت عنوان «غرض تنكير لفظ القلب»","url":""}]},{"id":"s50-79","number":79,"surah":50,"verses":[34],"references":[{"surah":50,"verses":[34]}],"verseLabel":"ق: 34","question":"ما دلالة توجيه الأمر للجماعة في ﴿ادْخُلُوهَا بِسَلَامٍ﴾؟","answer":"يصور الجنة مهيأة لاستقبال المتقين جميعًا، ويعجل لهم البشارة والإكرام بالأمر المباشر بالدخول.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص247، تحت عنوان «بلاغة الأمر للجماعة»","url":""}]},{"id":"s50-140","number":140,"surah":50,"verses":[34],"references":[{"surah":50,"verses":[34]}],"verseLabel":"ق: 34","question":"ماذا تضيف الباء في قوله ﴿ادْخُلُوهَا بِسَلَامٍ﴾؟","answer":"تفيد دخولهم مصحوبين بالسلامة من كل خوف وآفة، ومع تحية وإكرام؛ فلا يقتصر الوعد على المكان بل يشمل حال الدخول.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص247، تحت عنوان «نوع الباء ودلالتها»","url":""}]},{"id":"s50-141","number":141,"surah":50,"verses":[34],"references":[{"surah":50,"verses":[34]}],"verseLabel":"ق: 34","question":"ماذا يوحي تنكير ﴿سَلَامٍ﴾ في ﴿ادْخُلُوهَا بِسَلَامٍ﴾؟","answer":"يوحي بسلام عظيم كامل متعدد الوجوه: سلامة الجسد والنفس، والأمن، والتحية، ودوام النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص247–248، تحت عنوان «نكتة تنكير المجرور»","url":""}]},{"id":"s50-80","number":80,"surah":50,"verses":[34],"references":[{"surah":50,"verses":[34]}],"verseLabel":"ق: 34","question":"ما سر إضافة اليوم إلى الخلود في ﴿ذَلِكَ يَوْمُ الْخُلُودِ﴾؟","answer":"الإضافة تجعل الخلود أبرز ما يعرف به ذلك اليوم، فهو بدء إقامة لا تنقطع. فلا يراد يوم محدود كأيام الدنيا، بل زمن الجزاء الدائم الذي يطمئن أهله إلى بقاء النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص248–249، تحت عنوان «سر إضافة اليوم للمصدر ﴿الخلود﴾»","url":""}]},{"id":"s50-81","number":81,"surah":50,"verses":[35],"references":[{"surah":50,"verses":[35]}],"verseLabel":"ق: 35","question":"لماذا جاء بعد ﴿لَهُمْ مَا يَشَاءُونَ﴾ قوله ﴿وَلَدَيْنَا مَزِيدٌ﴾؟","answer":"ليبين أن عطاء الله لا يقف عند حدود ما يعرفونه ويطلبونه؛ فلهم فوق كل أمنية نعيم زائد عظيم لم يخطر لهم على بال.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص250–251، تحت عنوان «غرض تنكير المبتدأ»","url":""}]},{"id":"s50-82","number":82,"surah":50,"verses":[36],"references":[{"surah":50,"verses":[36]}],"verseLabel":"ق: 36","question":"ماذا تفيد ﴿كَمْ﴾ في قوله ﴿وَكَمْ أَهْلَكْنَا مِنْ قَرْنٍ﴾؟","answer":"تفيد التكثير والتهويل؛ فالأمم القوية التي أهلكت كثيرة، وفي كثرتها تحذير لمن يظن أن قوته تحميه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص254، تحت عنوان «نوع ﴿كم﴾ ودلالتها»","url":""}]},{"id":"s50-142","number":142,"surah":50,"verses":[36],"references":[{"surah":50,"verses":[36]}],"verseLabel":"ق: 36","question":"لماذا عُبّر عن إهلاك القرون الماضية بالفعل الماضي؟","answer":"لتأكيد وقوعه وتحققه مرة بعد مرة، وجعله شاهدًا تاريخيًا حاضر الدلالة على أن سنة الله لا تتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص255، تحت عنوان «نكتة التعبير بالإهلاك ماضيًا»","url":""}]},{"id":"s50-83","number":83,"surah":50,"verses":[36],"references":[{"surah":50,"verses":[36]}],"verseLabel":"ق: 36","question":"ما المراد بـ﴿قَرْنٍ﴾، وهل يلزم أن يكون مئة سنة؟","answer":"القرن هنا القوم المقترنون في زمان واحد، فهو اسم للجماعة بحسب اجتماعها في عصر. والمقصود كثرة الأمم السابقة التي أهلكت، لا تحديد مدة عددية ثابتة بمئة سنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص253، تحت عنوان «شرح المفردات»","url":""}]},{"id":"s50-84","number":84,"surah":50,"verses":[36],"references":[{"surah":50,"verses":[36]}],"verseLabel":"ق: 36","question":"ما الصورة في قوله عن الأمم القوية ﴿فَنَقَّبُوا فِي الْبِلَادِ﴾؟","answer":"صوّر كثرة تجوالهم ونفوذهم في الأقاليم بمن يخرق الأرض وينقبها، فيبرز سعة قوتهم ومعرفتهم بالمسالك، ثم عجزهم عن الفرار من الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص257–258، تحت عنوان «بلاغة الاستعارة في فعل التنقيب»","url":""}]},{"id":"s50-85","number":85,"surah":50,"verses":[36],"references":[{"surah":50,"verses":[36]}],"verseLabel":"ق: 36","question":"ماذا يقرر الاستفهام ﴿هَلْ مِنْ مَحِيصٍ﴾ بعد ذكر قوة الأمم السابقة؟","answer":"يقرر أنه لا مهرب من حكم الله ولا ملجأ يحول دون الهلاك؛ فقوتهم وتنقلهم في البلاد لم يصنعا لهم مخرجًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص259، تحت عنوان «بلاغة الاستفهام وغرضه»","url":""}]},{"id":"s50-86","number":86,"surah":50,"verses":[37],"references":[{"surah":50,"verses":[37]}],"verseLabel":"ق: 37","question":"لماذا عُبر عن العقل الواعي بـ﴿الْقَلْبِ﴾ في قوله ﴿لِمَنْ كَانَ لَهُ قَلْبٌ﴾؟","answer":"لأن القلب يطلق على موضع الفهم والوعي الذي ينتفع بالموعظة، لا على العضو الموجود في كل إنسان؛ فالعبرة بحياة الإدراك لا بمجرد وجود الجارحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص266–267، تحت عنوان «بلاغة استعمال مفردة القلب»","url":""}]},{"id":"s50-143","number":143,"surah":50,"verses":[37],"references":[{"surah":50,"verses":[37]}],"verseLabel":"ق: 37","question":"ماذا يفيد تنكير ﴿قَلْبٌ﴾ في قوله ﴿لِمَنْ كَانَ لَهُ قَلْبٌ﴾؟","answer":"يعظم شأن القلب الحي ويبين أن أدنى قدر صادق من الوعي يكفي للانتفاع بالذكر؛ أما قلب الغافل فكأنه غير موجود.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص267، تحت عنوان «نكتة تنكير لفظ القلب»","url":""}]},{"id":"s50-87","number":87,"surah":50,"verses":[37],"references":[{"surah":50,"verses":[37]}],"verseLabel":"ق: 37","question":"ما الصورة في قوله ﴿أَلْقَى السَّمْعَ﴾ بدل «استمع»؟","answer":"صوّر السمع كشيء يطرحه صاحبه كله نحو المتكلم؛ فيدل على إنصات كامل خال من الشواغل، مع حضور القلب طلبًا للحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص267–268، تحت عنوان «بلاغة الاستعارة في الإلقاء»","url":""}]},{"id":"s50-88","number":88,"surah":50,"verses":[37],"references":[{"surah":50,"verses":[37]}],"verseLabel":"ق: 37","question":"ماذا يضيف وصف المستمع بأنه ﴿شَهِيدٌ﴾؟","answer":"يدل على حضور قلبه ومشاهدته للمعنى، فلا يكفي وصول الصوت إلى الأذن؛ إنما ينتفع من يجمع الإنصات والوعي والتفاعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص270، تحت عنوان «بلاغة استعمال لفظ ﴿شهيد﴾»","url":""}]},{"id":"s50-89","number":89,"surah":50,"verses":[38],"references":[{"surah":50,"verses":[38]}],"verseLabel":"ق: 38","question":"لماذا قُيّد خلق السماوات والأرض بأنه وقع ﴿فِي سِتَّةِ أَيَّامٍ﴾؟","answer":"لبيان إحكام الخلق وتدرجه وفق الحكمة مع كمال القدرة؛ فالله قادر على خلقه دفعة، لكنه أوجده على نظام مقدر يعلّم التثبت.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص273–274، تحت عنوان «وجه التقييد بالزمن»","url":""}]},{"id":"s50-144","number":144,"surah":50,"verses":[38],"references":[{"surah":50,"verses":[38]}],"verseLabel":"ق: 38","question":"لماذا اختير ﴿اللُّغُوبِ﴾ في نفي التعب عن خلق السماوات والأرض؟","answer":"لأن اللغوب هو الإعياء الناشئ بعد العمل؛ فنفيه يرد توهم أن عظمة الخلق أنهكت الخالق، ويثبت كمال قدرته بلا أدنى فتور.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص275، تحت عنوان «دلالة انتقاء ﴿اللغوب﴾»","url":""}]},{"id":"s50-90","number":90,"surah":50,"verses":[38],"references":[{"surah":50,"verses":[38]}],"verseLabel":"ق: 38","question":"ماذا يضيف قوله ﴿وَمَا مَسَّنَا﴾ إلى نفي اللغوب؟","answer":"ينفي أن يكون أدنى أثر من التعب قد أصاب الخالق؛ فالمس أدنى درجات الإصابة، ونفيه أبلغ في إثبات كمال القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص275، تحت عنوان «نكتة التعبير بالفعل ﴿مسنا﴾»","url":""}]},{"id":"s50-145","number":145,"surah":50,"verses":[38],"references":[{"surah":50,"verses":[38]}],"verseLabel":"ق: 38","question":"ما الفرق بين ﴿اللُّغُوبِ﴾ و«النَّصَب»، ولماذا اختير الأول هنا؟","answer":"اللغوب إعياء وفتور يعقب العمل، والنصب هو المشقة والتعب نفسه. واختيار اللغوب ينفي حتى الأثر اللاحق للخلق، فضلًا عن التعب أثناءه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص276، تحت عنوان «اللغوب والنصب»","url":""}]},{"id":"s50-92","number":92,"surah":50,"verses":[39],"references":[{"surah":50,"verses":[39]}],"verseLabel":"ق: 39","question":"لماذا عُطف الأمر بالتسبيح على الصبر على أقوال المكذبين؟","answer":"لأن التسبيح والحمد يمدان القلب بالقوة والسكينة التي تعينه على الصبر، ويجددان صلته بالله في مواجهة الأذى وطول الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص281–282، تحت عنوان «دلالة عطف الأمر بالتسبيح»","url":""}]},{"id":"s50-93","number":93,"surah":50,"verses":[39],"references":[{"surah":50,"verses":[39]}],"verseLabel":"ق: 39","question":"ما سر الجمع بين التسبيح والحمد في ﴿وَسَبِّحْ بِحَمْدِ رَبِّكَ﴾؟","answer":"التسبيح تنزيه عن كل نقص، والحمد ثناء وإقرار بالكمال والنعمة. والباء تفيد الملابسة، فيكون التنزيه مصحوبًا بالحمد والرضا بما يقدره الله، فيتكامل النفي والإثبات في الثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص282، تحت عنوان «نوع الباء ودلالتها»","url":""}]},{"id":"s50-94","number":94,"surah":50,"verses":[39],"references":[{"surah":50,"verses":[39]}],"verseLabel":"ق: 39","question":"ما سر تكرار ﴿قَبْلَ﴾ في ﴿قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ﴾؟","answer":"أعيد الظرف للاهتمام بتحديد الوقت الثاني وتأكيد استقلاله بالذكر. والمقصود التنبيه إلى التسبيح قبل الغروب كما نبه إليه قبل الطلوع، فيتوزع الذكر على الأوقات المعينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص285، تحت عنوان «غرض تكرار الظرف»","url":""}]},{"id":"s50-95","number":95,"surah":50,"verses":[40],"references":[{"surah":50,"verses":[40]}],"verseLabel":"ق: 40","question":"هل يطلب قوله ﴿وَمِنَ اللَّيْلِ فَسَبِّحْهُ﴾ تسبيح الليل كله؟","answer":"لا؛ تفيد ﴿من﴾ تبعيض الزمن، فيطلب التسبيح في جزء من الليل، وهو وقت السكون والخلوة الأجمع للقلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص286، تحت عنوان «نوع ﴿من﴾ ودلالته»","url":""}]},{"id":"s50-96","number":96,"surah":50,"verses":[40],"references":[{"surah":50,"verses":[40]},{"surah":52,"verses":[49]}],"verseLabel":"ق: 40، الطور: 49","question":"ماذا يوحي التعبير بـ﴿أَدْبَارَ السُّجُودِ﴾ عن وقت التسبيح بعد الصلاة؟","answer":"يوحي بأن وقت التسبيح لا يقتصر على لحظة الفراغ من الصلاة، بل يمتد بعدها إلى وقت الصلاة التي تليها، وجمع ﴿أدبار﴾ يشمل أعقاب الصلوات المفروضة وغيرها من النوافل.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص288، تحت عنوان «سر التعبير بالأدبار»","url":""}]},{"id":"s50-97","number":97,"surah":50,"verses":[41],"references":[{"surah":50,"verses":[41]}],"verseLabel":"ق: 41","question":"ما سر حذف مفعول الأمر في ﴿وَاسْتَمِعْ﴾؟","answer":"حذف المفعول يوجه العناية إلى الاستماع نفسه ويعظم شأن ما سيعلن. ويثير الترقب لما بعده من خبر النداء والبعث، فيلقى السامع هذا الخبر وهو أشد انتباهًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص293، تحت عنوان «دلالة حذف المفعول»","url":""}]},{"id":"s50-98","number":98,"surah":50,"verses":[41],"references":[{"surah":50,"verses":[41]}],"verseLabel":"ق: 41","question":"ماذا يصور المضارع في قوله ﴿يُنَادِ الْمُنَادِ﴾؟","answer":"يستحضر النداء واقعًا يتجدد أمام السامع، فيقرب مشهد البعث ويصور المنادي وهو يرفع صوته فتخرج الخلائق.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص293، تحت عنوان «نكتة التعبير بصيغة المضارع»","url":""}]},{"id":"s50-99","number":99,"surah":50,"verses":[41],"references":[{"surah":50,"verses":[41]}],"verseLabel":"ق: 41","question":"ما سر وصف موضع النداء بأنه ﴿مَكَانٍ قَرِيبٍ﴾؟","answer":"القرب يصور وصول النداء إلى الجميع بوضوح، فلا يتفاوت سماعه كالأصوات التي يضعفها البعد. فالمقصود تأكيد نفاذ الدعوة وسرعة الاستجابة، لا ترك أحد خارج السماع.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص295، تحت عنوان «نكتة التنكير والوصف»","url":""}]},{"id":"s50-100","number":100,"surah":50,"verses":[42],"references":[{"surah":50,"verses":[42]}],"verseLabel":"ق: 42","question":"ماذا يعني وصف الصيحة يوم القيامة بأنها ﴿بِالْحَقِّ﴾؟","answer":"يعني أنها واقعة حتمًا ومقترنة بالحكمة والعدل، وأنها تبطل ظن المكذبين بالبعث؛ فهي الصيحة التي تنشئ الخروج الموعود حقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص296–297، تحت عنوان «دلالة استعمال مفردة ﴿الحق﴾»","url":""}]},{"id":"s50-101","number":101,"surah":50,"verses":[11,42],"references":[{"surah":50,"verses":[11,42]}],"verseLabel":"ق: 11، 42","question":"ما العلاقة بين ﴿كَذَلِكَ الْخُرُوجُ﴾ بعد إحياء الأرض وخروج الناس عند الصيحة؟","answer":"جعل خروج النبات من الأرض مثالًا محسوسًا لخروج الأجساد منها؛ فما يشاهدونه كل عام دليل يقرب حقيقة البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص130، تحت عنوان «بلاغة ذكر الخروج»","url":""}]},{"id":"s50-146","number":146,"surah":50,"verses":[11,42],"references":[{"surah":50,"verses":[11,42]}],"verseLabel":"ق: 11، 42","question":"لماذا عُرّف ﴿الْخُرُوجُ﴾ في قوله ﴿ذَلِكَ يَوْمُ الْخُرُوجِ﴾؟","answer":"للعهد؛ فهو الخروج العظيم المعروف الذي أنكروه، خروج الناس من القبور إلى الحساب، لا خروجًا عابرًا مجهولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص297، تحت عنوان «دلالة تعريف ﴿الخروج﴾»","url":""}]},{"id":"s50-102","number":102,"surah":50,"verses":[43],"references":[{"surah":50,"verses":[43]}],"verseLabel":"ق: 43","question":"لماذا توالت المؤكدات في قوله ﴿إِنَّا نَحْنُ نُحْيِي وَنُمِيتُ﴾؟","answer":"لتقرير اختصاص الله بالإحياء والإماتة والرد على منكري البعث؛ فـ﴿إن﴾ وضمير الفصل وتكرار الإسناد تجعل الحقيقة قاطعة لا تقبل الشك.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص300–301، تحت عنوان «غرض تتابع المؤكدات»","url":""}]},{"id":"s50-147","number":147,"surah":50,"verses":[43],"references":[{"surah":50,"verses":[43]}],"verseLabel":"ق: 43","question":"ماذا يفيد اجتماع ضمائر العظمة في ﴿إِنَّا نَحْنُ نُحْيِي وَنُمِيتُ﴾؟","answer":"يفخم سلطان الله وقدرته المنفردة على أعظم شؤون الخلق، ويؤكد أن الإحياء والإماتة لا يملكهما سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص301، تحت عنوان «دلالة الجمع بين ضمائر العظمة»","url":""}]},{"id":"s50-103","number":103,"surah":50,"verses":[43],"references":[{"surah":50,"verses":[43]}],"verseLabel":"ق: 43","question":"ما المراد بـ﴿الْمَصِيرُ﴾ في قوله ﴿وَإِلَيْنَا الْمَصِيرُ﴾؟","answer":"هو مرجع الخلق كلهم بعد الموت إلى حكم الله وحسابه؛ فكل حي صائر إليه يوم البعث ولا يملك مهربًا من لقائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص299، تحت عنوان «شرح المفردات»","url":""}]},{"id":"s50-148","number":148,"surah":50,"verses":[43],"references":[{"surah":50,"verses":[43]}],"verseLabel":"ق: 43","question":"ماذا يفيد تقديم ﴿إِلَيْنَا﴾ في قوله ﴿وَإِلَيْنَا الْمَصِيرُ﴾؟","answer":"يفيد قصر المرجع على الله وحده، مع التعظيم والاهتمام؛ فلا مصير نهائيًا إلى غير حكمه، وفيه وعد للمحسن ووعيد للمسيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص303–304، تحت عنوان «غرض تقديم شبه الجملة»","url":""}]},{"id":"s50-104","number":104,"surah":50,"verses":[44],"references":[{"surah":50,"verses":[44]}],"verseLabel":"ق: 44","question":"ما سر تعدية ﴿تَشَقَّقُ الْأَرْضُ﴾ بـ﴿عَنْهُمْ﴾؟","answer":"﴿عن﴾ للمجاوزة، فتصور انشقاق الأرض وانكشافها عنهم بعد أن كانت تحيط بأجسادهم. وتظهر الصورة سهولة خروج الناس عند البعث، على خلاف ما استبعدوه من امتزاجهم بالتراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص306–307، تحت عنوان «دلالة ﴿عنهم﴾»","url":""}]},{"id":"s50-105","number":105,"surah":50,"verses":[44],"references":[{"surah":50,"verses":[44]}],"verseLabel":"ق: 44","question":"ما الذي تضيفه الحال ﴿سِرَاعًا﴾ إلى مشهد خروج الناس من الأرض؟","answer":"الحال تصور سرعة استجابتهم للنداء وخروجهم إلى الموقف، فلا يملكون تأخرًا أو بقاء في قبورهم. وتدل السرعة على سهولة البعث ونفاذ الأمر الذي أنكروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص307، تحت عنوان «دلالة الحال»","url":""}]},{"id":"s50-106","number":106,"surah":50,"verses":[44],"references":[{"surah":50,"verses":[44]}],"verseLabel":"ق: 44","question":"ماذا يفيد تقديم ﴿عَلَيْنَا﴾ في قوله ﴿ذَلِكَ حَشْرٌ عَلَيْنَا يَسِيرٌ﴾؟","answer":"يبرز أن الحشر مع عظمته يسير على الله خاصة، ويحول النظر من استبعاد البشر له إلى كمال قدرة من يتولاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص308، تحت عنوان «دلالة تقديم ﴿علينا﴾»","url":""}]},{"id":"s50-107","number":107,"surah":50,"verses":[45],"references":[{"surah":50,"verses":[45]}],"verseLabel":"ق: 45","question":"كيف يتصل نفي الجبر عن الرسول بقوله ﴿نَحْنُ أَعْلَمُ بِمَا يَقُولُونَ﴾؟","answer":"لما طمأنه الله بعلمه بأقوالهم، بين أن مهمته البلاغ لا إكراههم على الإيمان؛ فالله يتولى حسابهم ولا يحمل الرسول مسؤولية عنادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص314، تحت عنوان «دلالة العطف بين الجمل»","url":""}]},{"id":"s50-149","number":149,"surah":50,"verses":[45],"references":[{"surah":50,"verses":[45]}],"verseLabel":"ق: 45","question":"ماذا يضيف خطاب النبي مباشرة في ﴿وَمَا أَنْتَ عَلَيْهِمْ بِجَبَّارٍ﴾؟","answer":"يزيده تسلية وتثبيتًا، وينفي عنه عبء حملهم قسرًا على الإيمان؛ فوظيفته التذكير والبلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص314–315، تحت عنوان «دلالة ضمير الخطاب»","url":""}]},{"id":"s50-108","number":108,"surah":50,"verses":[45],"references":[{"surah":50,"verses":[45]}],"verseLabel":"ق: 45","question":"لماذا خُص القرآن بالتذكير في قوله ﴿فَذَكِّرْ بِالْقُرْآنِ﴾؟","answer":"لأنه أجمع وسائل الذكرى وأعظمها أثرًا، بما يجمعه من حجج ومواعظ ووعد ووعيد؛ فقراءته هي أصل البلاغ والتوجيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص317، تحت عنوان «نكتة التعبير بلفظ القرآن»","url":""}]},{"id":"s50-150","number":150,"surah":50,"verses":[45],"references":[{"surah":50,"verses":[45]}],"verseLabel":"ق: 45","question":"ماذا يفيد المضارع في قوله ﴿مَنْ يَخَافُ وَعِيدِ﴾؟","answer":"يفيد خوفًا متجددًا حيًا يدفع صاحبه إلى الانتفاع بالذكر والعمل، لا رهبة عابرة تزول دون أثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص317–318، تحت عنوان «بلاغة التعبير بالفعل ﴿يخاف﴾»","url":""}]},{"id":"s50-109","number":109,"surah":50,"verses":[14,45],"references":[{"surah":50,"verses":[14,45]}],"verseLabel":"ق: 14، 45","question":"ماذا تضيف نسبة الوعيد إلى الله في قوله ﴿فَحَقَّ وَعِيدِ﴾؟","answer":"تؤكد صدقه ووقوعه؛ لأنه وعيد الله الذي لا يخلف، وتفخم العقوبة التي حقت بمن كذب الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص140، تحت عنوان «دلالة الإضافة في ﴿وعيد﴾»","url":""}]},{"id":"s50-151","number":151,"surah":50,"verses":[14,45],"references":[{"surah":50,"verses":[14,45]}],"verseLabel":"ق: 14، 45","question":"لماذا عُبّر بـ﴿وَعِيدِ﴾ مصدرًا في قوله ﴿مَنْ يَخَافُ وَعِيدِ﴾؟","answer":"ليعظم جنس التهديد ويجعله حاضر الأثر في النفس، فالمنتفع بالقرآن هو من يصدق بالبعث ويستشعر عاقبة الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص318، تحت عنوان «بلاغة التعبير بالمصدر ﴿وعيد﴾»","url":""}]},{"id":"s51-1","number":1,"surah":51,"verses":[1,2,3,4],"references":[{"surah":51,"verses":[1,2,3,4]}],"verseLabel":"الذاريات: 1–4","question":"لماذا افتتحت سورة الذاريات بالقسم بالرياح؟","answer":"لأن حركة الرياح وما تحمله من سحاب ومطر ورزق شاهد محسوس على قدرة الله وتدبيره؛ فجاء القسم بها لتوكيد أن الوعد والجزاء واقعان كما تقع آثارها المشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص333–334، تحت عنوان «غرض القسم في قوله: ﴿والذاريات﴾»","url":""}]},{"id":"s51-32","number":32,"surah":51,"verses":[1,2,3,4],"references":[{"surah":51,"verses":[1,2,3,4]}],"verseLabel":"الذاريات: 1–4","question":"ماذا تفيد الفاء في تتابع ﴿فَالْحَامِلَاتِ﴾ و﴿فَالْجَارِيَاتِ﴾ و﴿فَالْمُقَسِّمَاتِ﴾؟","answer":"ترتب المشاهد كحلقات متعاقبة: تثير الرياح السحاب، فيحمل الماء، ثم يجري، ثم تُقسم الأرزاق؛ فيظهر من التتابع نظام التدبير ووحدة مراحله.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص336–337، تحت عنوان «معنى ﴿الفاء﴾ في جملة: ﴿فالحاملات وقرًا﴾»","url":""}]},{"id":"s51-33","number":33,"surah":51,"verses":[1,2,3,4],"references":[{"surah":51,"verses":[1,2,3,4]}],"verseLabel":"الذاريات: 1–4","question":"لماذا جاءت ﴿الْمُقَسِّمَاتِ﴾ معرفةً وجمعًا؟","answer":"يشير التعريف إلى طائفة معلومة بوظيفتها في تنفيذ أمر الله، ويدل الجمع على كثرة الملائكة وتنوع ما يوكل إليهم من تقسيم الأرزاق والآجال وغيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص343، تحت عنوان «معنى ﴿أل﴾ في ﴿فالمقسمات﴾، ودلالة جمعه»","url":""}]},{"id":"s51-2","number":2,"surah":51,"verses":[7],"references":[{"surah":51,"verses":[7]}],"verseLabel":"الذاريات: 7","question":"ما سرّ وصف السماء بأنها ﴿ذَاتِ الْحُبُكِ﴾؟","answer":"الحبك تدل على إحكام النسج وحسن الهيئة، فيصف اللفظ السماء بمتانة بنائها وانتظامها وجمالها. ويجمع الوصف بين الحسن والإتقان، فيجعل المقسم به شاهدًا على حكمة الخالق وقدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص360، تحت عنوان «نكتة وصف السماء بـ﴿ذات الحبك﴾»","url":""}]},{"id":"s51-3","number":3,"surah":51,"verses":[8],"references":[{"surah":51,"verses":[8]}],"verseLabel":"الذاريات: 8","question":"ما سرّ التعبير في قول ﴿إِنَّكُمْ لَفِي قَوْلٍ مُخْتَلِفٍ﴾، ولم يقل «في كفر وضلال»؟","answer":"وصف موقفهم بأنه قول مختلف يكشف تناقض أحكامهم على الرسول والقرآن، ويواجههم باضطراب كلامهم نفسه. واختيار القول بدل التصريح بالكفر والضلال أرفق في المحاجة، وأدعى إلى حملهم على مراجعة ما يقولون.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص363–364، تحت عنوان «دلالة لفظ القول»","url":""}]},{"id":"s51-4","number":4,"surah":51,"verses":[9],"references":[{"surah":51,"verses":[9]}],"verseLabel":"الذاريات: 9","question":"لماذا عُبِّر عن الانصراف عن القرآن بالفعل ﴿يُؤْفَكُ﴾؟","answer":"لأن الإفك صرفٌ عن الوجه الصحيح إلى الباطل، فيصور المعرض وقد قلب عن الحق الواضح وانحرف عنه انقلابًا شديدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص366، تحت عنوان «بلاغة التعبير بالإفك في الفعل ﴿يؤفك﴾»","url":""}]},{"id":"s51-34","number":34,"surah":51,"verses":[9],"references":[{"surah":51,"verses":[9]}],"verseLabel":"الذاريات: 9","question":"لماذا بُني ﴿يُؤْفَكُ﴾ للمجهول؟","answer":"لأن أسباب الصرف عن الحق متعددة؛ فقد تكون هوى النفس أو شيطانًا أو صاحب سوء، فحُذف الفاعل لتتجه العناية إلى هول الانصراف نفسه وتعدد أبوابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص367، تحت عنوان «لطيفة بناء الفعل ﴿يؤفك﴾ للمفعول»","url":""}]},{"id":"s51-35","number":35,"surah":51,"verses":[9],"references":[{"surah":51,"verses":[9]}],"verseLabel":"الذاريات: 9","question":"لماذا بُني ﴿أُفِكَ﴾ للمجهول في قوله: ﴿مَنْ أُفِكَ﴾؟","answer":"ليدل على أن هذا المصروف بلغ من تمكن الباطل منه أن صار معروفًا بنتيجة الانقلاب لا بسببها، وليعم الحكم كل من انتهى إلى هذا المصير مهما كان صارفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص370، تحت عنوان «لطيفة بناء الفعل ﴿أفك﴾ للمفعول»","url":""}]},{"id":"s51-5","number":5,"surah":51,"verses":[12],"references":[{"surah":51,"verses":[12]}],"verseLabel":"الذاريات: 12","question":"لماذا سأل المكذبون بـ﴿أَيَّانَ﴾ عن يوم الدين؟","answer":"لأن ﴿أيان﴾ تسأل عن زمن مستقبل بعيد أو مجهول، فاختاروها استبعادًا لوقوع اليوم وإنكارًا أن يكون قريبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص382، تحت عنوان «دلالة التعبير بـ﴿أيان﴾»","url":""}]},{"id":"s51-6","number":6,"surah":51,"verses":[13],"references":[{"surah":51,"verses":[13]}],"verseLabel":"الذاريات: 13","question":"لماذا سُمِّي عذابهم ﴿فِتْنَةً﴾ في قوله: ﴿ذُوقُوا فِتْنَتَكُمْ﴾؟","answer":"لأن الفتنة أصلها الاختبار بالنار، فاستعيرت للعذاب المحرق الذي يكشف حقيقتهم ويجازيهم؛ وفي لفظ الذوق تجسيد مباشر للإحساس بالألم.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص387–388، تحت عنوان «بلاغة المجاز في قوله تعالى: ﴿ذوقوا فتنتكم﴾»","url":""}]},{"id":"s51-36","number":36,"surah":51,"verses":[13],"references":[{"surah":51,"verses":[13]}],"verseLabel":"الذاريات: 13","question":"ماذا تضيف نسبة الفتنة إليهم في ﴿فِتْنَتَكُمْ﴾؟","answer":"تقرر أن هذا العذاب خاص بهم وناشئ عن كفرهم وفتنتهم في الدنيا؛ فكأنه الفتنة التي صنعوها لأنفسهم ثم عاد أثرها عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص388، تحت عنوان «دلالة الإضافة في ﴿فتنتكم﴾»","url":""}]},{"id":"s51-7","number":7,"surah":51,"verses":[15],"references":[{"surah":51,"verses":[15]}],"verseLabel":"الذاريات: 15","question":"لماذا وُصف أهل الجنة هنا بـ﴿الْمُتَّقِينَ﴾؟","answer":"لأن السياق سبق بذكر المكذبين الذين قادتهم المعاصي إلى النار، فجاء وصف المتقين ليبين أن وقايتهم أنفسهم من الكفر والآثام كانت سبب نجاتهم ودخولهم الجنات.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص398–399، تحت عنوان «سر إيثار وصف ﴿المتقين﴾ على غيره من أوصافهم»","url":""}]},{"id":"s51-8","number":8,"surah":51,"verses":[16],"references":[{"surah":51,"verses":[16]}],"verseLabel":"الذاريات: 16","question":"ما سرّ التعبير في قول ﴿آخِذِينَ مَا آتَاهُمْ رَبُّهُمْ﴾، ولم يقل «ما يؤتيهم»؟","answer":"جاء الإيتاء ماضيًا مع أن النعيم مستقبل لتحقيق الوعد، فكأن العطاء تم وحصل. ويقرر ذلك أن ما وعد الله به المتقين لا يتخلف، فتتلقى النفس الخبر بيقين الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص405–406، تحت عنوان «سر صوغ فعل الإيتاء ماضيًا»","url":""}]},{"id":"s51-9","number":9,"surah":51,"verses":[17],"references":[{"surah":51,"verses":[17]}],"verseLabel":"الذاريات: 17","question":"لماذا وُصف أهل الإحسان بقلة الهجوع بدل كثرة قيام الليل؟","answer":"لأن قلة النوم أبلغ في تصوير ملازمتهم للعبادة طوال الليل؛ فهي تثبت أنهم يأخذون قدر الضرورة من الراحة ثم يعودون إلى مناجاة ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص414، تحت عنوان «نكتة العدول عن ذكر قيام الليل إلى قلة الهجوع بالليل»","url":""}]},{"id":"s51-37","number":37,"surah":51,"verses":[17],"references":[{"surah":51,"verses":[17]}],"verseLabel":"الذاريات: 17","question":"لماذا قُدِّم ﴿قَلِيلًا﴾ و﴿مِنَ اللَّيْلِ﴾ في وصف هجوعهم؟","answer":"لإبراز الندرة وتوجيه الانتباه إليها قبل ذكر النوم؛ فكأن أول ما يعرف من ليلهم أن نصيب الهجوع فيه قليل محدود.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص415، تحت عنوان «لطيفة تقديم الخبر ﴿قليلًا﴾ والقيد ﴿من الليل﴾ على بدل اسم كان»","url":""}]},{"id":"s51-10","number":10,"surah":51,"verses":[20],"references":[{"surah":51,"verses":[20]}],"verseLabel":"الذاريات: 20","question":"ما سرّ التعبير في قول ﴿لِلْمُوقِنِينَ﴾ بصيغة اسم الفاعل، ولم يقل «للذين يوقنون»؟","answer":"صيغة اسم الفاعل تصور اليقين صفة راسخة في أصحابه، فينتفعون بالآيات ويهتدون بها. أما التعبير بالفعل فيلحظ تجدد حصول الفعل؛ فاختيار الموقنين أنسب بإبراز ثبوت اليقين ورسوخه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص434، تحت عنوان «وجه التعبير بلفظ ﴿الموقنين﴾ مادة وصيغة»","url":""}]},{"id":"s51-11","number":11,"surah":51,"verses":[21],"references":[{"surah":51,"verses":[21]}],"verseLabel":"الذاريات: 21","question":"ما دلالة التعبير بالنفس في ﴿وفي أنفسكم﴾، وما وجه اتساعه عن الاقتصار على «أرواحكم»؟","answer":"يعرض المبحث النفس بمعنى الجسم وما في خلقه وأعضائه وحواسه من دلائل القدرة، ويعرض أيضًا حملها على الروح وما فيها من أسرار الخلق. فالتعبير يفتح النظر في الإنسان نفسه، ولا يلزم منه استبعاد الروح أو قصر الدلالة عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص436–437، تحت عنوان «دلالة التعبير بالنفس في قوله: ﴿وفي أنفسكم﴾»","url":""}]},{"id":"s51-12","number":12,"surah":51,"verses":[22],"references":[{"surah":51,"verses":[22]}],"verseLabel":"الذاريات: 22","question":"ما سرّ التعبير في قول ﴿وَفِي السَّمَاءِ رِزْقُكُمْ﴾ مع أن الطعام يخرج من الأرض؟","answer":"من أوجه التفسير أن الرزق المطر الذي ينزل من السماء فيكون سببًا لما تنبته الأرض، فسمي السبب باسم ما ينشأ عنه. ومن أوجهه أن الرزق مقدر مضمون عند الله؛ فلا تعارض بين إضافته إلى السماء وبين خروج الطعام من الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص443–444، تحت عنوان «دلالة التعبير بالرزق، ونكتة صوغه مصدرًا»","url":""}]},{"id":"s51-13","number":13,"surah":51,"verses":[23],"references":[{"surah":51,"verses":[23]}],"verseLabel":"الذاريات: 23","question":"لماذا ترقّى القسم من المخلوقات إلى قوله: ﴿فَوَرَبِّ السَّمَاءِ وَالْأَرْضِ﴾؟","answer":"لأن السورة بدأت بالقسم بآثار القدرة في الرياح والسحاب، ثم ارتقت إلى القسم بخالقها وربها؛ فيبلغ التوكيد غايته عند تقرير حقيقة الرزق والوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص448، تحت عنوان «بلاغة الترقي من القسم بالمخلوقات إلى القسم بخالقها سبحانه»","url":""}]},{"id":"s51-38","number":38,"surah":51,"verses":[23],"references":[{"surah":51,"verses":[23]}],"verseLabel":"الذاريات: 23","question":"لماذا شُبِّه يقين الوعد بيقين نطق الإنسان في ﴿مِثْلَ مَا أَنَّكُمْ تَنْطِقُونَ﴾؟","answer":"لأن الإنسان لا يشك في أنه ينطق ولا يحتاج في ذلك إلى برهان؛ فجُعل حق الوعد والرزق في الدرجة نفسها من الظهور واليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص453، تحت عنوان «بلاغة التشبيه بالنطق»","url":""}]},{"id":"s51-14","number":14,"surah":51,"verses":[24],"references":[{"surah":51,"verses":[24]}],"verseLabel":"الذاريات: 24","question":"لماذا قيل: ﴿أَتَاكَ حَدِيثُ﴾ ولم يقل «جاءك»؟","answer":"لأن الإتيان أنسب بوصول الخبر والمعرفة إلى السامع، أما المجيء فأظهر في وصول الأجسام؛ فالذي بلغ النبي ﷺ هنا حديث الضيف بوحي الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص462، تحت عنوان «دلالة التعبير بالفعل ﴿أتاك﴾ دون ﴿جاءك﴾»","url":""}]},{"id":"s51-15","number":15,"surah":51,"verses":[24],"references":[{"surah":51,"verses":[24]}],"verseLabel":"الذاريات: 24","question":"ما سرّ وصف ضيف إبراهيم في الذاريات بـ﴿الْمُكْرَمِينَ﴾؟","answer":"يحتمل الوصف إكرامهم عند الله؛ فهم ملائكته المكرمون، ويحتمل ما أكرمهم به إبراهيم من حسن الاستقبال والضيافة. فيجمع السياق رفعة منزلة الضيف وكرم المضيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص464–465، تحت عنوان «نكتة وصف الضيف بـ﴿المكرمين﴾»","url":""}]},{"id":"s51-16","number":16,"surah":51,"verses":[25],"references":[{"surah":51,"verses":[25]}],"verseLabel":"الذاريات: 25","question":"ما سرّ التعبير في قول الضيوف ﴿سَلَامًا﴾ بالنصب، ورد إبراهيم ﴿سَلَامٌ﴾ بالرفع؟","answer":"﴿سلامًا﴾ مصدر منصوب لفعل محذوف، فتقديره تحية بجملة فعلية. ورد إبراهيم ﴿سلامٌ﴾ جملة اسمية تفيد الثبوت والدوام؛ فكانت تحيته أحسن من تحيتهم من هذا الوجه، موافقة لكرمه وحسن لقائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص470، تحت عنوان «توجيه إعراب ﴿سلامًا﴾ و﴿سلام﴾»","url":""}]},{"id":"s51-17","number":17,"surah":51,"verses":[25],"references":[{"surah":51,"verses":[25]}],"verseLabel":"الذاريات: 25","question":"ما سرّ التعبير في قول إبراهيم ﴿قَوْمٌ مُنْكَرُونَ﴾، ولم يقل «قوم لا أعرفهم»؟","answer":"المراد أنهم غير معروفين لديه، وليس الوصف حكمًا عليهم بسوء. وفي التعبير غير المباشر تلطف في إظهار عدم معرفتهم، من غير مواجهتهم بعبارة أشد مثل «أنكرتكم»؛ فهو أنسب بأدب استقبال الضيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص471، تحت عنوان «نكتة وصف ﴿قوم﴾ بـ﴿منكرون﴾»","url":""}]},{"id":"s51-18","number":18,"surah":51,"verses":[26],"references":[{"surah":51,"verses":[26]}],"verseLabel":"الذاريات: 26","question":"ما سرّ التعبير في قول ﴿فَرَاغَ إِلَى أَهْلِهِ﴾، ولم يقل «فذهب»؟","answer":"الروغان ذهاب في خفاء وسرعة؛ فاختياره يصور مبادرة إبراهيم إلى إعداد الضيافة من غير إشعار الضيوف بما قد يحملهم على الاعتذار أو المنع. أما الذهاب وحده فلا يؤدي هذه الهيئة من حسن التصرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص472–473، تحت عنوان «سر إيثار الفعل ﴿راغ﴾ دون غيره»","url":""}]},{"id":"s51-19","number":19,"surah":51,"verses":[27],"references":[{"surah":51,"verses":[27]}],"verseLabel":"الذاريات: 27","question":"ما سرّ التعبير في قول ﴿فَقَرَّبَهُ إِلَيْهِمْ﴾ ولم يقل «فقربهم إليه»؟","answer":"قرب الطعام إلى مكان ضيوفه ولم يكلفهم الانتقال إليه، فذلك من تمام إكرامهم. والتضعيف في ﴿قرب﴾ يلائم العناية بإدنائه حتى يكون في متناولهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص476، تحت عنوان «دلالة التعبير بالفعل ﴿قرب﴾ ماضيًا مضعفًا»","url":""}]},{"id":"s51-20","number":20,"surah":51,"verses":[28],"references":[{"surah":51,"verses":[28]}],"verseLabel":"الذاريات: 28","question":"لماذا عُبِّر عن خوف إبراهيم بقوله: ﴿فَأَوْجَسَ﴾؟","answer":"لأن الإيجاس خوف يقع في النفس خفيًا قبل أن يظهر، فجاء الماضي ليصور اللحظة المفاجئة التي أحس فيها الريبة حين لم تمتد أيديهم إلى الطعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص479–480، تحت عنوان «دلالة التعبير بالفعل ﴿أوجس﴾ ماضيًا»","url":""}]},{"id":"s51-39","number":39,"surah":51,"verses":[28],"references":[{"surah":51,"verses":[28]}],"verseLabel":"الذاريات: 28","question":"لماذا قيل: ﴿خِيفَةً﴾ دون «خوفًا» ونُكِّرت؟","answer":"لأن الخيفة هيئة خوف خفي يسير، وتنكيرها يصور قدرًا مبهمًا طرأ في نفسه من غير هلع ظاهر؛ فناسب المقام حذر إبراهيم المكتوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص480–481، تحت عنوان «دلالة التعبير بـ﴿خيفة﴾ دون ﴿خوفًا﴾، ونكتة تنكيره»","url":""}]},{"id":"s51-21","number":21,"surah":51,"verses":[28],"references":[{"surah":51,"verses":[28]}],"verseLabel":"الذاريات: 28","question":"لماذا وُصف الغلام الذي بُشِّر به إبراهيم في الذاريات بأنه ﴿عَلِيمٍ﴾؟","answer":"لأن البشارة لا تقف عند ولادته، بل تومئ إلى مستقبل إسحاق وما يؤتاه من علم ونبوة؛ فوصف الصبي بما سيؤول إليه زيادة في تمام البشرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص484–485، تحت عنوان «نكتة وصف ﴿غلام﴾ بـ﴿عليم﴾ على زنة ﴿فعيل﴾»","url":""}]},{"id":"s51-22","number":22,"surah":51,"verses":[29],"references":[{"surah":51,"verses":[29]}],"verseLabel":"الذاريات: 29","question":"ما سرّ التعبير في قول ﴿فَأَقْبَلَتِ امْرَأَتُهُ﴾، ولم يقل «زوجته»؟","answer":"يوجه المبحث اختيار ﴿امرأته﴾ إلى حال العقم التي كانت عليها عند البشارة، إذ لم يتحقق جانب التناسل من الزوجية. فالوصف مناسب للمقام الذي تظهر فيه غرابة البشارة، ولا يراد به نفي العلاقة الزوجية بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص487–488، تحت عنوان «دلالة التعبير بـ﴿امرأته﴾ دون ﴿زوجته﴾»","url":""}]},{"id":"s51-23","number":23,"surah":51,"verses":[29],"references":[{"surah":51,"verses":[29]}],"verseLabel":"الذاريات: 29","question":"ما سرّ التعبير في قول ﴿عَجُوزٌ عَقِيمٌ﴾، ولم تقل «عاقر»؟","answer":"﴿عقيم﴾ على وزن فعيل تصور العقم صفة راسخة ملازمة، بخلاف عاقر على وزن فاعل الذي لا يبرز هذا الثبوت بالقوة نفسها. وبذلك يشتد تصوير تعجبها من الولد مع الكبر واستمرار العقم، وتظهر عظمة القدرة في البشارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص492–493، تحت عنوان «سر التعبير بـ﴿عقيم﴾ دون ﴿عاقر﴾»","url":""}]},{"id":"s51-24","number":24,"surah":51,"verses":[31],"references":[{"surah":51,"verses":[31]}],"verseLabel":"الذاريات: 31","question":"لماذا ناداهم إبراهيم بـ﴿الْمُرْسَلُونَ﴾ دون «الملائكة»؟","answer":"لأن سؤاله متعلق بمهمتهم لا بجنسهم؛ فالوصف يوجه الانتباه إلى الرسالة التي كُلّفوا بها وإلى الجهة التي أرسلتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص509، تحت عنوان «نكتة إيثار التعبير بـ﴿المرسلون﴾ دون (الملائكة)»","url":""}]},{"id":"s51-25","number":25,"surah":51,"verses":[32],"references":[{"surah":51,"verses":[32]}],"verseLabel":"الذاريات: 32","question":"ما سرّ وصف قوم لوط بـ﴿قَوْمٍ مُجْرِمِينَ﴾ بصيغة اسم الفاعل؟","answer":"اسم الفاعل يدل على أن الإجرام صار صفة راسخة ملازمة لهم، بعد أن استمروا عليه وأكثروا منه. أما الفعل ﴿يجرمون﴾ فيلحظ حدوث الفعل وتجددَه؛ فالوصف أنسب ببيان استحقاقهم ما أرسل إليهم من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص514، تحت عنوان «نكتة وصف قوم لوط بـ﴿مجرمين﴾ دون (يجرمون)»","url":""}]},{"id":"s51-26","number":26,"surah":51,"verses":[34],"references":[{"surah":51,"verses":[34]}],"verseLabel":"الذاريات: 34","question":"ما سرّ التعبير في قول الملائكة ﴿مُسَوَّمَةً عِنْدَ رَبِّكَ﴾، فأضافت الرب إلى إبراهيم؟","answer":"إضافة الرب إلى إبراهيم تلطف في الخطاب وتطمين له: فإهلاك المجرمين واقع بتدبير ربه الرحيم به. وفيها أيضًا تذكير بعناية الله بإبراهيم، وبأن من أكرمه بالنعم يستحق عبادته وطاعته؛ ولا تناقض بين رحمته وإهلاك المعتدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص519، تحت عنوان «دلالة الإضافة في ﴿ربك﴾»","url":""}]},{"id":"s51-27","number":27,"surah":51,"verses":[34],"references":[{"surah":51,"verses":[34]}],"verseLabel":"الذاريات: 34","question":"لماذا أظهر فقال ﴿لِلْمُسْرِفِينَ﴾، ولم يقل «لهم»؟","answer":"إظهار وصف المسرفين بدل الضمير يبين سبب العقوبة؛ فقد تجاوزوا الحد في المعاصي. فهو يذمهم ويجعل الإسراف علة لما نزل بهم، بينما «لهم» لا يصرح بهذا الوصف الموجب للعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص521، تحت عنوان «لطيفة إظهار (المسرفين) دون إضماره (لهم)»","url":""}]},{"id":"s51-28","number":28,"surah":51,"verses":[41],"references":[{"surah":51,"verses":[41]}],"verseLabel":"الذاريات: 41","question":"لماذا وُصفت ريح عاد بأنها ﴿الْعَقِيمَ﴾؟","answer":"لأنها لا تحمل مطرًا ولا تلقح سحابًا أو نباتًا، بل لا تنتج إلا الهلاك؛ فاستعير العقم لانقطاع كل خير منها، وجاءت صيغة فعيل لتثبيت الصفة والمبالغة فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص572–573، تحت عنوان «دلالة وصف ﴿الريح﴾ بـ﴿العقيم﴾، ولطيفة صوغه على (فعيل)»","url":""}]},{"id":"s51-29","number":29,"surah":51,"verses":[45],"references":[{"surah":51,"verses":[45]}],"verseLabel":"الذاريات: 45","question":"لماذا قيل عن ثمود: ﴿فَمَا اسْتَطَاعُوا مِنْ قِيَامٍ﴾ دون «فما قدروا»؟","answer":"لأن الاستطاعة توحي ببذل الوسع ومحاولة الفعل، فنفى عنهم حتى القدرة المكتسبة على النهوض بعد الصاعقة، وصوّر عجزهم واقعًا منتهيًا بالماضي.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص594–595، تحت عنوان «دلالة التعبير بالاستطاعة، ولطيفة صوغها فعلًا ماضيًا»","url":""}]},{"id":"s51-40","number":40,"surah":51,"verses":[45],"references":[{"surah":51,"verses":[45]}],"verseLabel":"الذاريات: 45","question":"ماذا تضيف السين والتاء في ﴿اسْتَطَاعُوا﴾ إلى صورة عجز ثمود؟","answer":"توحيان بطلب القدرة واستجماعها؛ فمع أنهم حاولوا أن يجدوا في أنفسهم قوة للنهوض لم يملكوها، فكان العجز أبلغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص595، تحت عنوان «دلالة السين والتاء في الفعل ﴿استطاعوا﴾»","url":""}]},{"id":"s51-30","number":30,"surah":51,"verses":[56],"references":[{"surah":51,"verses":[56]}],"verseLabel":"الذاريات: 56","question":"ما سرّ تقديم الجن على الإنس في ﴿وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ﴾؟","answer":"من وجوه التقديم أن الجن أسبق خلقًا وتكليفًا، فوافق ترتيب الذكر هذا السبق. وفي مقام تقرير العبودية اهتمام بإبطال اعتقاد المشركين في الجن؛ إذ إن هؤلاء الذين عظموهم خُلقوا هم أيضًا لعبادة الله، كالإنس.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص672، تحت عنوان «نكتة تقديم ﴿الجن﴾ على (الإنس)»","url":""}]},{"id":"s51-31","number":31,"surah":51,"verses":[56],"references":[{"surah":51,"verses":[56]}],"verseLabel":"الذاريات: 56","question":"ما سرّ التعبير في قول ﴿إِلَّا لِيَعْبُدُونِ﴾، ولم يقل «ليطيعون» أو «ليخدمون»؟","answer":"للعبادة خصوصية في الدلالة على غاية الخضوع والتذلل التي يستحقها الله؛ أما الطاعة والخدمة ونحوهما فقد تكون للمخلوق. فاختيار العبادة يقرر اختصاص الله بهذا الحق، ويصل غاية الخلق بتوحيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص677، تحت عنوان «سر إيثار التعبير بالعبادة دون الطاعة والخدمة وغيرهما»","url":""}]},{"id":"s52-1","number":1,"surah":52,"verses":[1],"references":[{"surah":52,"verses":[1]}],"verseLabel":"الطور: 1","question":"لماذا أقسم الله بـ﴿الطُّورِ﴾ لا بلفظ «الجبل»؟","answer":"لأن الطور وإن شارك الجبل في أصل الجبلية أخص منه: فهو أقل ارتفاعًا وحجمًا، وفيه خضرة وزرع؛ فاختياره يستحضر طور سيناء بسماته لا مجرد جبل مطلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص717، تحت عنوان «سر التعبير بالطور دون الجبل»","url":""}]},{"id":"s52-33","number":33,"surah":52,"verses":[1],"references":[{"surah":52,"verses":[1]}],"verseLabel":"الطور: 1","question":"لماذا عُرّف ﴿الطُّورِ﴾ في مطلع السورة؟","answer":"لأن التعريف يوجه الذهن إلى الطور المعهود الذي كلم الله عنده موسى وأنزل عليه التوراة، فيستحضر السامع موطن الوحي المشهور لا جبلًا مجهولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص717–718، تحت عنوان «دلالة تعريف الطور»","url":""}]},{"id":"s52-2","number":2,"surah":52,"verses":[2],"references":[{"surah":52,"verses":[2]}],"verseLabel":"الطور: 2","question":"لماذا جاء القسم بـ﴿كِتَابٍ﴾ منكرًا دون أن يسمَّى؟","answer":"لتفخيم شأن الكتاب، مع إبقاء اللفظ صالحًا لما قيل فيه من الكتاب المنزل أو الكتاب الذي سطرت فيه الأعمال؛ فالتنكير يثير الهيبة ولا يحصر المقسم به في اسم واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص718–719، تحت عنوان «نكتة تنكير الكتاب»","url":""}]},{"id":"s52-34","number":34,"surah":52,"verses":[2],"references":[{"surah":52,"verses":[2]}],"verseLabel":"الطور: 2","question":"ماذا يضيف وصف الكتاب بأنه ﴿مَسْطُورٍ﴾؟","answer":"يصور الكتاب مكتوبًا كتابة ظاهرة منضبطة، باقية تُقرأ ولا تضيع؛ فيزيد المقسم به ثبوتًا وتوثيقًا، سواء أريد الوحي المكتوب أو سجل الأعمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص719، تحت عنوان «نكتة وصف الكتاب بأنه ﴿مسطور﴾»","url":""}]},{"id":"s52-3","number":3,"surah":52,"verses":[7],"references":[{"surah":52,"verses":[7]}],"verseLabel":"الطور: 7","question":"ما سرّ التعبير في قول ﴿إِنَّ عَذَابَ رَبِّكَ لَوَاقِعٌ﴾، ولم يقل «لكائن»؟","answer":"الوقوع يشعر بالشدة ويصور العذاب نازلًا محققًا، فهو أبلغ في التهديد من مجرد إثبات كونه. وتؤكد صيغة الخبر أن هذا العذاب متحقق لا يدفعه إنكار المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص725، تحت عنوان «دلالة التعبير بـ﴿لواقع﴾ دون كائن»","url":""}]},{"id":"s52-4","number":4,"surah":52,"verses":[9,10],"references":[{"surah":52,"verses":[9,10]}],"verseLabel":"الطور: 9–10","question":"ما الذي يصوره قوله يوم القيامة: ﴿تَمُورُ السَّمَاءُ مَوْرًا﴾؟","answer":"يصور السماء تضطرب وتجيء وتذهب وتدور بعد إحكامها المألوف؛ فالمور حركة شديدة مترددة، ولذلك يرسم انقلاب النظام الكوني لا حركة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص731–732، تحت عنوان «دلالة التعبير بـ﴿تمور﴾ مادة وصيغة»","url":""}]},{"id":"s52-35","number":35,"surah":52,"verses":[9,10],"references":[{"surah":52,"verses":[9,10]}],"verseLabel":"الطور: 9–10","question":"لماذا قيل عن الجبال: ﴿وَتَسِيرُ الْجِبَالُ سَيْرًا﴾؟","answer":"لأن السير ينقلها من مواضعها التي عرفت فيها بالثبات والرسوخ، فيجعل زوالها كأنه مشهد انتقال ظاهر أمام العين، ويضاعف رهبة اليوم الذي تتبدل فيه المعالم.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص733، تحت عنوان «دلالة التعبير بالسير مادة وصيغة»","url":""}]},{"id":"s52-5","number":5,"surah":52,"verses":[11],"references":[{"surah":52,"verses":[11]}],"verseLabel":"الطور: 11","question":"ما سرّ التعبير في قول ﴿فَوَيْلٌ يَوْمَئِذٍ لِلْمُكَذِّبِينَ﴾، ولم يقل «للكافرين»؟","answer":"التكذيب يصرح بموقفهم من الرسل وما أخبروا به، وهو من أسباب كفرهم. فاختياره يواجههم بالجناية التي أنكروها ثم عاينوها، ويبرز وجه استحقاقهم الوعيد في هذا السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص737، تحت عنوان «سر التعبير بالمكذبين دون الكافرين»","url":""}]},{"id":"s52-6","number":6,"surah":52,"verses":[14],"references":[{"surah":52,"verses":[14]}],"verseLabel":"الطور: 14","question":"ما سرّ حذف فعل القول في ﴿هَذِهِ النَّارُ الَّتِي كُنْتُمْ بِهَا تُكَذِّبُونَ﴾؟","answer":"دل السياق على قول مقدر: «يقال لهم: هذه النار»، فحذف فعل القول إيجازًا. ولم يعين القائل لأن المقصود توبيخ المكذبين وتقريعهم بمواجهة النار التي أنكروها، لا التعريف بمن يقول ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص741، تحت عنوان «سر حذف القول في جملة ﴿هذه النار﴾»","url":""}]},{"id":"s52-7","number":7,"surah":52,"verses":[15],"references":[{"surah":52,"verses":[15]}],"verseLabel":"الطور: 15","question":"لماذا يقال للمكذبين عند رؤية النار: ﴿أَفَسِحْرٌ هَذَا﴾؟","answer":"توبيخًا وتهكمًا بهم؛ فقد سموا الوحي سحرًا في الدنيا، فلما صار العذاب حاضرًا واجههم السؤال بدعواهم نفسها، ليظهر عجز المكابرة حين تقع الحقيقة التي أنكروها.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص746–747، تحت عنوان «بلاغة الاستفهام في قوله: ﴿أفسحر هذا﴾»","url":""}]},{"id":"s52-36","number":36,"surah":52,"verses":[15],"references":[{"surah":52,"verses":[15]}],"verseLabel":"الطور: 15","question":"ما الذي يضيّقه عليهم السؤال: ﴿أَمْ أَنْتُمْ لَا تُبْصِرُونَ﴾؟","answer":"يحصرهم في احتمالين كلاهما يفضحهم: أهذا العذاب سحر كما زعموا في الحق، أم ما زالوا لا يبصرون مع حضوره؟ وبذلك تنقطع أعذارهم ويثبت أن إنكارهم كان عنادًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص748، تحت عنوان «سر التعبير بـ﴿أم﴾، ودلالة الاستفهام بها»","url":""}]},{"id":"s52-8","number":8,"surah":52,"verses":[17],"references":[{"surah":52,"verses":[17]}],"verseLabel":"الطور: 17","question":"ما سرّ وصف أهل الجنة هنا بـ﴿الْمُتَّقِينَ﴾ لا «الذين اتقوا»؟","answer":"اسم الفاعل يبرز رسوخ التقوى وتمكنها فيهم حتى صارت صفة يعرفون بها، بينما «الذين اتقوا» يلحظ وقوع الفعل. فالوصف يصور مقامهم المستقر الذي ناسب ما أعد لهم من النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص760، تحت عنوان «سر التعبير باسم الفاعل ﴿المتقين﴾ دون (الذين اتقوا)»","url":""}]},{"id":"s52-9","number":9,"surah":52,"verses":[18],"references":[{"surah":52,"verses":[18]}],"verseLabel":"الطور: 18","question":"ما سرّ التعبير في قول ﴿بِمَا آتَاهُمْ رَبُّهُمْ﴾، ولم يقل «بما أعطاهم»؟","answer":"يوجه المبحث الإيتاء إلى قوة ثبوت العطاء واستقراره للمؤمنين، بخلاف الإعطاء الذي لا يفيد هذا الثبوت بالقوة نفسها. وصيغة الماضي تحقق الوعد، فيطمئنون إلى نعيم لا ينقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص763، تحت عنوان «دلالة التعبير بفعل الإيتاء مادة وصيغة»","url":""}]},{"id":"s52-10","number":10,"surah":52,"verses":[20],"references":[{"surah":52,"verses":[20]}],"verseLabel":"الطور: 20","question":"لماذا قيل عن أهل الجنة: ﴿عَلَى سُرُرٍ﴾ ولم يقل «على الأرائك»؟","answer":"لأن السرير أعم في تصوير مجلس الراحة والملك، أما الأريكة فسرير داخل حجلة؛ والسياق يريد إبراز المجالس الظاهرة المتقابلة التي يجتمع عليها أهل النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص770، تحت عنوان «سر التعبير بالسرر دون الأرائك»","url":""}]},{"id":"s52-37","number":37,"surah":52,"verses":[20],"references":[{"surah":52,"verses":[20]}],"verseLabel":"الطور: 20","question":"ماذا يصور وصف سرر الجنة بأنها ﴿مَصْفُوفَةٍ﴾؟","answer":"يصورها منسقة متجاورة لا متفرقة، فيجتمع أهلها في أنس وتواصل ويتقابلون من غير تدابر؛ فالصف يزيد مشهد النعيم نظامًا وألفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص771، تحت عنوان «فائدة وصف السرر بأنها ﴿مصفوفة﴾»","url":""}]},{"id":"s52-11","number":11,"surah":52,"verses":[20],"references":[{"surah":52,"verses":[20]}],"verseLabel":"الطور: 20","question":"ما سرّ التعبير في قول ﴿وَزَوَّجْنَاهُمْ بِحُورٍ عِينٍ﴾ بالباء، ولم يقل «زوجناهم حورًا»؟","answer":"التعدية بالباء تلائم معنى قرناهم بحور عين وجعلناهن في صحبتهم؛ فالتزويج هنا يلحظ الاقتران والأنس. أما التزويج بمعنى عقد النكاح فيتعدى بنفسه؛ فاختيار الباء يبرز المعنى المقصود في مقام النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص772، تحت عنوان «دلالة تعدية الفعل ﴿وزوجناهم﴾ بالباء»","url":""}]},{"id":"s52-12","number":12,"surah":52,"verses":[21],"references":[{"surah":52,"verses":[21]}],"verseLabel":"الطور: 21","question":"لماذا قيل: ﴿وَالَّذِينَ آمَنُوا﴾ ولم يقل «والمؤمنون»؟","answer":"لأن الموصول وصلته يبرزان الإيمان فعلًا تحقق ورسخ في الآباء، وهو سبب الإكرام بإلحاق الذرية بهم؛ فالصياغة تستحضر ما صنعوه من إيمان لا مجرد اسم الفئة.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص780، تحت عنوان «سر التعبير بقوله: ﴿والذين آمنوا﴾ دون (المؤمنون)»","url":""}]},{"id":"s52-13","number":13,"surah":52,"verses":[21],"references":[{"surah":52,"verses":[21]}],"verseLabel":"الطور: 21","question":"ما سرّ التعبير في قول ﴿ذُرِّيَّتُهُمْ﴾، ولم يقل «أبناؤهم»؟","answer":"الذرية أوسع في الدلالة على النسل؛ فتشمل الذكور والإناث والصغار والكبار والواحد والجمع، مع إبراز صلة الانتماء إلى الآباء. أما الأبناء فأخص في أصل دلالته، فاختيار الذرية أتم في بيان نعمة جمع المؤمن بأهله ونسله.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص781–782، تحت عنوان «دلالة التعبير بلفظ الذرية دون الأبناء»","url":""}]},{"id":"s52-14","number":14,"surah":52,"verses":[21],"references":[{"surah":52,"verses":[21]}],"verseLabel":"الطور: 21","question":"ماذا يوحي قوله عن ذرية المؤمنين: ﴿أَلْحَقْنَا بِهِمْ ذُرِّيَّتَهُمْ﴾؟","answer":"يوحي برفع الذرية إلى درجة الآباء وجمع شمل الأسرة في الجنة، لا بمجرد إدخالهم إليها؛ فالإلحاق فضل يكمل به سرور الآباء من غير أن يجعل الذرية مساوية لهم بعملها.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص783، تحت عنوان «دلالة التعبير بالإلحاق»","url":""}]},{"id":"s52-38","number":38,"surah":52,"verses":[21],"references":[{"surah":52,"verses":[21]}],"verseLabel":"الطور: 21","question":"لماذا قيل: ﴿وَمَا أَلَتْنَاهُمْ مِنْ عَمَلِهِمْ مِنْ شَيْءٍ﴾؟","answer":"لينفي أن يكون رفع الذرية مقتطعًا من ثواب الآباء؛ فـ﴿ألتناهم﴾ تفيد النقص، ونفيها مع العموم يقرر أن أجورهم محفوظة كاملة وأن الإلحاق زيادة فضل محض.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص785، تحت عنوان «دلالة التعبير بـ﴿ألتناهم﴾ مادة وصيغة»","url":""}]},{"id":"s52-15","number":15,"surah":52,"verses":[21],"references":[{"surah":52,"verses":[21]}],"verseLabel":"الطور: 21","question":"ما سرّ التعبير في قول ﴿كُلُّ امْرِئٍ بِمَا كَسَبَ رَهِينٌ﴾، ولم يقل «بما عمل»؟","answer":"الكسب يلحظ عمل الإنسان الذي يجترحه ويحصله لنفسه، فيشعر باقتران العمل بصاحبه وما يترتب عليه. ولذلك ناسب صورة الرهن؛ فكل امرئ مرتبط بما اكتسب، وإن كان نفس العمل قد مضى وانقضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص789، تحت عنوان «دلالة التعبير بالكسب مادة وصيغة»","url":""}]},{"id":"s52-16","number":16,"surah":52,"verses":[22],"references":[{"surah":52,"verses":[22]}],"verseLabel":"الطور: 22","question":"ما دلالة إفراد ﴿بفاكهة﴾ مع كثرة فواكه الجنة؟","answer":"﴿فاكهة﴾ اسم جنس يدل على الأنواع الكثيرة، فلا يفيد إفراد اللفظ قلة النعيم. وقد سبق جمع الجنات، فناسب المقام ذكر جنس الفاكهة الذي يشمل ما يتنعم به أهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص791، تحت عنوان «سر التعبير بـ﴿بفاكهة﴾ دون فواكه»","url":""}]},{"id":"s52-17","number":17,"surah":52,"verses":[23],"references":[{"surah":52,"verses":[23]}],"verseLabel":"الطور: 23","question":"لماذا خُص ﴿اللَّغْوُ﴾ بالنفي عن شراب الجنة؟","answer":"لأن أبرز ما يفسد مجالس الخمر في الدنيا ما يجره ذهاب العقل من كلام ساقط وسباب وضرب؛ فنفي اللغو يفرق شراب الجنة عنها، إذ تبقى لذته خالصة لا تعقبها خفة ولا باطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج57، ص795، تحت عنوان «سر نفي اللغو دون غيره في قوله: ﴿لا لغو فيها﴾»","url":""}]},{"id":"s52-18","number":18,"surah":52,"verses":[26],"references":[{"surah":52,"verses":[26]}],"verseLabel":"الطور: 26","question":"ما سرّ التعبير في قول أهل الجنة ﴿إِنَّا كُنَّا قَبْلُ فِي أَهْلِنَا مُشْفِقِينَ﴾، ولم يقل «خائفين»؟","answer":"الإشفاق خوف يصحبه حذر وترحم، فلا يقتصر على مجرد توقع المكروه. وذكره في حال كونهم بين أهلهم يصور دوام حذرهم في موطن الأنس والأمان المعتاد؛ فلم تشغلهم الراحة عن الاستعداد للآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص16، تحت عنوان «دلالة التعبير بـ﴿مشفقين﴾ مادة وصيغة»","url":""}]},{"id":"s52-19","number":19,"surah":52,"verses":[28],"references":[{"surah":52,"verses":[28]}],"verseLabel":"الطور: 28","question":"لماذا قال أهل الجنة: ﴿إِنَّا كُنَّا مِنْ قَبْلُ نَدْعُوهُ﴾ ولم يقولوا «نعبده»؟","answer":"لأن الدعاء يجمع عبادتهم وسؤالهم وتضرعهم والتجاءهم إلى الله في كل شأن؛ فهو أوسع في تصوير تعلقهم به من لفظ يذكر جانب العبادة وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص20، تحت عنوان «دلالة التعبير بالدعاء مادة وصيغة»","url":""}]},{"id":"s52-39","number":39,"surah":52,"verses":[28],"references":[{"surah":52,"verses":[28]}],"verseLabel":"الطور: 28","question":"لماذا لم يذكروا ما الذي كانوا يدعون الله به في قولهم: ﴿نَدْعُوهُ﴾؟","answer":"ليعم دعاؤهم كل أبواب الخير؛ فقد كانوا يسألونه النجاة والرحمة والفوز وسائر الحاجات، فحذف المطلوب يصور دوام افتقارهم إلى الله في أمورهم كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص20، تحت عنوان «نكتة حذف متعلق ﴿ندعوه﴾»","url":""}]},{"id":"s52-20","number":20,"surah":52,"verses":[28],"references":[{"surah":52,"verses":[28]}],"verseLabel":"الطور: 28","question":"لماذا ختموا بقولهم ﴿إِنَّهُ هُوَ الْبَرُّ الرَّحِيمُ﴾؟","answer":"البر هو المحسن إلى عباده، والرحيم واسع الرحمة بهم؛ فالوصفان يبينان سبب رجائهم ودعائهم، ويناسبان ما شاهدوه من استجابة ونجاة ونعيم. وفي الختم بهما اعتراف بأن هذا الفضل من إحسان الله ورحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص21، تحت عنوان «سر تذييل الآية الكريمة بهذين الوصفين»","url":""}]},{"id":"s52-21","number":21,"surah":52,"verses":[29],"references":[{"surah":52,"verses":[29]}],"verseLabel":"الطور: 29","question":"لماذا نُفي عن النبي ﷺ في الطور أن يكون كاهنًا أو مجنونًا، بينما اقتصر في القلم على نفي الجنون؟","answer":"لأن سورة الطور عرضت سلسلة دعاواهم: الكهانة والجنون والشعر وتقوّل القرآن، فناسبها تفصيل الرد على افتراءاتهم. أما مطلع القلم فكان الاتهام البارز فيه الجنون، فجاء النفي مطابقًا لما يواجهه السياق هناك.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص30، تحت عنوان «سر زيادة نفي الكهانة مع الجنون في سورة الطور بخلاف سورة القلم»","url":""}]},{"id":"s52-22","number":22,"surah":52,"verses":[30],"references":[{"surah":52,"verses":[30]}],"verseLabel":"الطور: 30","question":"لماذا قال المكذبون عن النبي ﷺ: ﴿نَتَرَبَّصُ بِهِ﴾ ولم يقولوا «ننتظر»؟","answer":"لأن التربص انتظارٌ مقصود لما يسوء، فيه ترقب وتأمل وتمهل؛ فاختيار اللفظ يكشف خبث أملهم في أن يطول انتظارهم حتى تنتهي الدعوة بزوال صاحبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص32–33، تحت عنوان «دلالة التعبير بـ﴿نتربص﴾ مادة وصيغة»","url":""}]},{"id":"s52-40","number":40,"surah":52,"verses":[30],"references":[{"surah":52,"verses":[30]}],"verseLabel":"الطور: 30","question":"ماذا يوحي وصفهم ما ينتظرونه بـ﴿رَيْبِ﴾ المنون؟","answer":"يوحي بحوادث الدهر المفاجئة التي لا تؤمن ولا تستقر على حال؛ فهم لا يذكرون موتًا هادئًا فقط، بل يترقبون نازلة قاطعة تنهي أمر النبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص33، تحت عنوان «دلالة التعبير بلفظ ﴿ريب﴾»","url":""}]},{"id":"s52-41","number":41,"surah":52,"verses":[30],"references":[{"surah":52,"verses":[30]}],"verseLabel":"الطور: 30","question":"لماذا عبّروا عن الموت أو الدهر بـ﴿الْمَنُونِ﴾؟","answer":"لأن اللفظ مشتق من القطع؛ فالموت يقطع الحياة، والدهر يقطع الأعمار بما ينزل فيها من أحداث، فيصور أمنيتهم في قوةٍ قاطعة تطوي الدعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص34، تحت عنوان «سر التعبير بالمنون»","url":""}]},{"id":"s52-23","number":23,"surah":52,"verses":[32],"references":[{"surah":52,"verses":[32]}],"verseLabel":"الطور: 32","question":"ما سرّ التعبير في قول ﴿أَمْ تَأْمُرُهُمْ أَحْلَامُهُمْ بِهَذَا﴾، ولم يقل «عقولهم»؟","answer":"الحلم عقل يصحبه تأن وروية وكمال رشد، فهو أخص من مطلق العقل. والتعبير به يتهكم بمن يزعمون هذه المنزلة ثم تصدر عنهم أقوال متناقضة؛ فلو كانت أحلامهم ترشدهم لما أوقعتهم في هذا الاضطراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص42، تحت عنوان «نكتة التعبير بـ(الأحلام) دون العقول»","url":""}]},{"id":"s52-24","number":24,"surah":52,"verses":[33],"references":[{"surah":52,"verses":[33]}],"verseLabel":"الطور: 33","question":"لماذا قالوا عن القرآن: ﴿تَقَوَّلَهُ﴾ ولم يقولوا «افتراه»؟","answer":"لأن التقول يخص اختلاق قولٍ وتكلفه من النفس، فجاء أدق في تصوير زعمهم أن النبي ﷺ أنشأ هذا القرآن ثم نسبه إلى الله؛ أما الافتراء فأعم من اختلاق الأقوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص46، تحت عنوان «دلالة التعبير بـ﴿تقوله﴾ مادة وصيغة»","url":""}]},{"id":"s52-25","number":25,"surah":52,"verses":[35],"references":[{"surah":52,"verses":[35]}],"verseLabel":"الطور: 35","question":"لماذا سألهم القرآن: ﴿أَمْ خُلِقُوا مِنْ غَيْرِ شَيْءٍ﴾ ولم يقل «من غير خالق»؟","answer":"لأن ﴿شيء﴾ تعم كل احتمال يتوهمونه: أوجدوا بلا خالق، أم خُلقوا من غير أصل، أم من عدم محض؟ وكل فرض باطل، فتضيق عليهم سبل الإنكار ويلزمهم الإقرار بخالقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص59–60، تحت عنوان «دلالة التعبير بقوله: ﴿من غير شيء﴾ دون (من غير خالق)»","url":""}]},{"id":"s52-42","number":42,"surah":52,"verses":[35],"references":[{"surah":52,"verses":[35]}],"verseLabel":"الطور: 35","question":"ما قوة المقابلة بين ﴿خُلِقُوا﴾ و﴿أَمْ هُمُ الْخَالِقُونَ﴾؟","answer":"تنقلهم من حقيقة كونهم مخلوقين إلى الفرض المستحيل أنهم خلقوا أنفسهم؛ فإذا بطل أن يوجدوا بلا خالق وبطل أن يكونوا خالقي أنفسهم ثبت افتقارهم إلى الله في أقصر حجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص61، تحت عنوان «بلاغة المقابلة بين ﴿خلقوا﴾ و﴿أم هم الخالقون﴾»","url":""}]},{"id":"s52-26","number":26,"surah":52,"verses":[37],"references":[{"surah":52,"verses":[37]}],"verseLabel":"الطور: 37","question":"لماذا قيل في الطور ﴿خَزَائِنُ رَبِّكَ﴾ بلا وصف الرحمة، وقيل في ص ﴿خَزَائِنُ رَحْمَةِ رَبِّكَ﴾؟","answer":"لأن سؤال الطور يبطل أن يملكوا خزائن الله كلها فيتصرفوا في العطاء والمنع والنفع والضر، فناسب العموم. أما سورة ص فترد اعتراضهم على اختصاص محمد ﷺ بالوحي، والنبوة رحمة، فناسب التصريح بخزائن الرحمة هناك.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص67، تحت عنوان «سر تجريد الخزائن من وصف الرحمة»","url":""}]},{"id":"s52-27","number":27,"surah":52,"verses":[38],"references":[{"surah":52,"verses":[38]}],"verseLabel":"الطور: 38","question":"ما سرّ التعبير في قول ﴿أَمْ لَهُمْ سُلَّمٌ يَسْتَمِعُونَ فِيهِ﴾، ولم يقل «مصعد»؟","answer":"السلم يلحظ الصعود والمعارج التي توصل إلى مكان مرتفع، فيلائم دعواهم الوصول إلى خبر السماء. أما المصعد فقد يطلق على نفس الصعود أو مكانه؛ فذكر السلم يجسم الوسيلة التي يلزمهم إثباتها، ثم يطالبهم الدليل على ما زعموا أنهم سمعوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص70، تحت عنوان «سر التعبير بـ﴿سلم﴾ دون غيره»","url":""}]},{"id":"s52-28","number":28,"surah":52,"verses":[42],"references":[{"surah":52,"verses":[42]}],"verseLabel":"الطور: 42","question":"لماذا كشف تدبيرهم بقوله: ﴿أَمْ يُرِيدُونَ كَيْدًا﴾؟","answer":"لأن الإرادة تدل على تعمد طلب الشيء والسعي إليه؛ فالسؤال لا يصور كيدهم خاطرة عارضة، بل نيةً مصرّة مدبرة للتخلص من النبي ﷺ وإطفاء دعوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص90، تحت عنوان «سر التعبير بالإرادة في قوله: ﴿أم يريدون﴾»","url":""}]},{"id":"s52-43","number":43,"surah":52,"verses":[42],"references":[{"surah":52,"verses":[42]}],"verseLabel":"الطور: 42","question":"كيف يقلب قوله: ﴿فَالَّذِينَ كَفَرُوا هُمُ الْمَكِيدُونَ﴾ الكيد على أصحابه؟","answer":"يقصر وقوع الكيد عليهم هم؛ فمن خططوا لإيذاء النبي ﷺ يصيرون هم المحاطين بجزاء تدبيرهم، فيتحول تهديدهم إلى وعيد لهم وتثبيت للرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص92–93، تحت عنوان «بلاغة التعبير بأسلوب القصر»","url":""}]},{"id":"s52-29","number":29,"surah":52,"verses":[44],"references":[{"surah":52,"verses":[44]}],"verseLabel":"الطور: 44","question":"لماذا لو رأى المكذبون قطعة من السماء ساقطة سموها ﴿سَحَابٌ﴾؟","answer":"لأن السحاب في أصله ما ينسحب ويمتد في الهواء، ويطلق على الغيم سواء حمل ماء أم خلا منه؛ فسموا القطعة الساقطة سحابًا ليصرفوا مشهد العذاب الواضح إلى غيم عابر مألوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص108، تحت عنوان «سر التعبير بالسحاب»","url":""}]},{"id":"s52-44","number":44,"surah":52,"verses":[44],"references":[{"surah":52,"verses":[44]}],"verseLabel":"الطور: 44","question":"ماذا يضيف وصف السحاب في زعمهم بأنه ﴿مَرْكُومٌ﴾؟","answer":"يصوره متراكبًا بعضه فوق بعض، فيجعلون ثقل القطعة الساقطة وكثافتها مجرد سحاب ممطر متجمع؛ وهكذا يبلغ بهم العناد أن يؤولوا المشهد المخيف تأويلًا معتادًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص108–109، تحت عنوان «فائدة وصف السحاب بأنه ﴿مركوم﴾»","url":""}]},{"id":"s52-30","number":30,"surah":52,"verses":[45],"references":[{"surah":52,"verses":[45]}],"verseLabel":"الطور: 45","question":"ما سرّ التعبير في قول ﴿فَذَرْهُمْ﴾، ولم يقل «فاتركهم»؟","answer":"﴿ذرهم﴾ تلحظ تركهم وإهمال شأنهم لقلة الاعتداد بهم، وهو أخص من مطلق الترك. وفي الأمر تهديد بأنهم سيلاقون عاقبة عنادهم، وتسلية للنبي عن إصرار من لا يستجيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص110، تحت عنوان «سر التعبير بقوله: ﴿فذرهم﴾، دون (اتركهم)»","url":""}]},{"id":"s52-31","number":31,"surah":52,"verses":[48],"references":[{"surah":52,"verses":[48]}],"verseLabel":"الطور: 48","question":"ماذا يوحي جمع الأعين وإضافتها إلى الله في قوله للنبي ﷺ: ﴿فَإِنَّكَ بِأَعْيُنِنَا﴾؟","answer":"يبالغ في تصوير إحاطة العناية والحفظ بالنبي ﷺ؛ فكأن كل ما يراد حراسته واقع تحت رعاية لا تغيب، وإضافة الأعين إلى ضمير العظمة تزيد الطمأنينة والتشريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص128، تحت عنوان «نكتة جمع الأعين وإضافتها»","url":""}]},{"id":"s52-32","number":32,"surah":52,"verses":[49],"references":[{"surah":52,"verses":[49]}],"verseLabel":"الطور: 49","question":"كيف يتصل افتتاح سورة النجم بسورة الطور قبلها؟","answer":"كلتا السورتين تبدأ بقسم بمقدسات عظيمة: قسم الطور يقرر وقوع العذاب، وقسم النجم ينزه النبي ﷺ عن الضلال والهوى. كما تتابع النجم رد التهم التي عرضتها الطور من الشعر والكهانة والجنون والافتراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص141، تحت عنوان «مناسبة السورة لما قبلها»","url":""}]},{"id":"s52-45","number":45,"surah":52,"verses":[49],"references":[{"surah":52,"verses":[49]}],"verseLabel":"الطور: 49","question":"لماذا قُيّد القسم بالنجم بوقت هويه في قوله: ﴿وَالنَّجْمِ إِذَا هَوَى﴾؟","answer":"لأن سقوطه إلى المغيب مشهد ظاهر لخضوع هذا الجرم العظيم لنظام الله، وفيه تشبيه موحٍ بسقوط الشهب على الشياطين؛ فالقسم بحاله عند الهوي أنسب لإبطال ضلال المشركين وتثبيت الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص146–147، تحت عنوان «سر تقييد القسم بالنجم بوقت غروبه»","url":""}]},{"id":"s53-1","number":1,"surah":53,"verses":[1],"references":[{"surah":53,"verses":[1]}],"verseLabel":"النجم: 1","question":"لماذا اختير ﴿هَوَى﴾ بدل «سقط» في مطلع سورة النجم؟","answer":"لأن الهوي يصور حركة سريعة من علو إلى سفل، فيناسب أفول النجم وسقوط الشهب ونزول الوحي، ويستحضر مشهد الحركة لا مجرد بلوغ الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص147–148، تحت عنوان «سر إيثار الفعل ﴿هوى﴾ مادة وصيغة»","url":""}]},{"id":"s53-40","number":40,"surah":53,"verses":[1],"references":[{"surah":53,"verses":[1]}],"verseLabel":"النجم: 1","question":"كيف جمع لفظ ﴿هَوَى﴾ في مطلع السورة بين الحقيقة والمجاز؟","answer":"يصدق حقيقة على هبوط النجم أو غروبه، ويتسع مجازًا لنزول جبريل أو نجوم القرآن؛ فلفظ واحد يلائم المقسم به وما يمهد له من ذكر الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص148، تحت عنوان «براعة استعمال لفظ ﴿هوى﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s53-2","number":2,"surah":53,"verses":[2],"references":[{"surah":53,"verses":[2]}],"verseLabel":"النجم: 2","question":"ما سرّ التعبير في قول ﴿صَاحِبُكُمْ﴾، ولم يقل «محمد»؟","answer":"وصفه بالصاحب وإضافته إليهم يحتج بمعرفتهم الطويلة بأحواله وصدقه وأمانته. فهو الذي عاشروه وخبروا سيرته، فتكون هذه المعرفة أدعى إلى قبول خبره، وأشد تبكيتًا لهم على اتهامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص151–152، تحت عنوان «دلالة لفظ الصحبة وإضافته إلى ضمير الخطاب»","url":""}]},{"id":"s53-3","number":3,"surah":53,"verses":[2],"references":[{"surah":53,"verses":[2]}],"verseLabel":"النجم: 2","question":"لماذا كرر «ما» فقال ﴿مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَى﴾؟","answer":"تكرار النفي يجعل الضلال والغواية منفيين كلًّا على حدة، ويؤكد تنزيهه عنهما استقلالًا. ولو اقتصر النفي على الأول وعطف الثاني من غير إعادته لاحتمل نفي اجتماعهما وحده، فجاء التكرار لدفع هذا الاحتمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص152–153، تحت عنوان «سر تكرار (ما) النافية»","url":""}]},{"id":"s53-4","number":4,"surah":53,"verses":[2],"references":[{"surah":53,"verses":[2]}],"verseLabel":"النجم: 2","question":"لماذا جُمع بين نفي الضلال ونفي الغواية عن النبي ﷺ؟","answer":"لأن الضلال خلل في العلم والطريق، والغواية خلل في القصد والعمل؛ فنفيهما يجمع كمال معرفته ورشده مع استقامة غايته وفعله، ويرد وجهي طعن المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص152، تحت عنوان «وجه العطف بالواو في ﴿وما غوى﴾»","url":""}]},{"id":"s53-5","number":5,"surah":53,"verses":[3],"references":[{"surah":53,"verses":[3]}],"verseLabel":"النجم: 3","question":"ما سرّ التعبير في قول ﴿وَمَا يَنْطِقُ عَنِ الْهَوَى﴾ بـ«عن»، ولم يقل «بالهوى»؟","answer":"﴿عن﴾ تبين مبدأ صدور النطق، فتنفي أن يكون الهوى منبعه والدافع إليه. وهذا أدق في تنزيه الوحي من مجرد وصف الكلام بأنه ملتبس بالهوى؛ إذ يطهر مصدره وباعثه من الأصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص154، تحت عنوان «معنى ﴿عن﴾ في قوله: ﴿عن الهوى﴾»","url":""}]},{"id":"s53-6","number":6,"surah":53,"verses":[4],"references":[{"surah":53,"verses":[4]}],"verseLabel":"النجم: 4","question":"ما الذي يحسمه الحصر في قوله ﴿إِنْ هُوَ إِلَّا وَحْيٌ يُوحَى﴾؟","answer":"يحصر ما يبلغه النبي ﷺ عن الله في الوحي، فيبطل دعاوى الشعر والكهانة والاختلاق، ويؤكد أن مصدر القرآن إلهي لا هوى نفسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص162، تحت عنوان «بلاغة الاستثناء بـ﴿إلا﴾»","url":""}]},{"id":"s53-7","number":7,"surah":53,"verses":[5,6],"references":[{"surah":53,"verses":[5,6]}],"verseLabel":"النجم: 5–6","question":"ماذا يفيد وصف جبريل بأنه ﴿شَدِيدُ الْقُوَى﴾؟","answer":"يفيد كمال قواه المتعددة اللازمة لحمل الوحي: الإدراك والحفظ والأمانة والأداء، فيطمئن السامع إلى قوة المعلّم وسلامة ما بلغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص165، تحت عنوان «دلالة لفظ ﴿شديد﴾ معرفًا بالإضافة»","url":""}]},{"id":"s53-41","number":41,"surah":53,"verses":[5,6],"references":[{"surah":53,"verses":[5,6]}],"verseLabel":"النجم: 5–6","question":"ماذا يضيف وصف جبريل بأنه ﴿ذُو مِرَّةٍ﴾؟","answer":"يضيف معنى متانة العقل والخلق وكمال الهيئة والقوة؛ فهو وصف آخر مستقل يكمل صورة جبريل المؤهل لهذه الرسالة العظيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص166، تحت عنوان «دلالة تعديد الوصف بجملة ﴿ذو مرة﴾»","url":""}]},{"id":"s53-8","number":8,"surah":53,"verses":[7],"references":[{"surah":53,"verses":[7]}],"verseLabel":"النجم: 7","question":"ما سرّ وصف الأفق في النجم بـ﴿الْأُفُقِ الْأَعْلَى﴾؟","answer":"وصف الأفق بالأعلى يحدد جهة الرؤية ويبرز رفعة المشهد، مع الاحتراز من إرادة أفق الأرض. فيصور ظهور جبريل في ناحية عالية واضحة من السماء، مما يلائم جلال هذا اللقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص169–170، تحت عنوان «نكتة وصف (الأفق) بالأعلى»","url":""}]},{"id":"s53-9","number":9,"surah":53,"verses":[8],"references":[{"surah":53,"verses":[8]}],"verseLabel":"النجم: 8","question":"ماذا أضاف ﴿فَتَدَلَّى﴾ بعد قوله ﴿ثُمَّ دَنَا﴾؟","answer":"أضاف إلى مجرد القرب هيئة النزول من علو والاقتراب حتى اكتملت صورة اللقاء؛ فالدنو مسافة، والتدلي حركة تشوق إلى لحظة الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص171، تحت عنوان «دلالة فعل التدلي ماضيًا»","url":""}]},{"id":"s53-42","number":42,"surah":53,"verses":[8],"references":[{"surah":53,"verses":[8]}],"verseLabel":"النجم: 8","question":"كيف يُفهم ترتيب ﴿دَنَا فَتَدَلَّى﴾ مع أن التدلي يوصل إلى الدنو؟","answer":"يجوز أن يكون في الكلام قلب يراد به تدلى فدنا، أو أن يكون الترتيب منظورًا إليه من جهة تلقي النبي ﷺ للمشهد؛ وفي الوجهين يصور النظم شدة القرب وتتابع الحركة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص172، تحت عنوان «فن القلب في الآية»","url":""}]},{"id":"s53-10","number":10,"surah":53,"verses":[9],"references":[{"surah":53,"verses":[9]}],"verseLabel":"النجم: 9","question":"لماذا صُوِّر قرب جبريل بمقدار ﴿قَابَ قَوْسَيْنِ﴾؟","answer":"لتحويل شدة القرب إلى صورة حسية مألوفة: قوسان متجاوران يوشكان أن يتماسا، وهي كناية عن نهاية القرب وصفاء اللقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص173، تحت عنوان «بلاغة التشبيه والكناية في قوله: ﴿قاب قوسين﴾»","url":""}]},{"id":"s53-43","number":43,"surah":53,"verses":[9],"references":[{"surah":53,"verses":[9]}],"verseLabel":"النجم: 9","question":"هل تدل ﴿أَوْ﴾ في ﴿قَابَ قَوْسَيْنِ أَوْ أَدْنَى﴾ على الشك؟","answer":"لا؛ فهي بحسب تقدير الناظر: إن قدّر المسافة قال قاب قوسين أو أقرب، أو هي بمعنى بل. وفي الحالين تؤكد غاية القرب ولا تنسب ترددًا إلى علم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص174، تحت عنوان «توجيه العطف بـ﴿أو﴾»","url":""}]},{"id":"s53-11","number":11,"surah":53,"verses":[10],"references":[{"surah":53,"verses":[10]}],"verseLabel":"النجم: 10","question":"ما سرّ التعبير في قول ﴿فَأَوْحَى إِلَى عَبْدِهِ﴾ ولم يسم النبي؟","answer":"إضافة العبد إلى الله تشريف وتكريم، وتبرز أن غاية الرفعة تتحقق بكمال العبودية. ولم يحتج السياق إلى التصريح باسمه لظهور المقصود؛ فاختير الوصف الذي يجمع بيان المنزلة وتعظيم الإيحاء إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص176، تحت عنوان «سر التعبير بلفظ ﴿عبده﴾ معرفًا بالإضافة»","url":""}]},{"id":"s53-12","number":12,"surah":53,"verses":[11],"references":[{"surah":53,"verses":[11]}],"verseLabel":"النجم: 11","question":"ما الصورة البلاغية في قوله ﴿مَا كَذَبَ الْفُؤَادُ مَا رَأَى﴾؟","answer":"صُوّر الفؤاد كأنه شاهد يصدق أو يكذب، وحذف المشبه به؛ لتأكيد توافق بصيرة النبي ﷺ مع بصره في صدق الرؤية.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص184، تحت عنوان «بلاغة الاستعارة في الآية»","url":""}]},{"id":"s53-13","number":13,"surah":53,"verses":[12],"references":[{"surah":53,"verses":[12]}],"verseLabel":"النجم: 12","question":"ما غرض الاستفهام في ﴿أَفَتُمَارُونَهُ عَلَى مَا يَرَى﴾؟","answer":"هو إنكار جدالهم وتوبيخهم؛ لأنهم يجادلون الصادق الأمين في مشاهدة مباشرة اختص بها، من غير علم يقابل يقينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص184، تحت عنوان «بلاغة الاستفهام بالهمزة في ﴿أفتمارونه﴾»","url":""}]},{"id":"s53-44","number":44,"surah":53,"verses":[12],"references":[{"surah":53,"verses":[12]}],"verseLabel":"النجم: 12","question":"ماذا يصور فعل ﴿تُمَارُونَهُ﴾ في موقف المكذبين؟","answer":"يصوّر جدالهم كأنهم يفتلون المرية ويجذبون صاحب الحق إليها؛ فليس فعلهم تكذيبًا عابرًا، بل محاولة متكررة لزعزعة يقينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص185، تحت عنوان «بلاغة الاستعارة في الفعل (تمارون)»","url":""}]},{"id":"s53-14","number":14,"surah":53,"verses":[13],"references":[{"surah":53,"verses":[13]}],"verseLabel":"النجم: 13","question":"لماذا قيل ﴿نَزْلَةً﴾ بدل «مرة» في رؤية جبريل؟","answer":"لأن نزلة مصدر مرة يجمع تكرر الرؤية مع هيئة نزول جبريل، بخلاف مرة التي لا تصور كيفية اللقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص192، تحت عنوان «سر التعبير بالمصدر الدال على المرة ﴿نزلة﴾»","url":""}]},{"id":"s53-45","number":45,"surah":53,"verses":[13],"references":[{"surah":53,"verses":[13]}],"verseLabel":"النجم: 13","question":"ماذا يفيد وصف النزلة بأنها ﴿أُخْرَى﴾؟","answer":"يثبت أنها رؤية ثانية مغايرة للأولى، وقعت في عالم علوي عند سدرة المنتهى، فيؤكد تعدد المشاهدة وحقيقتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص192، تحت عنوان «نكتة وصف ﴿نزلة﴾ بـ﴿أخرى﴾»","url":""}]},{"id":"s53-15","number":15,"surah":53,"verses":[14,15,16],"references":[{"surah":53,"verses":[14,15,16]}],"verseLabel":"النجم: 14–16","question":"لماذا تكرر ﴿عِنْدَ﴾ في قوله ﴿عِنْدَ سِدْرَةِ الْمُنْتَهَى عِنْدَهَا جَنَّةُ الْمَأْوَى﴾؟","answer":"لاختلاف المتعلق: الأول يحدد موضع رؤية جبريل، والثاني يبين موضع جنة المأوى؛ ويؤكد التكرار شرف المكان وقرب المشاهد العظيمة بعضها من بعض.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص194–195، تحت عنوان «سر تكرار ظرف المكان ﴿عندها﴾ وعود الضمير فيه»","url":""}]},{"id":"s53-46","number":46,"surah":53,"verses":[14,15,16],"references":[{"surah":53,"verses":[14,15,16]}],"verseLabel":"النجم: 14–16","question":"لماذا أعيد لفظ ﴿السِّدْرَةِ﴾ بدل الاكتفاء بالضمير؟","answer":"لزيادة العناية بها وتعظيم شأنها، وتعريفها بالعهد يربطها بسدرة المنتهى المذكورة قبل، فلا تكون سدرة مجهولة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص197، تحت عنوان «نكتة تكرار لفظ ﴿السدرة﴾ معرفًا بـ(الـ) دون الإضافة»","url":""}]},{"id":"s53-16","number":16,"surah":53,"verses":[17],"references":[{"surah":53,"verses":[17]}],"verseLabel":"النجم: 17","question":"كيف يكمل نفي الزيغ ونفي الطغيان صورة بصر النبي ﷺ؟","answer":"نفي الزيغ يثبت أنه لم يمل عن المرئي، ونفي الطغيان أنه لم يتجاوز الحد المأذون له؛ فاجتمع ثبات النظر وكمال الأدب وصدق المشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص200–201، تحت عنوان «سر تكرار (ما) النافية»","url":""}]},{"id":"s53-17","number":17,"surah":53,"verses":[17],"references":[{"surah":53,"verses":[17]}],"verseLabel":"النجم: 17","question":"ما سرّ التعبير في قول ﴿الْبَصَرُ﴾، ولم يقل «القلب»؟","answer":"سبق نفي الكذب عن الفؤاد، ثم جاء نفي الزيغ عن البصر ليثبت استقامة المشاهدة نفسها. فالجمع بين سلامة الإدراك الباطن وثبات النظر يؤكد حقيقة الرؤية، ويظهر شدة ضبط النبي لنفسه في ذلك المشهد المهيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص200، تحت عنوان «نكتة إيثار ﴿البصر﴾»","url":""}]},{"id":"s53-18","number":18,"surah":53,"verses":[18],"references":[{"surah":53,"verses":[18]}],"verseLabel":"النجم: 18","question":"ما سرّ التعبير في قول ﴿مِنْ آيَاتِ رَبِّهِ الْكُبْرَى﴾، فاختار «ربه»؟","answer":"لفظ الربوبية أنسب بمعاني الرعاية والإحسان؛ فما رآه الرسول من الآيات إكرام وعناية من ربه. وإضافته إلى ضميره تخصه بهذا التشريف، وتثبت قلبه وتؤنسه في مواجهة التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص203، تحت عنوان «نكتة إيثار لفظ الربوبية مضافًا إلى الضمير»","url":""}]},{"id":"s53-19","number":19,"surah":53,"verses":[19,20],"references":[{"surah":53,"verses":[19,20]}],"verseLabel":"النجم: 19–20","question":"لماذا بدأ باللات ثم العزى ثم مناة؟","answer":"يذكر المبحث وجه ترتيبها بحسب المنزلة المزعومة، فيكون الترتيب حكاية لمراتبها عند عابديها ثم إبطالًا لها، ووجهًا آخر بحسب شهرة المواضع عند قريش وقربها منهم. ويعرض خلافًا في منزلة مناة، فلا يصح الجزم بأن الترتيب تاريخي أو أنه لا يحتمل إلا تعليلًا واحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص212، تحت عنوان «سر ترتيب الأصنام تقديمًا وتأخيرًا»","url":""}]},{"id":"s53-20","number":20,"surah":53,"verses":[22],"references":[{"surah":53,"verses":[22]}],"verseLabel":"النجم: 22","question":"لماذا اختيرت الكلمة النادرة ﴿ضِيزَى﴾ لوصف قسمتهم؟","answer":"﴿ضيزى﴾ تصف القسمة بالجور والنقص، وغرابة لفظها تلائم غرابة دعوى المشركين في جعل ما يكرهونه لأنفسهم لله. ويبرز المبحث مناسبة وقع الكلمة لمعناها المنكر، مع انسجامها مع فواصل السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص217، تحت عنوان «سر وصف ﴿قسمة﴾ بـ﴿ضيزى﴾»","url":""}]},{"id":"s53-21","number":21,"surah":53,"verses":[23],"references":[{"surah":53,"verses":[23]}],"verseLabel":"النجم: 23","question":"لماذا جُمع بين اتباع الظن واتباع هوى الأنفس؟","answer":"ليجمع فساد المعرفة وفساد الإرادة: ظن بلا برهان، وميل نفسي يحملهم على قبول ما يشتهون، مع أن الهدى قد جاءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص228–229، تحت عنوان «توجيه العطف بالواو»","url":""}]},{"id":"s53-22","number":22,"surah":53,"verses":[23],"references":[{"surah":53,"verses":[23]}],"verseLabel":"النجم: 23","question":"ما سرّ التعبير في قول ﴿وَلَقَدْ جَاءَهُمْ مِنْ رَبِّهِمُ الْهُدَى﴾، ولم يقل «أتاهم»؟","answer":"المجيء هنا أقوى في تصوير وصول الهدى وبلوغه إليهم، لا مجرد الإتيان من غير إبراز ذلك التحقق. وصيغة الماضي تثبت قيام الحجة فعلًا، فيشتد اللوم على اتباعهم الظن بعد أن وصلهم الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص231، تحت عنوان «سر إيثار فعل المجيء ماضيًا مجموعًا»","url":""}]},{"id":"s53-23","number":23,"surah":53,"verses":[25],"references":[{"surah":53,"verses":[25]}],"verseLabel":"النجم: 25","question":"ماذا يفيد تقديم ﴿لِلَّهِ﴾ في قوله ﴿فَلِلَّهِ الْآخِرَةُ وَالْأُولَى﴾؟","answer":"يفيد اختصاص ملك الدارين وتدبيرهما بالله، فيبطل اعتماد المشركين على الأماني والشفاعة المزعومة، ويبعث المهابة والتسليم لحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص237، تحت عنوان «سر تقديم الخبر (لله)»","url":""}]},{"id":"s53-24","number":24,"surah":53,"verses":[26],"references":[{"surah":53,"verses":[26]}],"verseLabel":"النجم: 26","question":"لماذا نُفي نفع الشفاعة في ﴿لَا تُغْنِي شَفَاعَتُهُمْ شَيْئًا﴾ بدل نفي وقوعها؟","answer":"لأن المقصود إبطال اعتمادهم على الشفاعة بغير إذن الله؛ فقد تقع شفاعة الملائكة بعد الإذن والرضا، لكنها لا تستقل بنفع أحد، فكيف بالأصنام؟","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص244، تحت عنوان «دلالة نفي الإغناء عن الشفاعة دون نفي الشفاعة ذاتها»","url":""}]},{"id":"s53-25","number":25,"surah":53,"verses":[28],"references":[{"surah":53,"verses":[28]}],"verseLabel":"النجم: 28","question":"ما الصورة في قوله ﴿ذَلِكَ مَبْلَغُهُمْ مِنَ الْعِلْمِ﴾؟","answer":"صوّر علمهم كمسير له نهاية وقفوا عندها، وهي ظاهر الدنيا؛ فلم يتجاوزوا هذا الحد إلى الهدى ومعرفة الآخرة، وفي الصورة تحقير لقصور همتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص268، تحت عنوان «بلاغة التعبير بالاستعارة في جملة: ﴿ذلك مبلغهم﴾»","url":""}]},{"id":"s53-26","number":26,"surah":53,"verses":[31],"references":[{"surah":53,"verses":[31]}],"verseLabel":"النجم: 31","question":"ما سرّ التعبير في قول ﴿لِيَجْزِيَ الَّذِينَ أَسَاءُوا بِمَا عَمِلُوا وَيَجْزِيَ الَّذِينَ أَحْسَنُوا بِالْحُسْنَى﴾؟","answer":"جزاء المسيئين مقيد بما عملوا، فيقرر العدل وأنهم لا يعاقبون بغير ذنبهم. أما المحسنون فجزاؤهم بالحسنى، وهو أحسن الثواب وزيادة الفضل، لا مجرد مقابلة العمل بمثله؛ فجمعت المقابلة عدل العقوبة وكرم المثوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص284، تحت عنوان «بلاغة التعبير بالمقابلة بين الجزاءين»","url":""}]},{"id":"s53-27","number":27,"surah":53,"verses":[32],"references":[{"surah":53,"verses":[32]}],"verseLabel":"النجم: 32","question":"لماذا استُثني ﴿اللَّمَمَ﴾ من كبائر الإثم والفواحش؟","answer":"لأن اللمم دون الكبائر: ما يلم به الإنسان من صغيرة أو ذنب لا يصر عليه ثم يتوب. فالاستثناء يفتح باب الرجاء لمن اجتنب الكبائر، ولا يبيح المعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص287–288، تحت عنوان «دلالة الاستثناء بـ﴿إلا﴾»","url":""}]},{"id":"s53-47","number":47,"surah":53,"verses":[32],"references":[{"surah":53,"verses":[32]}],"verseLabel":"النجم: 32","question":"ماذا يفيد تعريف ﴿اللَّمَمَ﴾؟","answer":"يشير إلى النوع المعروف شرعًا مما دون الكبائر والفواحش، ويقابل بين المحرمات المشددة وما يعرض للمؤمن ثم يقلع عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص288–289، تحت عنوان «الغرض من تعريف: ﴿اللمم﴾»","url":""}]},{"id":"s53-28","number":28,"surah":53,"verses":[32],"references":[{"surah":53,"verses":[32]}],"verseLabel":"النجم: 32","question":"ما سرّ التعبير في قول ﴿إِنَّ رَبَّكَ وَاسِعُ الْمَغْفِرَةِ﴾ باسم الرب؟","answer":"اسم الرب يشير إلى الرعاية والإحسان؛ فمن رحمته بعباده سعة مغفرته لهم. وإضافته إلى ضمير النبي تزيده تشريفًا وتبشره بعناية ربه بالمحسنين من أمته، فيناسب مقام الوعد بالمغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص289، تحت عنوان «سر التعبير بلفظ الربوبية مضافًا إلى ضمير النبي ﷺ»","url":""}]},{"id":"s53-29","number":29,"surah":53,"verses":[32],"references":[{"surah":53,"verses":[32]}],"verseLabel":"النجم: 32","question":"لماذا نهى الله عن تزكية النفس في قوله ﴿فَلَا تُزَكُّوا أَنْفُسَكُمْ﴾؟","answer":"لأنها مدح للنفس وادعاء للطهارة والفضل، وقد يداخلها العجب والرياء؛ والله أعلم بحقيقة التقوى، فالمطلوب العمل الصالح لا شهادة المرء لنفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص296، تحت عنوان «غرض التعبير بالنهي في قوله تعالى: ﴿فلا تزكوا﴾»","url":""}]},{"id":"s53-30","number":30,"surah":53,"verses":[32],"references":[{"surah":53,"verses":[32]}],"verseLabel":"النجم: 32","question":"ما سرّ التعبير في قول ﴿هُوَ أَعْلَمُ بِكُمْ إِذْ أَنْشَأَكُمْ مِنَ الْأَرْضِ﴾، ولم يقل «خلقكم»؟","answer":"الإنشاء يلحظ الإيجاد مع الرعاية والنمو والتدرج إلى الكمال، فهو أوسع في تصوير أطوار الإنسان من مجرد ذكر أصل خلقه. وذكر علم الله بهم في هذه الأطوار يبين إحاطته بحقيقتهم، فلا تخفى عليه دعوى من يزكي نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص291–292، تحت عنوان «دلالة التعبير بالماضي ﴿أنشأكم﴾ مادة وصيغة»","url":""}]},{"id":"s53-31","number":31,"surah":53,"verses":[39],"references":[{"surah":53,"verses":[39]}],"verseLabel":"النجم: 39","question":"ما سرّ التعبير في قول ﴿وَأَنْ لَيْسَ لِلْإِنْسَانِ إِلَّا مَا سَعَى﴾، ولم يقل «إلا ما عمل»؟","answer":"أصل السعي السير والعمل المقصود، واستعمل هنا في مطلق العمل على وجه المجاز، مع الإشعار بالجد والجهد الذي يباشره صاحبه. فالتعبير يربط الإنسان بما قدمه بنفسه، ويحض على العمل الصالح بدل الاتكال على مجرد الأماني.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص326، تحت عنوان «بلاغة التعبير بالمجاز المرسل، والكناية»","url":""}]},{"id":"s53-32","number":32,"surah":53,"verses":[40],"references":[{"surah":53,"verses":[40]}],"verseLabel":"النجم: 40","question":"ما سرّ التعبير في قول ﴿وَأَنَّ سَعْيَهُ سَوْفَ يُرَى﴾، ولم يقل «سوف يُعلم»؟","answer":"الرؤية تصور السعي ظاهرًا مشهودًا يوم الجزاء، فتزيد المعنى وضوحًا على مجرد العلم به. ويعرض المبحث إمكان رؤية الأعمال أو آثارها، وإمكان حمل الرؤية على العلم المحقق والإشهاد؛ فالمقصود ألا يضيع عمل الإنسان وأن يظهر جزاؤه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص328–329، تحت عنوان «بلاغة التعبير بـ﴿يرى﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s53-33","number":33,"surah":53,"verses":[43,44],"references":[{"surah":53,"verses":[43,44]}],"verseLabel":"النجم: 43–44","question":"ما دلالة الجمع بين ﴿أَضْحَكَ وَأَبْكَى﴾؟","answer":"يجمع حالين متقابلين يختبرهما الإنسان في نفسه، فيدل على إحاطة قدرة الله بمشاعره المتعاقبة وانفراده بالتصرف فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص337، تحت عنوان «بلاغة التعبير بالطباق بين ﴿أضحك وأبكى﴾»","url":""}]},{"id":"s53-48","number":48,"surah":53,"verses":[43,44],"references":[{"surah":53,"verses":[43,44]}],"verseLabel":"النجم: 43–44","question":"لماذا أعقب الضحك والبكاء بقوله ﴿أَمَاتَ وَأَحْيَا﴾؟","answer":"للانتقال من التصرف في المشاعر إلى القدرة على أصل الوجود، وهو أعظم أثرًا؛ فتتدرج الدلائل من حال النفس إلى الموت والحياة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص337–338، تحت عنوان «بلاغة العطف بالواو في ﴿أمات وأحيا﴾»","url":""}]},{"id":"s53-49","number":49,"surah":53,"verses":[43,44],"references":[{"surah":53,"verses":[43,44]}],"verseLabel":"النجم: 43–44","question":"ما دلالة الجمع بين ﴿أَمَاتَ وَأَحْيَا﴾؟","answer":"يجمع طرفي الوجود لإثبات أن الله وحده يملك الإماتة والإحياء، ردًا على من نسب شيئًا من ذلك إلى غيره، ودليلًا على إمكان البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص339، تحت عنوان «بلاغة التعبير بالطباق بين ﴿أمات وأحيا﴾»","url":""}]},{"id":"s53-34","number":34,"surah":53,"verses":[45],"references":[{"surah":53,"verses":[45]}],"verseLabel":"النجم: 45","question":"ماذا يفيد التعبير بـ﴿الزَّوْجَيْنِ﴾ في خلق الإنسان؟","answer":"يفيد أن الذكر والأنثى صنفان متقابلان يقوم بهما النسل، ويقرب حجة القدرة إلى كل إنسان من أصل خلقه الذي يعرفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص344، تحت عنوان «دلالة التعبير بلفظ ﴿الزوجين﴾ معرفًا»","url":""}]},{"id":"s53-50","number":50,"surah":53,"verses":[45],"references":[{"surah":53,"verses":[45]}],"verseLabel":"النجم: 45","question":"لماذا صُرح بـ﴿الذَّكَرَ وَالْأُنْثَى﴾ بعد ذكر الزوجين؟","answer":"لبيان المقصود بالزوجين واستغراق الجنسين جميعًا، والتأكيد أن اختلافهما وتكاملهما من خلق الله وتقديره لا من المصادفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص344، تحت عنوان «دلالة التعبير بلفظي ﴿الذكر والأنثى﴾ معرفين والجمع بينهما»","url":""}]},{"id":"s53-35","number":35,"surah":53,"verses":[46],"references":[{"surah":53,"verses":[46]}],"verseLabel":"النجم: 46","question":"ما سرّ التعبير في قول ﴿مِنْ نُطْفَةٍ إِذَا تُمْنَى﴾ بالمضارع؟","answer":"المضارع يستحضر فعل الإمناء المتكرر عبر الأزمان، فيجعل هذا الدليل على الخلق حاضرًا مشاهدًا. وبناء الفعل للمفعول يصرف النظر إلى النطفة وما يقع بها من بدء التكوين، وهو موضع الاستدلال على القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص346، تحت عنوان «دلالة التعبير بالمضارع ﴿تمنى﴾ مبنيًا للمفعول»","url":""}]},{"id":"s53-36","number":36,"surah":53,"verses":[49],"references":[{"surah":53,"verses":[49]}],"verseLabel":"النجم: 49","question":"ماذا تفيد إضافة ﴿رَبُّ﴾ إلى ﴿الشِّعْرَى﴾؟","answer":"تفيد أن الشعرى مخلوقة مربوبة خاضعة لله، لا تملك لنفسها نفعًا ولا ضرًا؛ فتسقط دعوى ألوهيتها واستحقاقها للعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص355، تحت عنوان «الغرض من الإضافة في ﴿رب الشعرى﴾»","url":""}]},{"id":"s53-51","number":51,"surah":53,"verses":[49],"references":[{"surah":53,"verses":[49]}],"verseLabel":"النجم: 49","question":"لماذا خُص نجم الشعرى بالذكر دون سائر النجوم؟","answer":"لأن بعض العرب عبدوه وعظموه، فخُص بالذكر لإبطال تلك العبادة من أصلها: ما يعبدونه ليس إلهًا بل مخلوق لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص356، تحت عنوان «فن التنكيت في تخصيص ﴿الشعرى﴾ بالذكر دون غيرها»","url":""}]},{"id":"s53-37","number":37,"surah":53,"verses":[50],"references":[{"surah":53,"verses":[50]}],"verseLabel":"النجم: 50","question":"ما سرّ وصف عادًا بـ﴿عَادًا الْأُولَى﴾؟","answer":"يعرض المبحث وجهين: أن ﴿الأولى﴾ وصف يكشف قدم عاد وسبقها، أو أنه يميز عادًا الأولى من عاد أخرى. وفي كلا الوجهين تذكير بقوم عظم شأنهم في الزمن الأول ثم لم تمنعهم قوتهم من الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص360–361، تحت عنوان «سر وصف عاد بالأولى»","url":""}]},{"id":"s53-38","number":38,"surah":53,"verses":[57,58],"references":[{"surah":53,"verses":[57,58]}],"verseLabel":"النجم: 57–58","question":"لماذا قيل ﴿أَزِفَتِ﴾ بالماضي مع أن القيامة لم تقع بعد؟","answer":"لأن الماضي ينزّل مجيء القيامة منزلة الأمر المتحقق الذي وقع وانقضى؛ فهي مؤكدة الوقوع وقريبة حتى كأنها حاضرة، وفي ذلك إيقاظ من يغفل عنها أو يستبعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص385، تحت عنوان «الغرض من العدول عن المضارع إلى الماضي ﴿أزفت﴾»","url":""}]},{"id":"s53-52","number":52,"surah":53,"verses":[57,58],"references":[{"surah":53,"verses":[57,58]}],"verseLabel":"النجم: 57–58","question":"ماذا يضيف اشتقاق ﴿الْآزِفَةُ﴾ من مادة الفعل ﴿أَزِفَتْ﴾؟","answer":"يكرر معنى القرب في الفعل والفاعل معًا، ويصنع تجانسًا صوتيًا يلفت السمع ويثبت الإنذار في النفس؛ فكأن قرب الساعة صار صفتها الملازمة وحقيقتها البارزة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص386، تحت عنوان «دلالة مجيء الفاعل ﴿الآزفة﴾ من مادة الفعل»","url":""}]},{"id":"s53-53","number":53,"surah":53,"verses":[57,58],"references":[{"surah":53,"verses":[57,58]}],"verseLabel":"النجم: 57–58","question":"ماذا توحي الكناية ﴿لَيْسَ لَهَا مِنْ دُونِ اللَّهِ كَاشِفَةٌ﴾؟","answer":"توحي بأن أحدًا سوى الله لا يملك دفع القيامة ولا إزالة شدتها، ولا يستقل بكشف وقتها وحقيقتها؛ فالحصر يقرر عجز الخلق جميعًا وانفراد الله بالعلم والقدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص390، تحت عنوان «بلاغة التعبير بالكناية في: ﴿ليس لها من دون الله كاشفة﴾»","url":""}]},{"id":"s53-39","number":39,"surah":53,"verses":[59,60,61,62],"references":[{"surah":53,"verses":[59,60,61,62]}],"verseLabel":"النجم: 59–62","question":"لماذا استُنكر تعجب المشركين من القرآن؟","answer":"لأن تعجبهم لم يكن طلبًا للفهم، بل إنكارًا واستهزاءً بوحي جدير بالتصديق والخضوع. فجاء الاستفهام يوبخهم ويجهل موقفهم ويعجب السامع من انقلابهم عن الحجة إلى السخرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص394، تحت عنوان «بلاغة التعبير بالاستفهام في قوله: ﴿أفمن هذا الحديث﴾»","url":""}]},{"id":"s53-54","number":54,"surah":53,"verses":[59,60,61,62],"references":[{"surah":53,"verses":[59,60,61,62]}],"verseLabel":"النجم: 59–62","question":"لماذا انتهى توبيخهم إلى الأمر ﴿فَاسْجُدُوا لِلَّهِ﴾؟","answer":"لأن الفاء تجعل السجود النتيجة التي تقتضيها آيات الوحي والإنذار: فبدل الضحك والغفلة ينبغي أن يقابلوا الحق بالخضوع لله. وهكذا ينتقل السياق من كشف الموقف الفاسد إلى العلاج العملي المقابل له.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص399، تحت عنوان «معنى الفاء ودلالتها في: ﴿فاسجدوا لله﴾»","url":""}]},{"id":"s53-55","number":55,"surah":53,"verses":[59,60,61,62],"references":[{"surah":53,"verses":[59,60,61,62]}],"verseLabel":"النجم: 59–62","question":"لماذا أُضيف ﴿وَاعْبُدُوا﴾ بعد الأمر بالسجود؟","answer":"لأن السجود أظهر صور الخضوع، لكنه لا يستوعب الدين كله؛ فأُتبع بالأمر العام ليشمل سائر أعمال العبادة الظاهرة والباطنة، وليدل على إخلاصها لله وترك ما يعبد المشركون.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص400–401، تحت عنوان «دلالة العطف بالواو في ﴿واعبدوا﴾»","url":""}]},{"id":"s54-1","number":1,"surah":54,"verses":[1],"references":[{"surah":54,"verses":[1]}],"verseLabel":"القمر: 1","question":"كيف يواصل مطلع سورة القمر إنذار ختام سورة النجم؟","answer":"خُتمت النجم بقوله ﴿أَزِفَتِ الْآزِفَةُ﴾، ثم افتتحت القمر بقوله ﴿اقْتَرَبَتِ السَّاعَةُ﴾؛ فانتقل الإنذار من الإخبار بقرب القيامة إلى مشهد اقترابها، وكأن السورتين حلقة واحدة توقظ الغافل من دنو الموعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص411، تحت عنوان «مناسبة السورة لما قبلها»","url":""}]},{"id":"s54-23","number":23,"surah":54,"verses":[1],"references":[{"surah":54,"verses":[1]}],"verseLabel":"القمر: 1","question":"لماذا عُطف انشقاق القمر على اقتراب الساعة؟","answer":"لأن انشقاق القمر آية محسوسة تدل على قدرة الله على قلب نظام الكون عند قيام الساعة؛ فجمع العطف بين الخبر عن الموعد ودليله المشاهد، وزاد الإنذار قوة وقربًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص418–419، تحت عنوان «بلاغة عطف الانشقاق على اقتراب الساعة»","url":""}]},{"id":"s54-2","number":2,"surah":54,"verses":[6],"references":[{"surah":54,"verses":[6]}],"verseLabel":"القمر: 6","question":"لماذا قيل ﴿يَوْمَ يَدْعُ الدَّاعِ﴾ بالمضارع؟","answer":"لاستحضار النداء كأنه يقع أمام السامع الآن، ولتصوير تتابع الدعاء يوم القيامة حتى ينهض الخلق جميعًا للحشر؛ فيتحول الخبر البعيد إلى مشهد حي.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص447، تحت عنوان «دلالة التعبير بالفعل المضارع»","url":""}]},{"id":"s54-24","number":24,"surah":54,"verses":[6],"references":[{"surah":54,"verses":[6]}],"verseLabel":"القمر: 6","question":"لماذا أبهمت الآية ما يُدعى إليه الناس بقولها ﴿إِلَى شَيْءٍ نُكُرٍ﴾؟","answer":"لتهويل ذلك الأمر قبل تفصيله؛ فلفظ ﴿شيء﴾ يترك النفس تتوقع ما يفزعها، ثم يكشف وصفه بالنُّكر أنه أمر عظيم تنكره النفوس من شدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص448، تحت عنوان «بلاغة استعمال لفظ ﴿شيء﴾»","url":""}]},{"id":"s54-3","number":3,"surah":54,"verses":[8],"references":[{"surah":54,"verses":[8]}],"verseLabel":"القمر: 8","question":"لماذا أظهر الكافرون لفظ ﴿يَوْمٌ﴾ في قولهم ﴿هَذَا يَوْمٌ عَسِرٌ﴾ بدل الاكتفاء بضمير؟","answer":"لأن إظهار اليوم بالاسم يرسخ هوله في نفوسهم ويجدد استحضاره، فيواجههم بالموعد الذي كانوا ينكرونه حاضرًا لا مهرب منه، بدل أن يمر ذكره في ضمير خافت.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص455، تحت عنوان «بلاغة إظهار الفاعل دون إضماره»","url":""}]},{"id":"s54-25","number":25,"surah":54,"verses":[8],"references":[{"surah":54,"verses":[8]}],"verseLabel":"القمر: 8","question":"ماذا يصور وصف يوم القيامة بأنه ﴿عَسِرٌ﴾؟","answer":"يصور يومًا بالغ الشدة لا يقدر الكافرون على دفع أهواله، وجاء اللفظ موجزًا قوي الجرس ليلائم ثقل الموقف وعسر النجاة منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص456، تحت عنوان «بلاغة استعمال مفردة ﴿عسر﴾ مادة وصيغة»","url":""}]},{"id":"s54-4","number":4,"surah":54,"verses":[16,18,21,30],"references":[{"surah":54,"verses":[16,18,21,30]}],"verseLabel":"القمر: 16، 18، 21، 30","question":"ما الذي يحققه الاستفهام في ﴿فَكَيْفَ كَانَ عَذَابِي وَنُذُرِ﴾؟","answer":"ليس سؤالًا ينتظر جوابًا، بل تهويل وتعجيب من شدة العذاب الذي نزل بالمكذبين؛ فهو يدعو السامع إلى أن يتصور المصير ويعتبر به قبل أن يلقاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص490، تحت عنوان «غرض الاستفهام بكيف»","url":""}]},{"id":"s54-26","number":26,"surah":54,"verses":[16,18,21,30],"references":[{"surah":54,"verses":[16,18,21,30]}],"verseLabel":"القمر: 16، 18، 21، 30","question":"لماذا تكررت لازمة ﴿فَكَيْفَ كَانَ عَذَابِي وَنُذُرِ﴾ في قصص السورة؟","answer":"لتجعل كل قصة شاهدًا مستقلًا على صدق الإنذار، وتقطع الانتقال بين الأمم بوقفة توقظ السامع: لقد تنوع المكذبون، لكن عاقبة التكذيب واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص509–510، تحت عنوان «نكتة تكرار قوله: ﴿فكيف كان عذابي ونذر﴾»","url":""}]},{"id":"s54-5","number":5,"surah":54,"verses":[24],"references":[{"surah":54,"verses":[24]}],"verseLabel":"القمر: 24","question":"لماذا قدّم قوم ثمود قولهم ﴿بَشَرًا مِنَّا وَاحِدًا﴾ على ﴿نَتَّبِعُهُ﴾؟","answer":"ليجعلوا موضع سخريتهم واعتراضهم في صدر الكلام: كيف نتبع فردًا من جنسنا؟ فالتقديم يكشف أن استكبارهم على شخص الرسول سبق نظرهم في صدق رسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص517–518، تحت عنوان «نكتة تقديم المفعول في قوله: ﴿بشرًا منا واحدًا نتبعه﴾»","url":""}]},{"id":"s54-6","number":6,"surah":54,"verses":[1],"references":[{"surah":54,"verses":[1]}],"verseLabel":"القمر: 1","question":"لماذا قيل ﴿وَانْشَقَّ الْقَمَرُ﴾ بصيغة الماضي؟","answer":"للدلالة على أن الانشقاق وقع وتحقق، لا أنه مجرد وعد مؤجل؛ وصيغة الماضي تمنح الخبر ثبات الأمر المشاهد، فتجعله شاهدًا على صدق الرسول وقدرة الله على أشراط الساعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص419–420، تحت عنوان «دلالة التعبير بفعل الانشقاق مادة وصيغة»","url":""}]},{"id":"s54-7","number":7,"surah":54,"verses":[2],"references":[{"surah":54,"verses":[2]}],"verseLabel":"القمر: 2","question":"لماذا صيغت رؤية الكافرين للآيات بالمضارع في ﴿وَإِنْ يَرَوْا آيَةً﴾؟","answer":"للدلالة على أن موقفهم لا يتعلق بآية واحدة مضت، بل يتجدد كلما رأوا دليلًا؛ فالمضارع يكشف عنادًا مستمرًا لا نقصًا في البراهين.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص423، تحت عنوان «دلالة الفعل المضارع في قوله: ﴿وإن يروا آية﴾»","url":""}]},{"id":"s54-27","number":27,"surah":54,"verses":[2],"references":[{"surah":54,"verses":[2]}],"verseLabel":"القمر: 2","question":"ماذا تكشف الجملة الشرطية ﴿وَإِنْ يَرَوْا آيَةً يُعْرِضُوا﴾؟","answer":"تكشف رابطة ثابتة في سلوكهم: كلما ظهرت لهم آية قابلوها بالإعراض؛ وبذلك يصور الشرط الإعراض عادة متكررة، لا رد فعل عابرًا على دليل واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص425، تحت عنوان «بلاغة التعبير بالجملة الشرطية»","url":""}]},{"id":"s54-8","number":8,"surah":54,"verses":[2],"references":[{"surah":54,"verses":[2]}],"verseLabel":"القمر: 2","question":"ما معنى قولهم ﴿سِحْرٌ مُسْتَمِرٌّ﴾، ولماذا اختير «مستمر»؟","answer":"يذكر المبحث للمستمر أوجهًا منها الدائم المتتابع، والشديد المحكم، والعابر الذي يزول. وهذه أوصاف متباينة لدعواهم الباطلة، يكشف كل وجه منها طريقة في رد الآية: إلحاقها بسحر سابق، أو تهويله، أو التهوين منه بزعم زواله؛ فلا يحصر اللفظ في تفسير واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص427، تحت عنوان «تنوع المعاني لمفردة ﴿مستمر﴾»","url":""}]},{"id":"s54-9","number":9,"surah":54,"verses":[5],"references":[{"surah":54,"verses":[5]}],"verseLabel":"القمر: 5","question":"لماذا وُصفت الأنباء التي جاءت المكذبين بأنها ﴿حِكْمَةٌ بَالِغَةٌ﴾؟","answer":"لأنها بلغت الغاية في إحكام الحجة والوصول إلى موضع العبرة؛ فلا خلل في الإنذار، وإنما الخلل في قوم أعرضوا بعد أن بلغهم من الأخبار ما يزجرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص439–440، تحت عنوان «بلاغة استعمال ﴿بالغة﴾ مادة وصيغة»","url":""}]},{"id":"s54-28","number":28,"surah":54,"verses":[5],"references":[{"surah":54,"verses":[5]}],"verseLabel":"القمر: 5","question":"ما الذي يقرره قوله ﴿فَمَا تُغْنِ النُّذُرُ﴾ بعد ﴿حِكْمَةٌ بَالِغَةٌ﴾؟","answer":"يقرر أن الإنذارات، مع بلوغها وكمال حجتها، لا تنفع من عقد قلبه على الإعراض؛ فالنفي لا يذم النذر، بل يفضح استعداد المكذب الذي أبطل أثرها في نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص440–441، تحت عنوان «نوع ﴿ما﴾ ودلالتها»","url":""}]},{"id":"s54-10","number":10,"surah":54,"verses":[7],"references":[{"surah":54,"verses":[7]}],"verseLabel":"القمر: 7","question":"لماذا شُبّه الخارجون من القبور بالجراد المنتشر؟","answer":"لأن الجراد إذا انتشر ملأ الفضاء بكثرته واضطراب حركته وتدافعه؛ فالتشبيه يجعل الحشر مشهدًا منظورًا لجماهير لا تحصى تخرج مسرعة في كل اتجاه ثم تنقاد إلى الداعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص453–454، تحت عنوان «علة التشبيه بالجراد المنتشر»","url":""}]},{"id":"s54-11","number":11,"surah":54,"verses":[7,8],"references":[{"surah":54,"verses":[7,8]}],"verseLabel":"القمر: 7–8","question":"لماذا وصف الخارجين من القبور بأنهم ﴿خُشَّعًا أَبْصَارُهُمْ﴾؟","answer":"لأن الذل والفزع يظهران أول ما يظهران في العين؛ فخفض الأبصار يرسم انكسار المكذبين الذين كانوا يستكبرون عن الإنذار، وقد صاروا لا يملكون رفع نظرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص449–450، تحت عنوان «بلاغة استعمال ﴿خشعًا﴾»","url":""}]},{"id":"s54-29","number":29,"surah":54,"verses":[7,8],"references":[{"surah":54,"verses":[7,8]}],"verseLabel":"القمر: 7–8","question":"ماذا تضيف كلمة ﴿مُهْطِعِينَ﴾ إلى مشهد الحشر؟","answer":"تصورهم مسرعين مادّي أعناقهم نحو الداعي، لا يتخلف منهم أحد؛ فتجمع الصورة بين ذلة الأبصار واضطرار الأجساد إلى الحركة السريعة صوب المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص454، تحت عنوان «بلاغة استعمال ﴿مهطعين﴾»","url":""}]},{"id":"s54-12","number":12,"surah":54,"verses":[9],"references":[{"surah":54,"verses":[9]}],"verseLabel":"القمر: 9","question":"لماذا قال الله عن نوح ﴿عَبْدَنَا﴾ ولم يقل «رسولنا»؟","answer":"لأن العبودية الخالصة أشرف أوصاف الإنسان وأصل مقام الرسالة، فإيثارها يشرف نوحًا ويظهر تمام انقياده لله، كما يزيد تكذيب قومه قبحًا إذ كذبوا عبدًا مصطفى قائمًا بحق ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص467، تحت عنوان «دلالة إيثار لفظ العبودية على الرسالة»","url":""}]},{"id":"s54-32","number":32,"surah":54,"verses":[9],"references":[{"surah":54,"verses":[9]}],"verseLabel":"القمر: 9","question":"ماذا تضيف نسبة نوح إلى الله في قوله ﴿عَبْدَنَا﴾؟","answer":"هي إضافة تشريف واختصاص، تقرر قربه من عناية الله ونصره، وتوحي بأن من كذبه عادَى عبدًا تولاه الله؛ فتهيئ النفس لما أعقب ذلك من إنجائه وعقوبة المكذبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص468، تحت عنوان «نوع الإضافة ودلالتها»","url":""}]},{"id":"s54-13","number":13,"surah":54,"verses":[13],"references":[{"surah":54,"verses":[13]}],"verseLabel":"القمر: 13","question":"لماذا وصف القرآن سفينة نوح بأنها ﴿ذَاتِ أَلْوَاحٍ وَدُسُرٍ﴾؟","answer":"ذكر أجزاءها الظاهرة من ألواح ومسامير وأراد السفينة كلها؛ فالكناية تستحضر بناءها المادي البسيط، وتبرز أن النجاة تمت بوسيلة صنعها البشر ولكنها جرت بحفظ الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص482–483، تحت عنوان «بلاغة الكناية بحذف الموصوف»","url":""}]},{"id":"s54-30","number":30,"surah":54,"verses":[13],"references":[{"surah":54,"verses":[13]}],"verseLabel":"القمر: 13","question":"لماذا جُمعت ﴿الدُّسُر﴾ مع ﴿الأَلْوَاح﴾ في وصف سفينة نوح؟","answer":"لأن الألواح مادة السفينة، والدسر ما يشد بعضها إلى بعض؛ فالعطف يجمع عناصر البناء والتماسك، ويصور السفينة محكمة الأجزاء لا ألواحًا متفرقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص483، تحت عنوان «نكتة عطف الدسر على الألواح»","url":""}]},{"id":"s54-14","number":14,"surah":54,"verses":[14],"references":[{"surah":54,"verses":[14]}],"verseLabel":"القمر: 14","question":"ما سرّ التعبير في قول ﴿جَزَاءً لِمَنْ كَانَ كُفِرَ﴾ بالبناء للمجهول؟","answer":"البناء للمفعول يبرز نوحًا الذي وقع عليه التكذيب والجحود، ويصرف الاهتمام عن تعيين الكافرين إلى إكرام من كفروا به. وفي إبهام اسمه تشريف، وتعميم للعبرة بأن الله ينصر عبده الذي جحده قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص486–487، تحت عنوان «نكتة بناء فعل ﴿كفر﴾ للمفعول»","url":""}]},{"id":"s54-15","number":15,"surah":54,"verses":[19],"references":[{"surah":54,"verses":[19]}],"verseLabel":"القمر: 19","question":"هل وصف يوم عذاب عاد بأنه ﴿يَوْمِ نَحْسٍ﴾ يعني أن اليوم مشؤوم بذاته؟","answer":"لا؛ أضيف اليوم إلى النحس لأن العذاب والشؤم وقعا فيه على قوم عاد، لا لأن الزمن يحمل شرًا ذاتيًا لكل أحد. فالأيام ظروف لما يقدره الله، وإنما يكون السعد أو النحس بحسب ما يقع فيها للناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص503–504، تحت عنوان «دلالة إضافة اليوم إلى الصفة»","url":""}]},{"id":"s54-16","number":16,"surah":54,"verses":[20],"references":[{"surah":54,"verses":[20]}],"verseLabel":"القمر: 20","question":"لماذا ذُكرت ﴿أَعْجَازُ النَّخْلِ﴾ دون رؤوسه في تصوير هلاك عاد؟","answer":"لأن الأعجاز هي الجذوع والأصول الباقية بعد ذهاب الفروع، وهي أنسب بصورة أجساد مطروحة بلا حراك؛ وفيها إيحاء بأن قوتهم قُلعت من أصلها ولم يبق منها إلا جثث خاوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص508، تحت عنوان «علة ذكر الأعجاز دون الرؤوس»","url":""}]},{"id":"s54-17","number":17,"surah":54,"verses":[24],"references":[{"surah":54,"verses":[24]}],"verseLabel":"القمر: 24","question":"ماذا يكشف قول ثمود ﴿مِنَّا وَاحِدًا﴾ عن سبب رفضهم لرسولهم؟","answer":"يكشف حسدهم واستكبارهم: استبعدوا أن يُختار فرد واحد من جماعتهم بالوحي، كأن الحق يوزن بكثرة الأتباع أو بالمكانة الاجتماعية لا ببرهانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص519، تحت عنوان «نكتة تقديم القيد على النعت في قوله: ﴿منا واحدًا﴾»","url":""}]},{"id":"s54-18","number":18,"surah":54,"verses":[25],"references":[{"surah":54,"verses":[25]}],"verseLabel":"القمر: 25","question":"لماذا جمعوا بين ﴿كَذَّابٌ أَشِرٌ﴾؟","answer":"الكذاب اتهام له باختلاق الوحي، والأشر اتهام بدافع ذلك الاختلاق في زعمهم، وهو البطر وطلب التعاظم. فقدموا أصل التهمة ثم أضافوا باعثًا مذمومًا لها، ليشتد تنفير قومهم من دعوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص528، تحت عنوان «دلالة تقديم ﴿كذاب﴾ على ﴿أشر﴾»","url":""}]},{"id":"s54-19","number":19,"surah":54,"verses":[28],"references":[{"surah":54,"verses":[28]}],"verseLabel":"القمر: 28","question":"ما سرّ التعبير في قول ﴿وَنَبِّئْهُمْ أَنَّ الْمَاءَ قِسْمَةٌ بَيْنَهُمْ﴾، ولم يقل «مقسوم»؟","answer":"الإخبار بالمصدر بدل اسم المفعول يبالغ في ثبوت القسمة ووضوحها، فكأن الماء نفس القسمة المحددة. فيؤكد أن لكل طرف نصيبه المعلوم، وأن هذا التقسيم مستقر لا مجال للنزاع فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص535، تحت عنوان «نكتة الإخبار بالمصدر في ﴿قسمة﴾»","url":""}]},{"id":"s54-20","number":20,"surah":54,"verses":[31],"references":[{"surah":54,"verses":[31]}],"verseLabel":"القمر: 31","question":"لماذا شُبّه أصحاب القرية بعد الصيحة بـ﴿هَشِيمِ الْمُحْتَظِرِ﴾؟","answer":"لأن الهشيم عيدان يابسة مكسرة يجمعها صاحب الحظيرة، فصورت العبارة القوم بعد الصيحة أجسادًا محطمة متراكمة لا قوة فيها؛ وفي التشبيه صورة مألوفة للعرب تجعل فجاءة الهلاك وتمامه محسوسين.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص544–545، تحت عنوان «بلاغة التشبيه ومناسبته التاريخية»","url":""}]},{"id":"s54-21","number":21,"surah":54,"verses":[45],"references":[{"surah":54,"verses":[45]}],"verseLabel":"القمر: 45","question":"ما سرّ التعبير في قول ﴿سَيُهْزَمُ الْجَمْعُ وَيُوَلُّونَ الدُّبُرَ﴾ بالإفراد؟","answer":"الدبر مفرد يراد به الجنس، فيصدق على أدبار أفراد الجمع. وفي إفراده تصوير لوحدة فرارهم بعد وحدة اجتماعهم على الباطل؛ كأنهم يدبرون إدبارًا واحدًا، فلا يحميهم ما تفاخروا به من كثرة وتناصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص599، تحت عنوان «دلالة إفراد لفظ ﴿الدبر﴾»","url":""}]},{"id":"s54-22","number":22,"surah":54,"verses":[54,55],"references":[{"surah":54,"verses":[54,55]}],"verseLabel":"القمر: 54–55","question":"ماذا يوحي وصف مقام المتقين بأنه ﴿مَقْعَدِ صِدْقٍ﴾؟","answer":"يوحي بمقام حق ثابت لا كدر فيه ولا زوال، يطابق ما وعد الله به عباده؛ فأضيف المقعد إلى الصدق لتجتمع طمأنينة المكان وكرامة المنزلة ووفاء الوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص632، تحت عنوان «دلالة الإضافة في قوله: ﴿مقعد صدق﴾»","url":""}]},{"id":"s54-31","number":31,"surah":54,"verses":[54,55],"references":[{"surah":54,"verses":[54,55]}],"verseLabel":"القمر: 54–55","question":"لماذا خُتمت السورة بوصفي ﴿مَلِيكٍ مُقْتَدِرٍ﴾؟","answer":"لأن تمام النعيم يحتاج ملكًا يهب بلا نفاد وقدرة لا يعجزها إنجاز الوعد؛ فاجتمع كمال السلطان وكمال القدرة، ليدل الختام على دوام الجزاء وأمن أهله من زواله.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص633–634، تحت عنوان «دلالة تخصيص صفتي ﴿مليك مقتدر﴾ بالذكر»","url":""}]},{"id":"s55-1","number":1,"surah":55,"verses":[1,2,3],"references":[{"surah":55,"verses":[1,2,3]}],"verseLabel":"الرحمن: 1–3","question":"ما سرّ تقديم ﴿عَلَّمَ الْقُرْآنَ﴾ على ﴿خَلَقَ الْإِنْسَانَ﴾ مع أن الإنسان خُلق قبل أن يتعلم؟","answer":"التقديم بحسب شرف النعمة وأهميتها، لا بحسب ترتيب حصولها؛ فتعليم القرآن أصل الهداية وأعظم ما يكرم به الإنسان، ومن أجله يعرف غاية خلقه وطريق عبادة ربه. لذلك قدم على ذكر خلق الإنسان، تنبيهًا إلى أن نعمة الهداية هي المقصودة في هذا المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص667، تحت عنوان «سر ترتيب الأخبار الثلاثة»","url":""}]},{"id":"s55-2","number":2,"surah":55,"verses":[5],"references":[{"surah":55,"verses":[5]}],"verseLabel":"الرحمن: 5","question":"لماذا قيل عن الشمس والقمر: ﴿بِحُسْبَانٍ﴾؟","answer":"لأن حركتهما تجري بحساب دقيق مقدر لا يختل، ومن هذا الانتظام يعرف الناس الأزمنة والمواقيت؛ فالباء تصور ملازمتهما لهذا النظام المحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص684–685، تحت عنوان «سر إيثار مفردة ﴿بحسبان﴾، ومعنى الباء ودلالتها»","url":""}]},{"id":"s55-3","number":3,"surah":55,"verses":[7,8,9],"references":[{"surah":55,"verses":[7,8,9]}],"verseLabel":"الرحمن: 7–9","question":"لماذا تكرر لفظ ﴿الْمِيزَانَ﴾ ثلاث مرات؟","answer":"لأن كل ذكر يؤدي معنى متدرجًا: أصل العدل الذي وضعه الله، والنهي عن الطغيان فيه، والأمر بإقامة الوزن؛ فالتكرار يثبت المحور ويميز مراتبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص701، تحت عنوان «دلالة تكرار لفظة (الميزان) ثلاث مرات»","url":""}]},{"id":"s55-25","number":25,"surah":55,"verses":[7,8,9],"references":[{"surah":55,"verses":[7,8,9]}],"verseLabel":"الرحمن: 7–9","question":"لماذا أُعيد اسم ﴿الْمِيزَانَ﴾ ولم يُستبدل به ضمير؟","answer":"لزيادة العناية بالعدل واستحضار معناه صريحًا عند كل حكم، حتى يبقى الميزان حاضرًا في الذهن ولا يضعف أثره بالإضمار.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص706، تحت عنوان «الغرض من وضع المظهر ﴿الميزان﴾ موضع المضمر»","url":""}]},{"id":"s55-4","number":4,"surah":55,"verses":[13],"references":[{"surah":55,"verses":[13]}],"verseLabel":"الرحمن: 13 وما بعدها","question":"لماذا تكرر قوله: ﴿فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ﴾ في سورة الرحمن؟","answer":"جاء التكرار بعد أصناف النعم والقدرة والوعيد ليقررها صنفًا بعد صنف، ويجدد التبكيت كلما انتقل السياق إلى آية جديدة؛ فكل موضع مرتبط بما قبله وليس تكرارًا خاليًا من الفائدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص658–659، تحت عنوان «تنوع الأقوال في توجيه تكرار قوله: ﴿فبأي آلاء ربكما تكذبان﴾»","url":""}]},{"id":"s55-5","number":5,"surah":55,"verses":[46,62],"references":[{"surah":55,"verses":[46,62]}],"verseLabel":"الرحمن: 46، 62","question":"ماذا يعني قوله عن الجنتين الأخريين: ﴿وَمِنْ دُونِهِمَا جَنَّتَانِ﴾؟","answer":"أي هما دون الأوليين في المرتبة، أو أقرب منهما، مع بقاء كونهما جنتين عظيمتين؛ فالتعبير يقرر تفاوت درجات النعيم لا حرمان الفريق الثاني منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص119–120، تحت عنوان «بيان المراد بـ﴿دونهما﴾ ومرجع الضمير»","url":""}]},{"id":"s55-6","number":6,"surah":55,"verses":[27,78],"references":[{"surah":55,"verses":[27,78]}],"verseLabel":"الرحمن: 27، 78","question":"لماذا وُصف وجه الله بأنه ﴿ذُو الْجَلَالِ وَالْإِكْرَامِ﴾؟","answer":"ليجمع الوصف بين عظمته التي تورث الهيبة، وفضله الذي يفيض الإكرام والإنعام؛ فالكمال الإلهي جلال يُهاب وإحسان يُرجى.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص786، تحت عنوان «سر الوصف بـ﴿ذو الجلال والإكرام﴾ ودلالة العطف»","url":""}]},{"id":"s55-26","number":26,"surah":55,"verses":[27,78],"references":[{"surah":55,"verses":[27,78]}],"verseLabel":"الرحمن: 27، 78","question":"ما دلالة ذكر ﴿الْجَلَالِ وَالْإِكْرَامِ﴾ مرةً مع وجه الرب ومرةً مع اسمه؟","answer":"ذكرها مع الوجه يؤكد بقاء ذات الله وكمالها بعد فناء الخلق، وذكرها مع الاسم في الختام يجعل تنزيهه وتعظيمه جامعًا لمهابة الجلال ورجاء الإكرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص149، تحت عنوان «دلالة التغاير في ذكر ﴿الجلال والإكرام﴾ في السورة مرتين»","url":""}]},{"id":"s55-7","number":7,"surah":55,"verses":[1],"references":[{"surah":55,"verses":[1]}],"verseLabel":"الرحمن: 1","question":"ما سرّ افتتاح السورة باسم ﴿الرَّحْمَنُ﴾ وحده؟","answer":"يفتتح الاسم باب التشوق إلى ما سيخبر به عن الرحمن، ثم تأتي نعم التعليم والخلق وسائر الآلاء آثارًا لرحمته. وفي إبرازه أيضًا رد على من أنكر هذا الاسم، فالسورة تعرف بالرحمن من خلال نعمه الواسعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص665–666، تحت عنوان «سر الافتتاح بالاسم الجميل ﴿الرحمن﴾»","url":""}]},{"id":"s55-8","number":8,"surah":55,"verses":[4],"references":[{"surah":55,"verses":[4]}],"verseLabel":"الرحمن: 4","question":"ما سرّ التعبير في قول ﴿عَلَّمَهُ الْبَيَانَ﴾، ولم يقل «علّمه الكلام»؟","answer":"البيان في أوسع أوجهه قدرة الإنسان على الفهم والإفهام وإظهار المعاني، بالنطق والكتابة وغيرهما، ومعرفة ما يحتاج إليه في أمر دينه ودنياه. لذلك يبرز سعة نعمة التعليم، ولا يقف عند مجرد التلفظ بالكلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص674–675، تحت عنوان «معنى اللام ودلالتها في ﴿البيان﴾ وثراء الدلالة فيها»","url":""}]},{"id":"s55-9","number":9,"surah":55,"verses":[6],"references":[{"surah":55,"verses":[6]}],"verseLabel":"الرحمن: 6","question":"لماذا جُمع بين ﴿النَّجْمُ وَالشَّجَرُ﴾؟","answer":"لأن النجم نبات لا ساق له، والشجر نبات قائم على ساق؛ فجمعهما يحيط بطرفي عالم النبات ويصور خضوعه كله لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص689–690، تحت عنوان «بلاغة مراعاة النظير في ﴿والنجم والشجر﴾»","url":""}]},{"id":"s55-27","number":27,"surah":55,"verses":[6],"references":[{"surah":55,"verses":[6]}],"verseLabel":"الرحمن: 6","question":"كيف يسجد النجم والشجر؟","answer":"سجودهما خضوعهما لنظام الله وانقيادهما لما قدر لهما من نمو وحركة وظلال، وهو حقيقة تليق بهما وإن لم يكن كسجود الإنسان ذي الهيئة المعروفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص690–691، تحت عنوان «دلالة الفعل ﴿يسجدان﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s55-10","number":10,"surah":55,"verses":[7],"references":[{"surah":55,"verses":[7]}],"verseLabel":"الرحمن: 7","question":"لماذا عُطف وضع الميزان على رفع السماء؟","answer":"لأن رفع السماء نعمة تحفظ نظام الكون، ووضع العدل نعمة تحفظ نظام حياة الناس؛ فجمعهما يربط انتظام العالم المادي باستقامة المجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص695، تحت عنوان «سر عطف وضع الميزان على ما سبقه من النعم والآلاء»","url":""}]},{"id":"s55-28","number":28,"surah":55,"verses":[7],"references":[{"surah":55,"verses":[7]}],"verseLabel":"الرحمن: 7","question":"ما دلالة المقابلة بين ﴿رَفَعَهَا﴾ و﴿وَضَعَ الْمِيزَانَ﴾؟","answer":"يجمع التعبير بين حركة العلو والوضع في طباق خفي؛ فالسماء مرفوعة حسًا، والميزان موضوع تشريعًا، فتلتقي الصورتان في إحكام النظام.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص696–697، تحت عنوان «بلاغة التعبير بالطباق الخفي والمشاكلة الضدية»","url":""}]},{"id":"s55-11","number":11,"surah":55,"verses":[8,9],"references":[{"surah":55,"verses":[8,9]}],"verseLabel":"الرحمن: 8–9","question":"لماذا قيل: ﴿أَلَّا تَطْغَوْا فِي الْمِيزَانِ﴾ دون «ألا تظلموا»؟","answer":"لأن الطغيان تجاوز الحد، فيشمل كل انحراف عن العدل بالزيادة أو النقص، ويصور المخالفة خروجًا متعمدًا عن الميزان الذي وضعه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص699، تحت عنوان «دلالة التعبير بمادة الطغيان دون مادة الظلم»","url":""}]},{"id":"s55-29","number":29,"surah":55,"verses":[8,9],"references":[{"surah":55,"verses":[8,9]}],"verseLabel":"الرحمن: 8–9","question":"لماذا قيل: ﴿وَلَا تُخْسِرُوا الْمِيزَانَ﴾؟","answer":"لأن الإخسار إحداث النقص في حقوق الناس عمدًا، فينهى عن تحويل الميزان من أداة للعدل إلى وسيلة لسلب الحقوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص705، تحت عنوان «سر اختيار الفعل ﴿تخسروا﴾»","url":""}]},{"id":"s55-12","number":12,"surah":55,"verses":[10],"references":[{"surah":55,"verses":[10]}],"verseLabel":"الرحمن: 10","question":"ماذا تفيد اللام في قوله: ﴿وَالْأَرْضَ وَضَعَهَا لِلْأَنَامِ﴾؟","answer":"تفيد أن تهيئة الأرض واستقرارها كانا لنفع الخلق وتمكينهم من السكن والعيش؛ فتستحضر اللام مقصد الرحمة والتسخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص713، تحت عنوان «معنى اللام ودلالتها في ﴿للأنام﴾»","url":""}]},{"id":"s55-30","number":30,"surah":55,"verses":[10],"references":[{"surah":55,"verses":[10]}],"verseLabel":"الرحمن: 10","question":"لماذا قيل: ﴿لِلْأَنَامِ﴾ دون «للخلق»؟","answer":"لأن الأنام تستحضر الخلائق التي تدب على الأرض وتنتفع بها، وفيها جرس يلائم تعداد النعم، أما الخلق فأعم وأبعد عن تصوير هذا الانتفاع المباشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص713–714، تحت عنوان «دلالة التعبير بمفردة (الأنام) دون (الخلق)»","url":""}]},{"id":"s55-13","number":13,"surah":55,"verses":[11],"references":[{"surah":55,"verses":[11]}],"verseLabel":"الرحمن: 11","question":"لماذا خُص النخل بالذكر بعد الفاكهة في قوله: ﴿وَالنَّخْلُ﴾؟","answer":"لشرف النخل وكثرة منافعه وكونه من أوضح نعم العرب، فخص بعد العموم تنبيهًا إلى منزلته، وعُرّف لاستحضار جنسه المعروف لديهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص716–717، تحت عنوان «دلالة العطف في ﴿والنخل﴾، وسر تعريفه باللام دون الفاكهة»","url":""}]},{"id":"s55-31","number":31,"surah":55,"verses":[11],"references":[{"surah":55,"verses":[11]}],"verseLabel":"الرحمن: 11","question":"لماذا وُصف النخل بأنه ﴿ذَاتُ الْأَكْمَامِ﴾؟","answer":"لأن الأكمام تحفظ الطلع والثمر في نشأته حتى يكتمل، فالوصف يستحضر عناية الله الخفية بالثمرة قبل ظهورها ومراحل نموها.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص717، تحت عنوان «سر تقييد النخل بالوصف ﴿ذات الأكمام﴾»","url":""}]},{"id":"s55-14","number":14,"surah":55,"verses":[12],"references":[{"surah":55,"verses":[12]}],"verseLabel":"الرحمن: 12","question":"لماذا وُصف الحب بأنه ﴿ذُو الْعَصْفِ﴾؟","answer":"للتنبيه إلى تمام النعمة؛ فالحب غذاء للإنسان، وعصفه قشر وورق ينتفع به الحيوان، فلا يضيع من الزرع جزء بلا فائدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص718–719، تحت عنوان «سر وصف الحب بأنه ﴿ذو العصف﴾»","url":""}]},{"id":"s55-32","number":32,"surah":55,"verses":[12],"references":[{"surah":55,"verses":[12]}],"verseLabel":"الرحمن: 12","question":"لماذا ذُكر ﴿الرَّيْحَانُ﴾ مع الحب ذي العصف؟","answer":"لأن الريحان يشمل الرزق الطيب أو النبات ذي الرائحة، فيجمع السياق بين القوت الضروري وما يكمّل الحياة من طيب ومتعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص720، تحت عنوان «دلالة التعبير بالريحان مادة وصيغة»","url":""}]},{"id":"s55-15","number":15,"surah":55,"verses":[13],"references":[{"surah":55,"verses":[13]}],"verseLabel":"الرحمن: 13","question":"لماذا جاء الخطاب مثنى في ﴿رَبِّكُمَا تُكَذِّبَانِ﴾ قبل التصريح بالجن والإنس؟","answer":"من أوجه عود التثنية أنها للإنس والجن، وقد دل عليهما السياق والإشارة إلى الأنام، ثم صرح بهما فيما بعد. فلا يتوقف فهم الضمير على تقدم اسميهما صراحة؛ ويجمع الخطاب الطرفين في الاعتراف بآلاء ربهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص724–725، تحت عنوان «المقصود بعود الضمير في علامة التثنية»","url":""}]},{"id":"s55-16","number":16,"surah":55,"verses":[17],"references":[{"surah":55,"verses":[17]}],"verseLabel":"الرحمن: 17","question":"لماذا ثنّى فقال ﴿رَبُّ الْمَشْرِقَيْنِ وَرَبُّ الْمَغْرِبَيْنِ﴾؟","answer":"من أشهر أوجه التثنية مشرقا الشمس ومغرباها في طرفي الصيف والشتاء، وما بينهما معلوم تبعًا. وفي ذلك تصوير لتنوع المطالع والمغارب مع خضوعها لرب واحد، وتناسب مع نسق التثنية البارز في السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص744، تحت عنوان «سر التعبير بالمثنى في ﴿المشرقين﴾»","url":""}]},{"id":"s55-17","number":17,"surah":55,"verses":[19,20],"references":[{"surah":55,"verses":[19,20]}],"verseLabel":"الرحمن: 19–20","question":"ما الصورة في قوله عن البحرين: ﴿يَلْتَقِيَانِ﴾؟","answer":"شُبّه تقارب البحرين واتصال مائهما بلقاء شخصين، فصار المشهد الكوني حركة حية مع بقاء لكل بحر خصائصه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص755، تحت عنوان «بلاغة التعبير بالاستعارة في ﴿يلتقيان﴾»","url":""}]},{"id":"s55-33","number":33,"surah":55,"verses":[19,20],"references":[{"surah":55,"verses":[19,20]}],"verseLabel":"الرحمن: 19–20","question":"ما دلالة قوله عن البحرين: ﴿لَا يَبْغِيَانِ﴾؟","answer":"كُني عن عدم تجاوز أحدهما الحد المقدر له بصورة شخصين لا يعتدي أحدهما على الآخر، فبرز البرزخ قانونًا مانعًا للاختلاط المفسد.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص757، تحت عنوان «بلاغة التعبير بالكناية في ﴿يبغيان﴾»","url":""}]},{"id":"s55-18","number":18,"surah":55,"verses":[24],"references":[{"surah":55,"verses":[24]}],"verseLabel":"الرحمن: 24","question":"لماذا وُصفت السفن بأنها ﴿الْمُنْشَآتُ﴾؟","answer":"لأن اللفظ يستحضر صنعها ورفع شراعها وظهورها قائمة في البحر، فيجمع دقة الصناعة وضخامة الهيئة واستعدادها للجري.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص768، تحت عنوان «دلالة التعبير بـ﴿المنشآت﴾»","url":""}]},{"id":"s55-19","number":19,"surah":55,"verses":[26,27],"references":[{"surah":55,"verses":[26,27]}],"verseLabel":"الرحمن: 26–27","question":"لماذا ذُكر فناء من على الأرض في سياق تعداد النعم؟","answer":"للتذكير بأن نعم الدنيا مهما عظمت زائلة، فيتجه القلب إلى المنعم الباقي ويستعمل النعمة فيما ينفع قبل انقضائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص780–781، تحت عنوان «فائدة ذكر الفناء في السورة الكريمة»","url":""}]},{"id":"s55-34","number":34,"surah":55,"verses":[26,27],"references":[{"surah":55,"verses":[26,27]}],"verseLabel":"الرحمن: 26–27","question":"ما دلالة المقابلة بين ﴿فَانٍ﴾ و﴿وَيَبْقَى وَجْهُ رَبِّكَ﴾؟","answer":"تبرز أن الفناء شامل للخلق، وأن البقاء المطلق لله وحده؛ فتقطع تعلق القلب بالمحدود وترده إلى صاحب الجلال والإكرام.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص782–783، تحت عنوان «بلاغة التعبير بالطباق بين ﴿ويبقى﴾ و﴿فان﴾»","url":""}]},{"id":"s55-20","number":20,"surah":55,"verses":[29],"references":[{"surah":55,"verses":[29]}],"verseLabel":"الرحمن: 29","question":"ما دلالة ﴿يَوْمٍ﴾ في قوله: ﴿كُلَّ يَوْمٍ هُوَ فِي شَأْنٍ﴾؟","answer":"اليوم هنا مجاز عن كل وقت ولحظة، أي إن آثار تدبير الله لا تنقطع في زمن دون زمن، بل تتجدد دائمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص794، تحت عنوان «دلالة المجاز في ﴿يوم﴾»","url":""}]},{"id":"s55-35","number":35,"surah":55,"verses":[29],"references":[{"surah":55,"verses":[29]}],"verseLabel":"الرحمن: 29","question":"ماذا يعني ﴿شَأْنٍ﴾ في قوله: ﴿كُلَّ يَوْمٍ هُوَ فِي شَأْنٍ﴾، ولماذا نُكِّرت؟","answer":"الشأن فعل عظيم من أفعال تدبيره: يحيي ويميت ويعطي ويمنع ويغفر ويكشف الضر؛ وتنكيره للتعظيم والتكثير، إذ لا تحيط العبارة بتنوع شؤونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص795–796، تحت عنوان «المراد بـ﴿شأن﴾، والغرض من تنكيرها»","url":""}]},{"id":"s55-21","number":21,"surah":55,"verses":[31],"references":[{"surah":55,"verses":[31]}],"verseLabel":"الرحمن: 31","question":"ما سرّ التعبير بقوله ﴿سَنَفْرُغُ لَكُمْ أَيُّهَ الثَّقَلَانِ﴾ مع أن الله لا يشغله شأن؟","answer":"هو تصوير للوعيد وتمام القصد إلى المحاسبة، على نحو قول المهدد لمن يتوعده إنه سيتفرغ له. فالمراد تحقيق الحساب وشدته بعد انقضاء مهلة الدنيا، وليس خلو الله من شغل كان يعوقه عن غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص13–14، تحت عنوان «بلاغة التعبير بالاستعارة في ﴿سنفرغ﴾»","url":""}]},{"id":"s55-22","number":22,"surah":55,"verses":[41],"references":[{"surah":55,"verses":[41]}],"verseLabel":"الرحمن: 41","question":"ما سرّ التعبير في قول ﴿يُعْرَفُ الْمُجْرِمُونَ بِسِيمَاهُمْ﴾، ولم يقل «الكافرون»؟","answer":"الإجرام وصف جامع لصور الشر والذنوب والجحود، فيبرز استحقاقهم العقوبة ويشتد به التبكيت. فالتعبير يواجههم بصفة ما اقترفوه من جرم، وهي المناسبة لهذا المقام من الأخذ والعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص55، تحت عنوان «سر إيثار التعبير بنائب الفاعل بلفظ ﴿المجرمون﴾ دون غيره»","url":""}]},{"id":"s55-23","number":23,"surah":55,"verses":[46],"references":[{"surah":55,"verses":[46]}],"verseLabel":"الرحمن: 46","question":"لماذا أُفرد الخائف في قوله: ﴿وَلِمَنْ خَافَ مَقَامَ رَبِّهِ جَنَّتَانِ﴾؟","answer":"ليتناول الوعد كل فرد على حدة، فيشعر كل سامع أن الجزاء متعلق بخوفه وعمله شخصيًا، مع أن اللفظ يعم أفرادًا كثيرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص78، تحت عنوان «علة التعبير بـ﴿خاف﴾ مسندًا للمفرد دون الجمع»","url":""}]},{"id":"s55-24","number":24,"surah":55,"verses":[48,64,66],"references":[{"surah":55,"verses":[48,64,66]}],"verseLabel":"الرحمن: 48، 64، 66","question":"لماذا وُصفت الجنتان الأوليان بأنهما ﴿ذَوَاتَا أَفْنَانٍ﴾؟","answer":"للدلالة على كثرة الأغصان وتنوع الثمار والظلال؛ فالأفنان تجمع صورة الامتداد والجمال وتعدد ألوان النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص82–83، تحت عنوان «سر وصف الجنتين بقوله: ﴿ذواتا أفنان﴾»","url":""}]},{"id":"s55-36","number":36,"surah":55,"verses":[48,64,66],"references":[{"surah":55,"verses":[48,64,66]}],"verseLabel":"الرحمن: 48، 64، 66","question":"لماذا قيل في العينين الأوليين: ﴿تَجْرِيَانِ﴾ بالمضارع؟","answer":"ليصور جريانهما متجددًا مستمرًا أمام أهل الجنة، فلا ينقطع ماؤهما ولا يفتر تدفقهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص84، تحت عنوان «الغرض من وصف العينين بالجملة الفعلية بصيغة المضارع»","url":""}]},{"id":"s55-37","number":37,"surah":55,"verses":[48,64,66],"references":[{"surah":55,"verses":[48,64,66]}],"verseLabel":"الرحمن: 48، 64، 66","question":"لماذا وُصفت الجنتان الأخريان بأنهما ﴿مُدْهَامَّتَانِ﴾ في مقابل ﴿ذَوَاتَا أَفْنَانٍ﴾؟","answer":"لأن شدة الخضرة في الأخريين تصور امتلاءهما بالنبات والري، بينما ﴿ذواتا أفنان﴾ تبرز تنوع الأغصان والثمار في الأوليين؛ فلكل مرتبة جمالها الخاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص121، تحت عنوان «دلالة الوصف بـ﴿مدهامتان﴾ في مقابل ﴿ذواتا أفنان﴾»","url":""}]},{"id":"s55-38","number":38,"surah":55,"verses":[48,64,66],"references":[{"surah":55,"verses":[48,64,66]}],"verseLabel":"الرحمن: 48، 64، 66","question":"لماذا قيل في العينين الأخريين: ﴿نَضَّاخَتَانِ﴾ بدل «تجريان»؟","answer":"لأن النضخ يدل على فوران الماء واندفاعه من منبعه، فيعطي صورة قوة وغزارة تختلف عن صورة الجريان الممتد في الجنتين الأوليين.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص122–123، تحت عنوان «دلالة التعبير بالنضخ دون النضح أو الجري»","url":""}]},{"id":"s56-1","number":1,"surah":56,"verses":[13,14],"references":[{"surah":56,"verses":[13,14]}],"verseLabel":"الواقعة: 13–14","question":"ما سرّ التعبير في السابقين ﴿ثُلَّةٌ مِنَ الْأَوَّلِينَ وَقَلِيلٌ مِنَ الْآخِرِينَ﴾؟","answer":"المقابلة بين الثلة والقليل تبين كثرة السابقين من الأولين بالنسبة إلى السابقين من الآخرين. فالكثرة والقلة هنا في مرتبة المقربين، ولا يلزم منهما الحكم على مجموع أهل الجنة؛ كما أن المقصود تفاوت العدد النسبي بين الفريقين، لا تعيين عدد محدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص240–241، تحت عنوان «دلالة العطف التقابلي بين (قليل) و﴿ثلة﴾»","url":""}]},{"id":"s56-2","number":2,"surah":56,"verses":[21,22],"references":[{"surah":56,"verses":[21,22]}],"verseLabel":"الواقعة: 21–22","question":"لماذا ذُكر ﴿وَحُورٌ عِينٌ﴾ نعيمًا مستقلًا بعد الطعام والشراب؟","answer":"لأن استئناف العبارة ينقل المشهد من المطعومات التي يطوف بها الولدان إلى لون أرفع من نعيم الصحبة والأنس، فيفصل مقام الحور ويشرفه بدل أن يجعله مجرد عنصر في قائمة الطعام والشراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص275–276، تحت عنوان «نوع الواو في قوله: ﴿وحور﴾ ودلالتها»","url":""}]},{"id":"s56-3","number":3,"surah":56,"verses":[60,61],"references":[{"surah":56,"verses":[60,61]}],"verseLabel":"الواقعة: 60–61","question":"لماذا نُفي أن يكون الله ﴿بِمَسْبُوقِينَ﴾ بدل أن يقال «بمغلوبين»؟","answer":"لأن نفي السَّبق يقطع أصل إمكان أن يفوته شيء أو يتقدم على إرادته أحد؛ فالغلبة قد تُتصور بعد نزاع، أما السبق فينفي أن تبدأ المعارضة أصلًا أو يمر مانع قبل نفاذ قدره. وبذلك يشتد تقرير القدرة على الموت والإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص415–416، تحت عنوان «بلاغة استعمال مفردة السبق دون الغلبة»","url":""}]},{"id":"s56-29","number":29,"surah":56,"verses":[60,61],"references":[{"surah":56,"verses":[60,61]}],"verseLabel":"الواقعة: 60–61","question":"ماذا يتسع له قوله ﴿أَنْ نُبَدِّلَ أَمْثَالَكُمْ﴾؟","answer":"يتسع لأن يبدل الله قومًا بغيرهم، ولأن ينشئهم بعد الموت في خلق وهيئة لا يعرفونها. فلفظ الأمثال يوجز صور التبديل كلها، ويقرر أن القادر على الخلق الأول لا يعجزه إهلاكهم أو إعادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص416، تحت عنوان «بلاغة التعبير بلفظ: ﴿أمثالكم﴾»","url":""}]},{"id":"s56-4","number":4,"surah":56,"verses":[65,70],"references":[{"surah":56,"verses":[65,70]}],"verseLabel":"الواقعة: 65، 70","question":"ما دلالة إثبات اللام في ﴿لجعلناه حطامًا﴾ وحذفها في ﴿جعلناه أجاجًا﴾؟","answer":"إثبات اللام في الزرع يزيد التوكيد والتهديد، لأن انقلاب الزرع الناضر حطامًا يصادم ما اطمأن إليه صاحبه بعد تعهده. أما صيرورة الماء ملحًا فمما يقرب تصوره، فجاء الجواب دون هذه الزيادة. وتذكر الموسوعة وجهًا آخر: قد يوهم ما يبذله البشر في الزرع استقلالهم به، فاحتيج إلى توكيد القدرة، بخلاف إنزال الماء الذي لا يد لهم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص465–466، تحت عنوان «توجيه المتشابه اللفظي في حذف اللام وإثباتها في السابقة»","url":""}]},{"id":"s56-5","number":5,"surah":56,"verses":[70],"references":[{"surah":56,"verses":[70]}],"verseLabel":"الواقعة: 70","question":"ما الذي تضيفه ﴿لَوْلَا﴾ إلى دعوة الناس لشكر نعمة الماء؟","answer":"تحول الدعوة إلى تحضيض قوي يحمل معنى: هلا تجددون الشكر وتداومون عليه؟ فهي توقظ الضمير بلطف العتاب، لأن بقاء النعمة مع ظهور مصدرها يجعل ترك الشكر أمرًا مستغربًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص467، تحت عنوان «غرض استعمال (لولا)»","url":""}]},{"id":"s56-30","number":30,"surah":56,"verses":[70],"references":[{"surah":56,"verses":[70]}],"verseLabel":"الواقعة: 70","question":"لماذا انتهت آية الماء إلى الشكر لا إلى مجرد الإيمان؟","answer":"لأن المقام مقام نعمة محسوسة يشربها الناس ويرون أثرها، والشكر هو ثمرة الإيمان عند مشاهدة الإنعام: اعتراف بالمنعم وخضوع له واستعمال النعمة في طاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص467، تحت عنوان «بلاغة استعمال ﴿تشكرون﴾»","url":""}]},{"id":"s56-6","number":6,"surah":56,"verses":[75],"references":[{"surah":56,"verses":[75]}],"verseLabel":"الواقعة: 75","question":"ما سرّ التعبير في قول ﴿فَلَا أُقْسِمُ بِمَوَاقِعِ النُّجُومِ﴾ بدل «أقسم»؟","answer":"تذكر الموسوعة أن «لا» تحتمل تقوية القسم وتوكيده، وتحتمل نفي الحاجة إليه لوضوح الحق؛ وهذا النفي نفسه أسلوب في تعظيم المقسم عليه. ففي الوجهين تمهيد مهيب لتقرير كرامة القرآن، لا تراجع عن تأكيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص488–489، تحت عنوان «دلالة استعمال (لا) في سياق القسم»","url":""}]},{"id":"s56-7","number":7,"surah":56,"verses":[84,85],"references":[{"surah":56,"verses":[84,85]}],"verseLabel":"الواقعة: 84–85","question":"كيف ينظر أهل المحتضر إليه ثم يقال لهم ﴿لَا تُبْصِرُونَ﴾؟","answer":"لأن النظر يقع بالعين إلى ظاهر المشهد، أما الإبصار هنا فهو إدراك حقيقته الغيبية. فهم يشاهدون الجسد وخروج الروح، لكنهم لا يرون قرب الملائكة ولا ينفذ حسهم إلى ما وراء الظاهر؛ فتتكشف محدودية الإدراك البشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص528–529، تحت عنوان «بلاغة مجيء فعل النظر مثبتًا والإبصار منفيًا»","url":""}]},{"id":"s56-8","number":8,"surah":56,"verses":[1],"references":[{"surah":56,"verses":[1]}],"verseLabel":"الواقعة: 1","question":"لماذا افتتحت السورة بفعل ﴿وَقَعَتِ﴾ لا «جاءت القيامة»؟","answer":"لأن الوقوع يوحي بسقوط أمر ثقيل مفاجئ لا يستطيع أحد دفعه أو رده؛ فليست القيامة مجيئًا عابرًا، بل حدثًا هائلًا يصيب العالم ويستقر أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص163، تحت عنوان «بلاغة استعمال مفردة ﴿وقعت﴾»","url":""}]},{"id":"s56-31","number":31,"surah":56,"verses":[1],"references":[{"surah":56,"verses":[1]}],"verseLabel":"الواقعة: 1","question":"لماذا صُورت القيامة بصيغة الماضي في ﴿إِذَا وَقَعَتِ﴾ وهي مستقبلة؟","answer":"لتنقلها من دائرة الانتظار إلى مشهد متحقق كأنه وقع وانتهى؛ فيترسخ اليقين بوعد الله، ويفاجأ السامع بهول الحدث حاضرًا أمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص163–164، تحت عنوان «فائدة التعبير بصيغة الماضي ﴿وقعت﴾»","url":""}]},{"id":"s56-32","number":32,"surah":56,"verses":[1],"references":[{"surah":56,"verses":[1]}],"verseLabel":"الواقعة: 1","question":"ماذا يضيف تعريف القيامة باسم ﴿الْوَاقِعَةُ﴾؟","answer":"يجعلها الواقعة المعهودة التي تنصرف إليها الأذهان ولا تلتبس بحادثة أخرى، ويضفي عليها معنى الكمال والتهويل؛ فكأن الوقائع كلها دونها وهي وحدها الواقعة حقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص165، تحت عنوان «معنى تعريف لفظ ﴿الواقعة﴾»","url":""}]},{"id":"s56-9","number":9,"surah":56,"verses":[2],"references":[{"surah":56,"verses":[2]}],"verseLabel":"الواقعة: 2","question":"كيف تحتمل كلمة ﴿كَاذِبَةٌ﴾ معنيين يؤكدان يقين القيامة؟","answer":"يجوز أن تكون وصفًا لنفس تكذب بوقوعها، فيكون المعنى أنه لا يبقى يومئذ مكذب؛ ويجوز أن تكون مصدرًا بمعنى الكذب، فينفي النص أن يخالط وقوعها أي باطل. والوجهان يقطعان الشك من جهة الناس ومن جهة الحدث نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص172–173، تحت عنوان «توجيه ﴿كاذبة﴾ بين المصدرية والوصفية»","url":""}]},{"id":"s56-10","number":10,"surah":56,"verses":[3],"references":[{"surah":56,"verses":[3]}],"verseLabel":"الواقعة: 3","question":"ما سرّ تقديم ﴿خَافِضَةٌ﴾ على ﴿رَافِعَةٌ﴾؟","answer":"تقديم الخفض يناسب مقام التهويل وما يبدأ به مشهد القيامة من انهيار القوى الشامخة واضطراب الأرض والجبال. ثم يأتي الرفع بعده، فيصور انقلاب موازين الدنيا: هبوط من اغتر بعلوه، وارتفاع من أكرمه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص184، تحت عنوان «علة تقديم ﴿خافضة﴾ على ﴿رافعة﴾»","url":""}]},{"id":"s56-11","number":11,"surah":56,"verses":[6],"references":[{"surah":56,"verses":[6]}],"verseLabel":"الواقعة: 6","question":"ما سرّ التعبير في قول ﴿وَبُسَّتِ الْجِبَالُ بَسًّا﴾، ولم يقل «سيرت»؟","answer":"البس يدل على التفتيت والخلط حتى تزول صلابة الجبال وتتفرق أجزاؤها. فهو يصور انهيار بنيتها وتحولها إلى فتات، ولا يقتصر على معنى انتقالها من موضع إلى آخر الذي يوحي به التسيير.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص194–195، تحت عنوان «بلاغة استعمال مفردة (بست)»","url":""}]},{"id":"s56-12","number":12,"surah":56,"verses":[7],"references":[{"surah":56,"verses":[7]}],"verseLabel":"الواقعة: 7","question":"ما سرّ التعبير في قول ﴿وَكُنْتُمْ أَزْوَاجًا ثَلَاثَةً﴾، ولم يقل «أصنافًا»؟","answer":"الأزواج أصناف يقترن أفراد كل منها في الصفات والعمل والمصير. ففي اللفظ معنى المشاكلة والصحبة فوق مجرد التقسيم إلى أنواع، إذ يجتمع كل فريق بمن يناسبه في حاله وجزائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص203، تحت عنوان «بلاغة استعمال مفردة ﴿أزواجًا﴾»","url":""}]},{"id":"s56-13","number":13,"surah":56,"verses":[8,9],"references":[{"surah":56,"verses":[8,9]}],"verseLabel":"الواقعة: 8–9","question":"ماذا تضيف كلمة ﴿أَصْحَابُ﴾ إلى وصف فريقي الميمنة والمشأمة؟","answer":"تشعر الصحبة بالملازمة والاتصال بالمصير؛ فكأن كل فريق صار ملازمًا للجهة والحال التي آل إليها، لا منسوبًا إليها نسبة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص210، تحت عنوان «نكتة استعمال مفردة (أصحاب)»","url":""}]},{"id":"s56-14","number":14,"surah":56,"verses":[10],"references":[{"surah":56,"verses":[10]}],"verseLabel":"الواقعة: 10","question":"ما دلالة تكرار ﴿والسابقون السابقون﴾؟","answer":"التكرار يفخم منزلتهم ويجعلهم كأنهم لا يعرفون بأبلغ من وصف السبق نفسه. ويحتمل أن يكون الثاني توكيدًا للأول ثم يأتي بيان منزلتهم في ﴿أولئك المقربون﴾، أو خبرًا عنه على معنى أنهم السابقون حقًا؛ وكلا الوجهين يرفع شأنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص222–223، تحت عنوان «نكتة تكرار لفظ ﴿السابقون﴾»","url":""}]},{"id":"s56-15","number":15,"surah":56,"verses":[11],"references":[{"surah":56,"verses":[11]}],"verseLabel":"الواقعة: 11","question":"ما سرّ التعبير في قول ﴿الْمُقَرَّبُونَ﴾، ولم يقل «القريبون»؟","answer":"صيغة «المقربون» تبرز أن الله هو الذي منحهم هذه المنزلة واصطفاهم لها. فالقرب قرب إكرام ورفعة، لا مجرد قرب مكاني؛ وفي البناء للمفعول جمع بين علو مقامهم وكونه فضلًا من ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص228، تحت عنوان «نكتة التعبير بصيغة ﴿المقربون﴾»","url":""}]},{"id":"s56-16","number":16,"surah":56,"verses":[17],"references":[{"surah":56,"verses":[17]}],"verseLabel":"الواقعة: 17","question":"لماذا اختير وصف خدم الجنة بـ﴿وِلْدَانٌ﴾؟","answer":"لأنه يستحضر صغر السن ونضارة الهيئة وخفة الحركة، فيناسب خدمة لا كلفة فيها ولا رهبة، ويكمل صورة الأنس والنعيم والسرور.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص253، تحت عنوان «بلاغة استعمال مفردة ﴿ولدان﴾»","url":""}]},{"id":"s56-33","number":33,"surah":56,"verses":[17],"references":[{"surah":56,"verses":[17]}],"verseLabel":"الواقعة: 17","question":"ماذا يطمئن إليه أهل الجنة في وصف الخدم بأنهم ﴿مُخَلَّدُونَ﴾؟","answer":"يطمئنون إلى أنهم باقون على سن واحدة وهيئة ناضرة، لا يهرمون ولا تنقص طاقتهم ولا تنقطع خدمتهم؛ فالخلود هنا ثبات الصفة والجمال مع دوام البقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص254، تحت عنوان «فائدة الوصف بلفظ ﴿مخلدون﴾»","url":""}]},{"id":"s56-17","number":17,"surah":56,"verses":[19],"references":[{"surah":56,"verses":[19]}],"verseLabel":"الواقعة: 19","question":"كيف يكمل قوله ﴿وَلَا يُنْزِفُونَ﴾ نفي أضرار شراب الجنة؟","answer":"بعد نفي صداع الرأس نُفي ذهاب العقل ونفاد الشراب؛ فالعطف يستوفي الضرر الجسدي والنفسي والانقطاع، ويبين أن لذة خمر الجنة لا يعقبها ألم ولا سكر ولا زوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص264–265، تحت عنوان «فائدة عطف ﴿ولا ينزفون﴾»","url":""}]},{"id":"s56-18","number":18,"surah":56,"verses":[23],"references":[{"surah":56,"verses":[23]}],"verseLabel":"الواقعة: 23","question":"لماذا شبه الحور بـ﴿أَمْثَالِ اللُّؤْلُؤِ الْمَكْنُونِ﴾؟","answer":"اللؤلؤ المكنون محفوظ في صدفه، لم تخدش صفاءه الأيدي ولم تغيره المؤثرات. فالتشبيه يجمع النقاء والجمال والنفاسة والصون، ولا يقتصر على لون البياض وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص280، تحت عنوان «فائدة تشبيه الحور العين باللؤلؤ المكنون»","url":""}]},{"id":"s56-19","number":19,"surah":56,"verses":[25,26],"references":[{"surah":56,"verses":[25,26]}],"verseLabel":"الواقعة: 25–26","question":"لماذا تكرر السلام في قوله ﴿سَلَامًا سَلَامًا﴾؟","answer":"للتأكيد والتعظيم وإشعار أهل الجنة بأن السلام يتجدد عليهم مرة بعد مرة، وتتنوع وجوه الأمن والتكريم؛ فيدخل معنى الطمأنينة في النفس دخولًا ثابتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص290، تحت عنوان «غرض تكرار ﴿سلامًا﴾»","url":""}]},{"id":"s56-20","number":20,"surah":56,"verses":[31],"references":[{"surah":56,"verses":[31]}],"verseLabel":"الواقعة: 31","question":"ما سرّ وصف الماء بأنه ﴿مَسْكُوبٍ﴾، لا «جارٍ»؟","answer":"المسكوب يوحي بماء يصب سهلًا متصلًا، متاح للانتفاع بلا عناء في طلبه. والجريان يصف حركة الماء، أما السكب فيزيد صورة الوفرة والتهيئة للشارب؛ فكأن الماء أعد وأرسل إلى أهل الجنة حيث يشاؤون.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص307، تحت عنوان «بلاغة وصف الماء بالمسكوب»","url":""}]},{"id":"s56-21","number":21,"surah":56,"verses":[35,36,37],"references":[{"surah":56,"verses":[35,36,37]}],"verseLabel":"الواقعة: 35–37","question":"إلى من يعود الضمير في ﴿إِنَّا أَنْشَأْنَاهُنَّ﴾ مع أن النساء لم يُذكرن صراحة؟","answer":"يعود إلى النساء اللاتي دل عليهن سياق الفرش والنعيم، ويشمل نساء الدنيا الصالحات والحور العين. وترك الاسم الظاهر يفتح المعنى على هذا الشمول ويعظم النعمة بدل حصرها في نوع واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص316–317، تحت عنوان «تعيين مرجع الضمير في قوله: ﴿أنشأناهن﴾»","url":""}]},{"id":"s56-34","number":34,"surah":56,"verses":[35,36,37],"references":[{"surah":56,"verses":[35,36,37]}],"verseLabel":"الواقعة: 35–37","question":"لماذا وصف إيجاد نساء الجنة بقوله ﴿أَنْشَأْنَاهُنَّ﴾؟","answer":"لأن الإنشاء يتسع للخلق ابتداء ولإعادة الخلق في صورة أخرى؛ فيشمل خلق الحور وتجديد نساء الدنيا في أكمل هيئة، ويجمع الحقيقة والمجاز في لفظ موجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص316، تحت عنوان «بلاغة استعمال مفردة ﴿أنشأناهن﴾»","url":""}]},{"id":"s56-35","number":35,"surah":56,"verses":[35,36,37],"references":[{"surah":56,"verses":[35,36,37]}],"verseLabel":"الواقعة: 35–37","question":"ماذا يفيد جعل نساء الجنة ﴿أَبْكَارًا﴾؟","answer":"يفيد دوام حال الكمال والتجدد؛ فكل واحدة تعاد إلى تمام العفة والنضارة، ولا يزيل تكرر المعاشرة عنها هذه الصفة، فتكون البكارة وصفًا دائمًا من أوصاف النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص320، تحت عنوان «توجيه وصفهن بالأبكار»","url":""}]},{"id":"s56-22","number":22,"surah":56,"verses":[42],"references":[{"surah":56,"verses":[42]}],"verseLabel":"الواقعة: 42","question":"لماذا جُمع لأصحاب الشمال بين ﴿سَمُومٍ وَحَمِيمٍ﴾؟","answer":"ليحيط بهم العذاب من جهتين: ريح حارة تحرق من الخارج، وماء بالغ الحرارة ينفذ إلى الداخل. فاجتماعهما يرسم إحاطة حسية لا يجد الجسد منها منفذًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص339، تحت عنوان «توجيه تخصيص السموم والحميم بالذكر»","url":""}]},{"id":"s56-23","number":23,"surah":56,"verses":[45],"references":[{"surah":56,"verses":[45]}],"verseLabel":"الواقعة: 45","question":"لماذا علل عذابهم بأنهم ﴿كَانُوا قَبْلَ ذَلِكَ مُتْرَفِينَ﴾؟","answer":"ليس المقصود مجرد امتلاك النعمة، بل تنعم أورث الغفلة والبطر والتكبر وترك الشكر. فذكر الترف يكشف منشأ إصرارهم على الذنب وإنكار الحساب، ويبين مسؤوليتهم عن سوء استعمال ما أتيح لهم من النعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص353، تحت عنوان «توجيه تخصيص الترف بالذكر»","url":""}]},{"id":"s56-24","number":24,"surah":56,"verses":[49,50],"references":[{"surah":56,"verses":[49,50]}],"verseLabel":"الواقعة: 49–50","question":"لماذا قيل عن الأولين والآخرين ﴿لَمَجْمُوعُونَ﴾ لا «لمبعوثون»؟","answer":"لأن الجمع يتضمن البعث ويزيد عليه أنهم يحشرون كلهم في وقت واحد بعد تفرق موتهم في الأزمنة والأماكن؛ فيصير اللفظ أصرح في الاجتماع وأشد وقعًا في الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص372، تحت عنوان «نكتة العدول عن لفظ البعث إلى الجمع»","url":""}]},{"id":"s56-25","number":25,"surah":56,"verses":[58,59],"references":[{"surah":56,"verses":[58,59]}],"verseLabel":"الواقعة: 58–59","question":"لماذا ردَّهم القرآن إلى ما ﴿تُمْنُونَ﴾ عند الاستدلال على البعث؟","answer":"لأن اللفظ يعيد الإنسان إلى نقطة الخلق الأولى: قطرة مهينة لا يملك سرها ولا مصيرها. فمن أبدع الإنسان منها قادر على أن يعيده بعد أن يصير عظامًا وترابًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص406–407، تحت عنوان «براعة اختيار مفردة ﴿تمنون﴾»","url":""}]},{"id":"s56-36","number":36,"surah":56,"verses":[58,59],"references":[{"surah":56,"verses":[58,59]}],"verseLabel":"الواقعة: 58–59","question":"ما الذي يقرره الاستفهام ﴿أَأَنْتُمْ تَخْلُقُونَهُ﴾ بعد ذكر النطفة؟","answer":"يقرر أن مباشرة السبب ليست خلقًا؛ فالناس يلقون النطفة لكنهم لا يصنعون مادتها ولا يدبرون أطوارها. والاستفهام يلزمهم بالإقرار بأن خالق النشأة الأولى هو القادر على الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص407–408، تحت عنوان «غرض الاستفهام في قوله: ﴿أأنتم﴾»","url":""}]},{"id":"s56-26","number":26,"surah":56,"verses":[63,64],"references":[{"surah":56,"verses":[63,64]}],"verseLabel":"الواقعة: 63–64","question":"كيف يكشف الانتقال من ﴿تَحْرُثُونَ﴾ إلى ﴿تَزْرَعُونَهُ﴾ حدود قدرة الإنسان؟","answer":"ذكر الحرث أولًا لأنه العمل الظاهر الذي يباشره الإنسان من شق الأرض وبذرها، ثم اختص الله بالزرع وهو الإحياء والإنبات. وحذف كل فعل من موضع صاحبه يكشف الفارق: للإنسان السبب، ولله الإيجاد الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص440، تحت عنوان «بلاغة الاحتباك بين فعلي الحرث والزراعة»","url":""}]},{"id":"s56-27","number":27,"surah":56,"verses":[68,69],"references":[{"surah":56,"verses":[68,69]}],"verseLabel":"الواقعة: 68–69","question":"لماذا قيل إن الماء ينزل من ﴿الْمُزْنِ﴾ لا من «السحاب»؟","answer":"لأن المزن أخص: هو السحاب المشحون بالماء والمنتظر منه المطر، لا مطلق السحاب العابر. فاختياره يربط ماء الشرب بوعائه الحقيقي، ويجعل النعمة والتحدي أوضح.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص462، تحت عنوان «نكتة استعمال مفردة ﴿المزن﴾ دون رديفاتها»","url":""}]},{"id":"s56-28","number":28,"surah":56,"verses":[75],"references":[{"surah":56,"verses":[75]}],"verseLabel":"الواقعة: 75","question":"ما المعاني التي يفتحها القسم بـ﴿مَوَاقِعِ النُّجُومِ﴾؟","answer":"يفتح معنى منازل النجوم ومساراتها ومطالعها ومغاربها، ويفتح أيضًا معنى مواقع نزول آيات القرآن وتدرج الوحي؛ فعلى الأول تعظيم لنظام السماء، وعلى الثاني تعظيم لحكمة التنزيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص490، تحت عنوان «دلالة مفردة (مواقع)»","url":""}]},{"id":"s56-37","number":37,"surah":56,"verses":[75],"references":[{"surah":56,"verses":[75]}],"verseLabel":"الواقعة: 75","question":"لماذا أقسم القرآن بمواقع النجوم لا بالنجوم وحدها؟","answer":"لأن المواقع تشمل نظام النجوم كله: طلوعها وغروبها ومساراتها وتباعدها في الزمان والمكان، فتكون أوسع دلالة وأدعى إلى الخشوع والتأمل من ذكر الأجرام مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص493، تحت عنوان «نكتة ذكر (مواقع) دون الاكتفاء بالنجوم»","url":""}]},{"id":"s56-38","number":38,"surah":56,"verses":[75],"references":[{"surah":56,"verses":[75]}],"verseLabel":"الواقعة: 75","question":"ماذا يضيف وصف القسم بمواقع النجوم بأنه ﴿عَظِيمٌ﴾؟","answer":"يفخم المقام ويوقظ السامع إلى جلال المقسَم به وخفاء أسراره، ويمهد لتعظيم المقسَم عليه وهو القرآن الكريم؛ فكأن عظمة الآية الكونية تقود إلى عظمة الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص498، تحت عنوان «دلالة وصف القسم بعظيم»","url":""}]},{"id":"s57-1","number":1,"surah":57,"verses":[1],"references":[{"surah":57,"verses":[1]}],"verseLabel":"الحديد: 1","question":"ما سرّ افتتاح الحديد ﴿سَبَّحَ لِلَّهِ﴾ بعد أن ختمت الواقعة بالأمر ﴿فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظِيمِ﴾؟","answer":"ختمت الواقعة بالأمر بالتسبيح، ثم أخبرت الحديد بتسبيح ما في السماوات والأرض، فظهر اتصال الأمر بما يشهد له الكون كله. وكأن المطلع يقول للمخاطب: سبح ربك، فقد سبحت له المخلوقات، فيتسع مشهد التعظيم ويؤكد استحقاقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص577، تحت عنوان «مناسبة السورة لما قبلها»","url":""}]},{"id":"s57-2","number":2,"surah":57,"verses":[1],"references":[{"surah":57,"verses":[1]}],"verseLabel":"الحديد: 1","question":"ما سرّ جمع السماوات والأرض تحت اسم الموصول الواحد في قوله ﴿مَا فِي السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"عدم تكرار «ما» يجمع السماوات والأرض في نظر المخاطب كأنهما شيء واحد في الخضوع لله ووحدة التسبيح. ويناسب ذلك ما يلي من تقرير صفات الله وملكه العام، فتلتقي كثرة المخلوقات في وحدة العبودية والسلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص585، تحت عنوان «سر عدم اقتران (ما) بالأرض كما اقترنت بالسماوات»","url":""}]},{"id":"s57-3","number":3,"surah":57,"verses":[1],"references":[{"surah":57,"verses":[1]}],"verseLabel":"الحديد: 1","question":"لماذا ناسب وصف الله بـ﴿الْحَكِيمُ﴾ تسبيح المخلوقات في مطلع الحديد؟","answer":"لأن التسبيح يقر بخضوع الكون لتدبير لا خلل فيه؛ فالحكيم يضع كل شيء موضعه، وتصدر أفعاله عن علم وإحكام لا عن عبث أو مصادفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص586، تحت عنوان «سر اختيار وصف ﴿الحكيم﴾»","url":""}]},{"id":"s57-4","number":4,"surah":57,"verses":[18],"references":[{"surah":57,"verses":[18]}],"verseLabel":"الحديد: 18","question":"ما الذي تضيفه قراءتا ﴿الْمُصَّدِّقِينَ وَالْمُصَّدِّقَاتِ﴾ إلى معنى الآية؟","answer":"قراءة التشديد تعني المتصدقين والمتصدقات، فتبرز بذل المال؛ وقراءة التخفيف تعني المصدقين والمصدقات، فتبرز صدق الإيمان. وتتكامل القراءتان في وصل الاعتقاد بالعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص96–97، تحت عنوان «أثر اختلاف القراءات في قوله: ﴿المصدقين والمصدقات﴾»","url":""}]},{"id":"s57-5","number":5,"surah":57,"verses":[21],"references":[{"surah":57,"verses":[21]}],"verseLabel":"الحديد: 21","question":"ماذا يصور تشبيه عرض الجنة بعرض السماء والأرض؟","answer":"يقرب إلى الذهن سعة الجنة الهائلة بما يشاهده الإنسان من امتداد السماء والأرض، من غير أن يحصرها في قياس تدركه الأبصار.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص183، تحت عنوان «دلالة تشبيه عرض الجنة بمجموع عرضي السماء والأرض»","url":""}]},{"id":"s57-31","number":31,"surah":57,"verses":[21],"references":[{"surah":57,"verses":[21]}],"verseLabel":"الحديد: 21","question":"لماذا أُفردت ﴿السَّمَاءُ﴾ في وصف عرض الجنة؟","answer":"لأن المفرد قد يراد به جنس السماوات كلها، فيجمع الإيجاز بين العموم والعظمة، ويبقي الصورة حاضرة في الذهن بلا تعداد.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص184، تحت عنوان «سر إفراد ﴿السماء﴾ دون جمعها»","url":""}]},{"id":"s57-6","number":6,"surah":57,"verses":[1,29],"references":[{"surah":57,"verses":[1,29]}],"verseLabel":"الحديد: 29، المجادلة 1","question":"كيف يكشف افتتاح المجادلة بسماع شكوى امرأة معنى فضل الله في ختام الحديد؟","answer":"ختمت الحديد بأن الفضل بيد الله، ثم جاء سماع شكوى امرأة وإنزال حكم يفرج عنها مثالًا حيًا لهذا الفضل ولإحاطة علم الله ومعيته بعباده.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص398–399، تحت عنوان «مناسبة السورة لما قبلها»","url":""}]},{"id":"s57-7","number":7,"surah":57,"verses":[2],"references":[{"surah":57,"verses":[2]}],"verseLabel":"الحديد: 2","question":"لماذا ذُكر الإحياء والإماتة بعد ملك السماوات والأرض؟","answer":"لبيان أن ملك الله تصرف نافذ لا اسم مجرد؛ فمن أعظم آثاره إنشاء الحياة وإنهاؤها، وهما دليلان على كمال السلطان والقدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص594، تحت عنوان «موقع جملة ﴿يحيي ويميت﴾ مما قبلها ودلالته»","url":""}]},{"id":"s57-8","number":8,"surah":57,"verses":[3],"references":[{"surah":57,"verses":[3]}],"verseLabel":"الحديد: 3","question":"ما الذي يجمعه قوله ﴿الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ﴾ من معاني الكمال؟","answer":"يقرر أن الله الأول بلا ابتداء، والآخر بلا انتهاء، والظاهر بآياته وقهره، والباطن الذي لا تحيط به الأبصار ويحيط بالخفايا؛ فيستوعب كمال الوجود والعلم والقدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص602–603، تحت عنوان «بلاغة التعبير بأسلوب الطباق»","url":""}]},{"id":"s57-32","number":32,"surah":57,"verses":[3],"references":[{"surah":57,"verses":[3]}],"verseLabel":"الحديد: 3","question":"لماذا رُتبت أسماء الله: الأول والآخر والظاهر والباطن بهذا النسق؟","answer":"بدأ بمراتب الوجود زمانًا، ثم انتقل إلى الإحاطة ظهورًا وخفاءً؛ فكل اسم يقابله ما يتم به المعنى، ويتتابع النسق ليحيط القلب بجلال الله من كل وجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص604، تحت عنوان «بلاغة ترتيب أسمائه سبحانه في الآية، وسر اقترانها»","url":""}]},{"id":"s57-10","number":10,"surah":57,"verses":[4],"references":[{"surah":57,"verses":[4]}],"verseLabel":"الحديد: 4","question":"كيف تكون معية الله لعباده في قوله ﴿وَهُوَ مَعَكُمْ أَيْنَ مَا كُنْتُمْ﴾؟","answer":"هي معية تليق بالله، معناها إحاطة علمه وقدرته وسلطانه بأحوالهم أينما كانوا، لا حلولًا في مكان؛ فتورث المراقبة والطمأنينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص626، تحت عنوان «بلاغة التعبير بالمعية ﴿معكم﴾»","url":""}]},{"id":"s57-12","number":12,"surah":57,"verses":[7],"references":[{"surah":57,"verses":[7]}],"verseLabel":"الحديد: 7","question":"ما سرّ التعبير في قول ﴿مِمَّا جَعَلَكُمْ مُسْتَخْلَفِينَ فِيهِ﴾ بدل «من أموالكم»؟","answer":"المال ليس ملكًا ذاتيًا مستقلًا للإنسان، بل هو مال الله جعله في يده مدة وأمره بحسن التصرف فيه. والاستخلاف يذكره أيضًا بأنه خلف غيره وسيخلفه غيره؛ فيخف تعلقه بالمال ويسهل عليه الإنفاق في طاعة مالكه الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص662–663، تحت عنوان «بلاغة التعبير بالمجاز في قوله: ﴿مستخلفين﴾»","url":""}]},{"id":"s57-13","number":13,"surah":57,"verses":[8],"references":[{"surah":57,"verses":[8]}],"verseLabel":"الحديد: 8","question":"ما غرض السؤال ﴿وَمَا لَكُمْ لَا تُؤْمِنُونَ بِاللَّهِ﴾؟","answer":"هو توبيخ وتعجيب من ترك الإيمان بعد قيام حجته؛ فليس سؤالًا يطلب جوابًا، بل يهز النفس لتفتش عما بقي من عذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص671–672، تحت عنوان «الغرض من التعبير بالاستفهام بـ (ما) في قوله: ﴿وما لكم﴾»","url":""}]},{"id":"s57-33","number":33,"surah":57,"verses":[8],"references":[{"surah":57,"verses":[8]}],"verseLabel":"الحديد: 8","question":"لماذا ذُكرت دعوة الرسول في أثناء عتابهم على ترك الإيمان؟","answer":"لأن دعوته قائمة واضحة تقطع الشبهة وتكشف أن الإعراض ليس لنقص البيان؛ فالرسول بين أظهرهم يتلو آيات الله ويدعوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص674، تحت عنوان «بلاغة التعبير بالجملة الحالية في قوله: ﴿والرسول يدعوكم لتؤمنوا بربكم﴾»","url":""}]},{"id":"s57-34","number":34,"surah":57,"verses":[8],"references":[{"surah":57,"verses":[8]}],"verseLabel":"الحديد: 8","question":"ماذا يضيف قوله ﴿وَقَدْ أَخَذَ مِيثَاقَكُمْ﴾ إلى عتابهم؟","answer":"يضيف حجة سابقة مؤكدة: فقد أخذ الله عليهم العهد، فصار الإعراض بعد الدعوة والميثاق أشد قبحًا وأبعد عن العذر.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص677، تحت عنوان «سر التقييد بالجملة الحالية ﴿وقد أخذ ميثاقكم﴾»","url":""}]},{"id":"s57-14","number":14,"surah":57,"verses":[10],"references":[{"surah":57,"verses":[10]}],"verseLabel":"الحديد: 10","question":"لماذا كان الإنفاق والقتال قبل الفتح أعظم درجة؟","answer":"لأنهما وقعا في زمن شدة وقلة ناصر، فكان السبق إليهما أدل على قوة اليقين وصدق الإيمان وأعظم أثرًا في نصرة الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص713، تحت عنوان «سر تقييد الفعلين ﴿أنفق﴾ و(قاتل) بقوله: ﴿من قبل﴾»","url":""}]},{"id":"s57-15","number":15,"surah":57,"verses":[11],"references":[{"surah":57,"verses":[11]}],"verseLabel":"الحديد: 11","question":"ماذا يفيد التعبير عن القرض لله بالفعل المضارع ﴿يُقْرِضُ﴾؟","answer":"يفيد تجدد باب الإنفاق واستمراره؛ فكأن الدعوة مفتوحة في كل وقت لمن يبذل ماله مخلصًا، مع وعده بعوض مضاعف لا ينقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص730، تحت عنوان «دلالة التعبير بالفعل ﴿يقرض﴾ مادة وصيغة، وسر استعارته»","url":""}]},{"id":"s57-16","number":16,"surah":57,"verses":[12],"references":[{"surah":57,"verses":[12]}],"verseLabel":"الحديد: 12","question":"لماذا قُدِّم نور المؤمنين بين أيديهم على نور أيمانهم؟","answer":"لأن ما بين الأيدي موضع الطريق والسير، فنورهم أمامهم يهديهم، ثم ذكر الأيمان لما فيها من اليمن والتشريف وأخذ الكتب بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص751–752، تحت عنوان «سر تقديم الأيدي على الأيمان»","url":""}]},{"id":"s57-35","number":35,"surah":57,"verses":[12],"references":[{"surah":57,"verses":[12]}],"verseLabel":"الحديد: 12","question":"هل يقتصر نور المؤمنين على ما بين أيديهم وأيمانهم؟","answer":"لا يلزم الحصر؛ فقد خُصت الجهتان لأنهما أشرف الجهات وأوضحها في مشهد المسير والكرامة، ويجوز أن يعم النور سائر جوانبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص752–753، تحت عنوان «دلالة تخصيص الجمع بين الأيدي والأيمان»","url":""}]},{"id":"s57-17","number":17,"surah":57,"verses":[13],"references":[{"surah":57,"verses":[13]}],"verseLabel":"الحديد: 13","question":"ما المقصود بالأمر للمنافقين ﴿ارْجِعُوا وَرَاءَكُمْ﴾؟","answer":"هو تهكم وتيئيس: ارجعوا إلى الدنيا حيث كان سبب النور الإيمان والعمل، وقد فات زمن الاكتساب؛ أو ارجعوا إلى موضع قسمة النور، ولن يجدوا شيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص780–781، تحت عنوان «دلالة الأمر في قوله: ﴿ارجعوا﴾»","url":""}]},{"id":"s57-36","number":36,"surah":57,"verses":[13],"references":[{"surah":57,"verses":[13]}],"verseLabel":"الحديد: 13","question":"لماذا قيل للمنافقين ﴿فَالْتَمِسُوا نُورًا﴾ وهم يعلمون أنه مفقود؟","answer":"لإبراز خيبة أملهم؛ فطلب النور بعد انقضاء زمن العمل تهكم يوقظ حسرتهم ويكشف أن مجرد مصاحبة المؤمنين لم تمنحهم إيمانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص785، تحت عنوان «دلالة الأمر بالرجوع والتماس النور المفقود»","url":""}]},{"id":"s57-18","number":18,"surah":57,"verses":[13],"references":[{"surah":57,"verses":[13]}],"verseLabel":"الحديد: 13","question":"لماذا نُص على وجود باب في السور الفاصل بين المؤمنين والمنافقين؟","answer":"ليزيد حسرة المنافقين؛ يرون الرحمة وراء باب قريب ولا يملكون دخوله، وليبين أن طريق الجنة واحد لا يفتح إلا بإذن الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص791، تحت عنوان «دلالة التنصيص على وجود باب في السور»","url":""}]},{"id":"s57-37","number":37,"surah":57,"verses":[13],"references":[{"surah":57,"verses":[13]}],"verseLabel":"الحديد: 13","question":"ماذا يمثل السور المضروب بين المؤمنين والمنافقين؟","answer":"يمثل الفصل الحقيقي بين مصيرين بعد أن تشابه الفريقان ظاهرًا في الدنيا؛ نور ونعيم للمؤمنين، وظلمة وعذاب للمنافقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص792، تحت عنوان «بلاغة التمثيل في قوله: ﴿فضرب بينهم بسور﴾ الآية»","url":""}]},{"id":"s57-38","number":38,"surah":57,"verses":[13],"references":[{"surah":57,"verses":[13]}],"verseLabel":"الحديد: 13","question":"ما أثر المقابلة بين ﴿بَاطِنُهُ﴾ و﴿ظَاهِرُهُ﴾ في وصف السور؟","answer":"تبرز التناقض الحاد بين الرحمة والعذاب في مشهد واحد، وتكشف الفرق بين باطن الإيمان وباطن النفاق الذي ستره ظاهر الصحبة في الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج59، ص795، تحت عنوان «بلاغة الطباق بين قوله: ﴿باطنه﴾ و﴿ظاهره﴾»","url":""}]},{"id":"s57-19","number":19,"surah":57,"verses":[16],"references":[{"surah":57,"verses":[16]}],"verseLabel":"الحديد: 16","question":"ما الذي يوقظه السؤال ﴿أَلَمْ يَأْنِ لِلَّذِينَ آمَنُوا﴾؟","answer":"يوقظ الهمم بعتاب مؤثر: لقد حان وقت الخشوع فلا يليق بالمؤمن تأخيره، والاستفهام يقرع الوجدان من غير انتظار جواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص55، تحت عنوان «دلالة التعبير بأسلوب الاستفهام ﴿ألم يأن﴾»","url":""}]},{"id":"s57-39","number":39,"surah":57,"verses":[16],"references":[{"surah":57,"verses":[16]}],"verseLabel":"الحديد: 16","question":"لماذا أُسند الخشوع إلى القلوب؟","answer":"لأن القلب مركز الإيمان والتأثر، فإذا خشع انقادت الجوارح، والمطلوب خشوع داخلي صادق لا مجرد صمت الأصوات أو مظهر عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص60، تحت عنوان «سر إسناد الخشوع إلى (القلوب)»","url":""}]},{"id":"s57-20","number":20,"surah":57,"verses":[16],"references":[{"surah":57,"verses":[16]}],"verseLabel":"الحديد: 16","question":"كيف أفضى طول الأمد بأهل الكتاب إلى قسوة القلوب؟","answer":"طال عليهم الزمن مع الغفلة وترك تجديد الصلة بالوحي، فضعف أثر الذكر ثم ثبتت القسوة في قلوبهم؛ فالسبب ليس الزمن وحده بل ما صحبه من إعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص70–72، تحت عنوان «نوع الفاء في قوله: ﴿فقست﴾، ودلالتها»","url":""}]},{"id":"s57-21","number":21,"surah":57,"verses":[17],"references":[{"surah":57,"verses":[17]}],"verseLabel":"الحديد: 17","question":"كيف يفتح إحياء الأرض باب الرجاء بعد الحديث عن قسوة القلوب؟","answer":"كما يحيي الله الأرض اليابسة بالمطر، يحيي القلب القاسي بالذكر والوحي؛ فالمشهد دليل قدرة وتشجيع على التوبة بعد اليأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص83–84، تحت عنوان «دلالة ارتباط إحياء الأرض بذكر الله في الآية السابقة»","url":""}]},{"id":"s57-22","number":22,"surah":57,"verses":[20],"references":[{"surah":57,"verses":[20]}],"verseLabel":"الحديد: 20","question":"ما سرّ وصف الدنيا بأنها ﴿لَعِبٌ وَلَهْوٌ وَزِينَةٌ وَتَفَاخُرٌ... وَتَكَاثُرٌ﴾ بهذا الترتيب؟","answer":"يجري الترتيب مع أطوار التعلق بالدنيا: لعب في الصغر، ثم لهو، ثم عناية بالزينة، ثم تنافس في المكانة وكثرة المال والولد. فيختصر مسارًا طويلًا من الانشغال بالمظاهر، وينبه إلى قصره وسرعة انقضائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص143، تحت عنوان «بلاغة البدء باللعب والانتهاء بالتكاثر في الأموال والأولاد»","url":""}]},{"id":"s57-23","number":23,"surah":57,"verses":[20],"references":[{"surah":57,"verses":[20]}],"verseLabel":"الحديد: 20","question":"لماذا قيل ﴿ثُمَّ يَهِيجُ﴾ بعد نضرة النبات؟","answer":"لتصوير انتقاله بعد مدة من القوة والنضرة إلى الجفاف والذبول، فتفصل ثم بين مرحلتين وتستحضر تقلب الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص151، تحت عنوان «دلالة التعبير بـ﴿ثم﴾ دون الفاء في قوله: ﴿ثم يهيج﴾»","url":""}]},{"id":"s57-40","number":40,"surah":57,"verses":[20],"references":[{"surah":57,"verses":[20]}],"verseLabel":"الحديد: 20","question":"ماذا تفيد الفاء في قوله ﴿فَتَرَاهُ مُصْفَرًّا﴾؟","answer":"تفيد أن الاصفرار يعقب الهيجان ويظهر سريعًا للعين، فيرى الإنسان زوال البهجة رأي مشاهدة لا خبرًا بعيدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص152، تحت عنوان «دلالة التعبير بالفاء في قوله: ﴿فتراه﴾»","url":""}]},{"id":"s57-41","number":41,"surah":57,"verses":[20],"references":[{"surah":57,"verses":[20]}],"verseLabel":"الحديد: 20","question":"لماذا عادت ﴿ثُمَّ﴾ في قوله ﴿ثُمَّ يَكُونُ حُطَامًا﴾؟","answer":"لتصور مرحلة لاحقة يكتمل فيها تفتت النبات بعد اصفراره، فتتدرج الصورة من الذبول إلى الانكسار والحطام.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص154، تحت عنوان «دلالة العطف بـ﴿ثم﴾ دون الفاء»","url":""}]},{"id":"s57-24","number":24,"surah":57,"verses":[21],"references":[{"surah":57,"verses":[21]}],"verseLabel":"الحديد: 21","question":"إلى ماذا يتسابق المؤمنون في قوله ﴿سَابِقُوا﴾ مع حذف جهة السباق؟","answer":"حُذف المتعلَّق ليعم كل عمل صالح يسبق بهم إلى المغفرة والجنة؛ فلا يحصر السباق في عبادة واحدة، بل يشمل أبواب الخير كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص177، تحت عنوان «دلالة الحذف من جملة المسابقة»","url":""}]},{"id":"s57-25","number":25,"surah":57,"verses":[22],"references":[{"surah":57,"verses":[22]}],"verseLabel":"الحديد: 22","question":"لماذا جُمعت مصائب الأرض ومصائب الأنفس؟","answer":"لاستيعاب المصائب العامة الواقعة في العالم، كالجدب، والخاصة التي تمس الإنسان في صحته وأهله وحاله؛ فلا يخرج شيء منها عن تقدير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص203، تحت عنوان «دلالة الواو في قوله: ﴿ولا في أنفسكم﴾»","url":""}]},{"id":"s57-42","number":42,"surah":57,"verses":[22],"references":[{"surah":57,"verses":[22]}],"verseLabel":"الحديد: 22","question":"ماذا يصور قوله إن المصائب ﴿فِي كِتَابٍ﴾؟","answer":"يصور ثبوتها في علم الله وتقديره قبل وقوعها، فالكتاب اللوح المحفوظ، وفي التعبير طمأنينة بأن الحوادث ليست فوضى ولا مفاجأة لعلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص206، تحت عنوان «سر التعبير بـ﴿كتاب﴾»","url":""}]},{"id":"s57-43","number":43,"surah":57,"verses":[22],"references":[{"surah":57,"verses":[22]}],"verseLabel":"الحديد: 22","question":"ما الحكمة من معرفة أن المصائب والعطايا مقدرة؟","answer":"لكيلا يستولي الحزن على ما فات، ولا يتحول الفرح بالعطاء إلى بطر وفخر؛ فيعيش المؤمن بين الصبر والشكر والتسليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص217، تحت عنوان «دلالة التعبير باللام في قوله: ﴿لكيلا﴾»","url":""}]},{"id":"s57-26","number":26,"surah":57,"verses":[23],"references":[{"surah":57,"verses":[23]}],"verseLabel":"الحديد: 23","question":"لماذا قيل ﴿بِمَا آتَاكُمْ﴾ بدل «أعطاكم»؟","answer":"لأن الإيتاء أوسع من مجرد التمليك، فيشمل كل ما وصل إلى العبد من فضل الله، ويذكره بجلالة مصدر النعمة فلا يبطر بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص222، تحت عنوان «دلالة التعبير بـ﴿آتاكم﴾»","url":""}]},{"id":"s57-44","number":44,"surah":57,"verses":[23],"references":[{"surah":57,"verses":[23]}],"verseLabel":"الحديد: 23","question":"ماذا يفيد مجيء ﴿آتَاكُمْ﴾ بصيغة الماضي؟","answer":"يفيد تحقق العطاء وثبوته، لا الوعد به، فيكون الفرح المذموم بما حصل فعلًا وكأن صاحبه يراه استحقاقًا ذاتيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص222، تحت عنوان «دلالة التعبير بالفعل ﴿آتاكم﴾ ماضيًا»","url":""}]},{"id":"s57-27","number":27,"surah":57,"verses":[25],"references":[{"surah":57,"verses":[25]}],"verseLabel":"الحديد: 25","question":"لماذا قرن إنزال الكتاب والميزان بإنزال الحديد؟","answer":"تجتمع الثلاثة في إقامة القسط: الكتاب يبين الحق ويهدي إليه، والميزان معيار العدل في التعامل، والحديد قوة تحمي العدل وترد العدوان. فالهداية والإنصاف يحتاجان إلى ما يصونهما، كما تحتاج القوة إلى هداية تضبط استعمالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص271–272، تحت عنوان «وجه المناسبة بين ﴿الكتاب﴾ و﴿الميزان﴾ و﴿الحديد﴾»","url":""}]},{"id":"s57-28","number":28,"surah":57,"verses":[25],"references":[{"surah":57,"verses":[25]}],"verseLabel":"الحديد: 25","question":"لماذا قُدِّم بأس الحديد على منافعه للناس؟","answer":"لأن السياق يتحدث عن الرسل والبينات وإقامة القسط، وقد يحتاج الحق أمام العناد إلى قوة تحميه وتردع المعتدي؛ فناسب تقديم البأس، ثم ذُكرت المنافع لتكتمل صورة الحديد أداةً للحماية والعمران.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص276، تحت عنوان «سر تقديم البأس على المنافع»","url":""}]},{"id":"s57-45","number":45,"surah":57,"verses":[25],"references":[{"surah":57,"verses":[25]}],"verseLabel":"الحديد: 25","question":"ماذا يوحي تنكير ﴿مَنَافِعُ﴾ الحديد وجمعها؟","answer":"يوحي بأن منافعه كثيرة متنوعة لا تحصى ولا تنحصر في وجه واحد؛ فهي تمتد من أدوات الحماية إلى الزراعة والبناء والصناعة وسائر مصالح الحياة، ولذلك جاء اللفظ جمعًا منكرًا يفتح مجال الاتساع.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص276، تحت عنوان «نكتة تنكير (منافع) وجمعه»","url":""}]},{"id":"s57-29","number":29,"surah":57,"verses":[27],"references":[{"surah":57,"verses":[27]}],"verseLabel":"الحديد: 27","question":"ماذا يقرر قوله عن الرهبانية ﴿مَا كَتَبْنَاهَا عَلَيْهِمْ﴾؟","answer":"يقرر أن الله لم يفرضها عليهم في أصل الشريعة، بل ابتدعوها من عند أنفسهم. فالدين لا يثبت بمجرد استحسان البشر، ولو كان الدافع حسنًا، وإنما مرد التشريع إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص330، تحت عنوان «دلالة نفي الكتابة في قوله: ﴿ما كتبناها﴾»","url":""}]},{"id":"s57-46","number":46,"surah":57,"verses":[27],"references":[{"surah":57,"verses":[27]}],"verseLabel":"الحديد: 27","question":"كيف نُفي فرض الرهبانية ثم قيل ﴿إِلَّا ابْتِغَاءَ رِضْوَانِ اللَّهِ﴾؟","answer":"المعنى أنهم أحدثوها طلبًا لرضوان الله، لا أن الله شرعها لهم؛ ويحتمل أن المراد أنه لم يكتب عليهم إلا ما أوجبوه على أنفسهم ابتغاء الرضوان. وفي الوجهين يظهر أن حسن القصد لا يجعل الابتداع تشريعًا إلهيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص331–332، تحت عنوان «دلالة الاستثناء بـ﴿إلا﴾»","url":""}]},{"id":"s57-47","number":47,"surah":57,"verses":[27],"references":[{"surah":57,"verses":[27]}],"verseLabel":"الحديد: 27","question":"ماذا يضيف وصف الرعاية بأنها ﴿حَقَّ رِعَايَتِهَا﴾؟","answer":"يبين أن التقصير لم يكن هفوة يسيرة، بل إخلالًا بما التزموه من رعاية تامة صادقة؛ فالتعبير يحمّلهم مسؤولية الوفاء الكامل ويكشف أن الدعوى لا تغني من العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص336، تحت عنوان «دلالة التقييد بقوله: ﴿حق رعايتها﴾»","url":""}]},{"id":"s57-30","number":30,"surah":57,"verses":[28],"references":[{"surah":57,"verses":[28]}],"verseLabel":"الحديد: 28","question":"لماذا قيل ﴿نُورًا تَمْشُونَ بِهِ﴾ لا «تمشون فيه»؟","answer":"لأن الباء تجعل النور أداةً يستعينون بها ورفيقًا ملازمًا لسيرهم، لا مجرد مكان يحيط بهم؛ فيصحبهم نور الإيمان في الدنيا ونور النجاة في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص364، تحت عنوان «دلالة تعدية ﴿تمشون﴾ بالباء دون (في)»","url":""}]},{"id":"s57-48","number":48,"surah":57,"verses":[28],"references":[{"surah":57,"verses":[28]}],"verseLabel":"الحديد: 28","question":"ما الصورة التي يرسمها قوله ﴿نُورًا تَمْشُونَ بِهِ﴾؟","answer":"يمثل المؤمن بمسافر يسير في طريق خطر ومعه نور يكشف العوائق ويهديه إلى الغاية؛ فتصير الهداية نورًا محسوسًا، والطاعة مشيًا ثابتًا، ويقابلها الضلال كالتخبط في الظلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص365، تحت عنوان «بلاغة التمثيل في قوله: ﴿ويجعل لكم نورًا تمشون به﴾»","url":""}]},{"id":"s58-1","number":1,"surah":58,"verses":[1],"references":[{"surah":58,"verses":[1]}],"verseLabel":"المجادلة: 1","question":"ماذا تفيد ﴿قَدْ﴾ في افتتاح السورة: ﴿قَدْ سَمِعَ اللَّهُ﴾؟","answer":"تحقق وقوع السماع وتؤكد أن شكوى المرأة قد بلغت ربها وأجيب عنها، فتفتتح السورة بتطمين المظلوم أن صوته لم يضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص402، تحت عنوان «دلالة ﴿قد﴾ في ﴿قد سمع الله﴾»","url":""}]},{"id":"s58-28","number":28,"surah":58,"verses":[1],"references":[{"surah":58,"verses":[1]}],"verseLabel":"المجادلة: 1","question":"لماذا افتتحت السورة بسماع الله للشكوى لا بمجرد علمه بها؟","answer":"لأن السماع يستحضر قرب الإجابة والعناية بالكلام المرفوع، وهو أبلغ في تسلية المشتكية من الإخبار المجرد بأن الله يعلم حالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص402، تحت عنوان «بلاغة المجاز في لفظ السماع»","url":""}]},{"id":"s58-2","number":2,"surah":58,"verses":[6,7],"references":[{"surah":58,"verses":[6,7]}],"verseLabel":"المجادلة: 6–7","question":"لماذا عُطف الإنباء بالأعمال أولًا بالفاء في ﴿فَيُنَبِّئُهُمْ﴾؟","answer":"للدلالة على سرعة مواجهتهم بأعمالهم عند البعث، فلا فاصل يضيع فيه شيء مما أحصاه الله عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص461، تحت عنوان «دلالة العطف بالفاء في ﴿فينبئهم﴾»","url":""}]},{"id":"s58-29","number":29,"surah":58,"verses":[6,7],"references":[{"surah":58,"verses":[6,7]}],"verseLabel":"المجادلة: 6–7","question":"لماذا عُطف الإنباء بالأعمال لاحقًا بـ﴿ثُمَّ﴾؟","answer":"لتصوير تراخي زمن الجزاء عن زمن النجوى والفعل، ثم حتمية الانتقال بعد المهلة إلى الإنباء والحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص479، تحت عنوان «سر العطف بـ﴿ثم﴾»","url":""}]},{"id":"s58-3","number":3,"surah":58,"verses":[7],"references":[{"surah":58,"verses":[7]}],"verseLabel":"المجادلة: 7","question":"لماذا خُصت نجوى الثلاثة والخمسة بالذكر؟","answer":"لأن الثلاثة أول عدد تتحقق فيه النجوى الجماعية، والخمسة تالية له من الأعداد الفردية التي يكثر اجتماع الناس عليها؛ وذكرهما مثالان يشملان ما بينهما وما بعدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص476، تحت عنوان «سر تخصيص الثلاثة والخمسة بالذكر»","url":""}]},{"id":"s58-30","number":30,"surah":58,"verses":[7],"references":[{"surah":58,"verses":[7]}],"verseLabel":"المجادلة: 7","question":"ماذا يضيف قوله: ﴿وَلَا أَدْنَى مِنْ ذَلِكَ وَلَا أَكْثَرَ﴾ بعد الثلاثة والخمسة؟","answer":"يرفع توهم الاختصاص بالعددين ويعم كل اجتماع، صغيرًا كان أو كبيرًا، تحت علم الله ومعيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص477، تحت عنوان «بلاغة عطف ﴿ولا أكثر﴾»","url":""}]},{"id":"s58-4","number":4,"surah":58,"verses":[12,13],"references":[{"surah":58,"verses":[12,13]}],"verseLabel":"المجادلة: 12–13","question":"لماذا قيل في العجز عن صدقة النجوى: ﴿فَإِنْ لَمْ تَجِدُوا﴾ بـ﴿إن﴾؟","answer":"لأن عدم الوجدان أمر محتمل لا واقع في كل مخاطب، فناسبته أداة الشرط التي لا تجزم بوقوع الحالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص552، تحت عنوان «علة إيثار (إن) على (إذا)»","url":""}]},{"id":"s58-31","number":31,"surah":58,"verses":[12,13],"references":[{"surah":58,"verses":[12,13]}],"verseLabel":"المجادلة: 12–13","question":"لماذا قيل بعد ذلك: ﴿فَإِذْ لَمْ تَفْعَلُوا﴾ بـ﴿إذ﴾؟","answer":"لأن تركهم تقديم الصدقة صار أمرًا واقعًا معلومًا، فجيء بـ﴿إذ﴾ التي تستحضر الحدث المتحقق وتبني عليه رفع الحكم والتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص558، تحت عنوان «دلالة (إذ) في ﴿فإذ لم تفعلوا﴾»","url":""}]},{"id":"s58-5","number":5,"surah":58,"verses":[12],"references":[{"surah":58,"verses":[12]}],"verseLabel":"المجادلة: 12","question":"لماذا أُشير إلى صدقة النجوى باسم البعيد في ﴿ذَلِكَ خَيْرٌ لَكُمْ﴾؟","answer":"لتعظيم شأن هذا الأدب ورفع منزلته، مع أنه ذُكر قريبًا؛ فالبعد هنا بعد رتبة لا بعد مسافة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص550، تحت عنوان «نكتة إيثار اسم الإشارة للبعيد ﴿ذلك﴾»","url":""}]},{"id":"s58-32","number":32,"surah":58,"verses":[12],"references":[{"surah":58,"verses":[12]}],"verseLabel":"المجادلة: 12","question":"لماذا وُصفت صدقة النجوى بأنها ﴿خَيْرٌ لَكُمْ﴾؟","answer":"لأنها تطهر القلوب من الشح، وتميز حاجة المناجي الصادقة، وتدفع التزاحم على الرسول ﷺ؛ فهي خير ديني واجتماعي للمخاطبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص550، تحت عنوان «نكتة التعبير بالخيرية»","url":""}]},{"id":"s58-6","number":6,"surah":58,"verses":[22],"references":[{"surah":58,"verses":[22]}],"verseLabel":"المجادلة: 22","question":"لماذا عُطف إدخال الجنات على الإيمان والتأييد في ﴿وَيُدْخِلُهُمْ جَنَّاتٍ﴾؟","answer":"ليبين ثمرة ما أودع في قلوبهم من الإيمان وما أيدوا به من روح: جزاء أخروي يتمثل في دخول الجنات ودوام النعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص635–636، تحت عنوان «نكتة عطف ﴿ويدخلهم جنات﴾»","url":""}]},{"id":"s58-33","number":33,"surah":58,"verses":[22],"references":[{"surah":58,"verses":[22]}],"verseLabel":"المجادلة: 22","question":"لماذا جاء إدخالهم الجنات بالمضارع في ﴿وَيُدْخِلُهُمْ﴾؟","answer":"لاستحضار الوعد كأنه يقع أمام السامع، وللدلالة على تجدد دخول أفواج المؤمنين إلى الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص636، تحت عنوان «بلاغة التعبير بالمضارع في ﴿ويدخلهم﴾»","url":""}]},{"id":"s58-7","number":7,"surah":58,"verses":[1],"references":[{"surah":58,"verses":[1]}],"verseLabel":"المجادلة: 1","question":"ماذا تفيد ﴿فِي﴾ في قول المرأة: ﴿تُجَادِلُكَ فِي زَوْجِهَا﴾؟","answer":"تجعل الزوج وقضيته موضوع المحاورة، فهي لا تجادل خصومة معه بل تبحث في الحكم المتعلق بعلاقتها به.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص404، تحت عنوان «معنى ﴿في﴾ من قوله: ﴿في زوجها﴾»","url":""}]},{"id":"s58-34","number":34,"surah":58,"verses":[1],"references":[{"surah":58,"verses":[1]}],"verseLabel":"المجادلة: 1","question":"لماذا قيل: ﴿وَتَشْتَكِي إِلَى اللَّهِ﴾ بـ﴿إلى﴾؟","answer":"لأن الشكوى متجهة إلى الله طلبًا للفرج والحكم، فالحرف يصور انتهاء حاجتها ورجائها إلى من يملك كشفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص406، تحت عنوان «دلالة ﴿إلى﴾ في ﴿إلى الله﴾»","url":""}]},{"id":"s58-8","number":8,"surah":58,"verses":[1],"references":[{"surah":58,"verses":[1]}],"verseLabel":"المجادلة: 1","question":"ماذا تضيف صيغة التفاعل في ﴿تَحَاوُرَكُمَا﴾؟","answer":"تصور مراجعة الكلام بين المرأة والنبي ﷺ أخذًا وردًا، لا كلام طرف واحد؛ وفيها عناية الله بكل تفاصيل الحوار.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص408، تحت عنوان «نكتة صيغة التفاعل في ﴿تحاوركما﴾»","url":""}]},{"id":"s58-35","number":35,"surah":58,"verses":[1],"references":[{"surah":58,"verses":[1]}],"verseLabel":"المجادلة: 1","question":"لماذا جاء سماع الله لحوارهما بالمضارع في ﴿يَسْمَعُ﴾؟","answer":"ليدل على استمرار إحاطته بكل ما يتجدد من كلامهما، وليستحضر السامع قرب العناية الإلهية أثناء الحوار.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص408، تحت عنوان «بلاغة التعبير بالمضارع في ﴿يسمع﴾»","url":""}]},{"id":"s58-9","number":9,"surah":58,"verses":[1],"references":[{"surah":58,"verses":[1]}],"verseLabel":"المجادلة: 1","question":"لماذا جُمع بين اسمي الله ﴿سَمِيعٌ بَصِيرٌ﴾ في ختام آية الشكوى؟","answer":"ليقرر إحاطته بالكلام المسموع والحال المشاهد معًا؛ فقد سمع حوارها ورأى ما نزل بها، فلا يغيب عنه قول ولا حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص409، تحت عنوان «نكتة الجمع بين السمع والبصر»","url":""}]},{"id":"s58-36","number":36,"surah":58,"verses":[1],"references":[{"surah":58,"verses":[1]}],"verseLabel":"المجادلة: 1","question":"لماذا قُدِّم ﴿سَمِيعٌ﴾ على ﴿بَصِيرٌ﴾؟","answer":"لأن محور الآية شكوى منطوقة وحوار مسموع، فقدم الوصف الأنسب للسياق ثم ضم إليه البصر لتكتمل الإحاطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص409، تحت عنوان «غرض تقديم السمع على البصر»","url":""}]},{"id":"s58-10","number":10,"surah":58,"verses":[2],"references":[{"surah":58,"verses":[2]}],"verseLabel":"المجادلة: 2","question":"ما بلاغة نفي الأمومة في قوله: ﴿مَا هُنَّ أُمَّهَاتِهِمْ﴾؟","answer":"ينفي التشبيه الذي توهمه الظهار من أصله؛ فقول الرجل لا يحول الزوجة إلى أم، وبطلان المشبه به يهدم الحكم المتوهم كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص418، تحت عنوان «بلاغة التشبيه المنفي في ﴿ما هن أمهاتهم﴾»","url":""}]},{"id":"s58-11","number":11,"surah":58,"verses":[2],"references":[{"surah":58,"verses":[2]}],"verseLabel":"المجادلة: 2","question":"لماذا حُصرت الأمومة في قوله: ﴿إِنْ أُمَّهَاتُهُمْ إِلَّا اللَّائِي وَلَدْنَهُمْ﴾؟","answer":"لقطع كل ادعاء لفظي يجعل الزوجة أمًا؛ فالأمومة حقيقة ثابتة بالولادة لا تنشأ بكلمة ظهار.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص419، تحت عنوان «بلاغة القصر بالنفي والاستثناء»","url":""}]},{"id":"s58-12","number":12,"surah":58,"verses":[2],"references":[{"surah":58,"verses":[2]}],"verseLabel":"المجادلة: 2","question":"لماذا نُكِّر ﴿مُنْكَرًا﴾ في وصف الظهار؟","answer":"لتعظيم فظاعة هذا القول وبيان أنه منكر عظيم تنفر منه الفطرة والشرع، لا مجرد عبارة غير مستحسنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص421، تحت عنوان «بلاغة إيثار لفظ (المنكر) بصيغة التنكير»","url":""}]},{"id":"s58-37","number":37,"surah":58,"verses":[2],"references":[{"surah":58,"verses":[2]}],"verseLabel":"المجادلة: 2","question":"ماذا يضيف وصف الظهار بأنه ﴿زُورًا﴾ بعد كونه منكرًا؟","answer":"يبين أنه لا يجمع القبح فقط، بل الكذب أيضًا؛ فالزوجة ليست أمًا في الحقيقة، فاجتمع فساد القيمة وبطلان الخبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص422، تحت عنوان «بلاغة عطف ﴿وزورًا﴾»","url":""}]},{"id":"s58-13","number":13,"surah":58,"verses":[2],"references":[{"surah":58,"verses":[2]}],"verseLabel":"المجادلة: 2","question":"لماذا أعقب ذم الظهار بقوله: ﴿وَإِنَّ اللَّهَ لَعَفُوٌّ غَفُورٌ﴾؟","answer":"ليفتح باب التوبة بعد بيان فظاعة القول، ويطمئن من زلّ ثم رجع أن التشريع لا يقصد اليأس بل الإصلاح والتطهير.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص422–423، تحت عنوان «بلاغة عطف جملة ﴿وإن الله لعفو غفور﴾»","url":""}]},{"id":"s58-14","number":14,"surah":58,"verses":[3],"references":[{"surah":58,"verses":[3]}],"verseLabel":"المجادلة: 3","question":"لماذا عُطف الرجوع في الظهار بـ﴿ثُمَّ﴾ في ﴿ثُمَّ يَعُودُونَ﴾؟","answer":"لأن العودة تقع بعد مهلة من قول الظهار، وللتنبيه إلى استبعاد أن يرجع المرء إلى ما حرمه على نفسه بعد هذا القول الشنيع.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص430–431، تحت عنوان «سر العطف بـ﴿ثم﴾ في ﴿ثم يعودون﴾»","url":""}]},{"id":"s58-38","number":38,"surah":58,"verses":[3],"references":[{"surah":58,"verses":[3]}],"verseLabel":"المجادلة: 3","question":"لماذا عُبِّر عن إرادة استئناف الحياة الزوجية بلفظ ﴿يَعُودُونَ﴾؟","answer":"استعير العود للرجوع إلى المعاشرة التي قطعها الظهار؛ فكأن العلاقة كانت طريقًا تركه ثم أراد العودة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص431، تحت عنوان «بلاغة المجاز في لفظ العود»","url":""}]},{"id":"s58-15","number":15,"surah":58,"verses":[3,4],"references":[{"surah":58,"verses":[3,4]}],"verseLabel":"المجادلة: 3–4","question":"لماذا تكرر قيد ﴿مِنْ قَبْلِ أَنْ يَتَمَاسَّا﴾ في العتق والصيام؟","answer":"لتأكيد أن الكفارة مانع واجب قبل استئناف المعاشرة، وتكراره مع البدلين يمنع توهم اختلاف ترتيب الحكم بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص442، تحت عنوان «سر تكرار ﴿من قبل أن يتماسا﴾»","url":""}]},{"id":"s58-39","number":39,"surah":58,"verses":[3,4],"references":[{"surah":58,"verses":[3,4]}],"verseLabel":"المجادلة: 3–4","question":"لماذا لم يُذكر ﴿مِنْ قَبْلِ أَنْ يَتَمَاسَّا﴾ مع الإطعام؟","answer":"لأن الإطعام بديل عند العجز عن الصيام، وقد ثبت ترتيب المنع قبلُ في الأصل وبدله الأول؛ فحذفه هنا اتكال على ما تقدم وتخفيف في العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص443، تحت عنوان «سر عدم ذكر ﴿من قبل أن يتماسا﴾ مع الإطعام»","url":""}]},{"id":"s58-16","number":16,"surah":58,"verses":[5],"references":[{"surah":58,"verses":[5]}],"verseLabel":"المجادلة: 5","question":"لماذا قيل: ﴿يُحَادُّونَ اللَّهَ وَرَسُولَهُ﴾ دون «يعادون»؟","answer":"لأن المحادة تصور كل فريق في حد منفصل مقابل حد الآخر، فتجسد شدة المخالفة والانفصال عن منهج الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص453، تحت عنوان «سر التعبير بالمحادة دون غيرها»","url":""}]},{"id":"s58-40","number":40,"surah":58,"verses":[5],"references":[{"surah":58,"verses":[5]}],"verseLabel":"المجادلة: 5","question":"لماذا جاءت محادة الله ورسوله بالمضارع في ﴿يُحَادُّونَ﴾؟","answer":"لتصوير المخالفة سلوكًا متجددًا مستمرًا، لا موقفًا وقع وانتهى؛ فهم يكررون الوقوف في جانب الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص453، تحت عنوان «دلالة صيغة المضارع في ﴿يحادون﴾»","url":""}]},{"id":"s58-17","number":17,"surah":58,"verses":[5],"references":[{"surah":58,"verses":[5]}],"verseLabel":"المجادلة: 5","question":"لماذا عُبِّر عن هزيمة المحادين بقوله: ﴿كُبِتُوا﴾؟","answer":"لأن الكبت يجمع الإذلال والقهر ورد المعتدي بغيظه، فيصور سقوط قوتهم النفسية والظاهرة معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص454، تحت عنوان «بلاغة التعبير بالكبت»","url":""}]},{"id":"s58-41","number":41,"surah":58,"verses":[5],"references":[{"surah":58,"verses":[5]}],"verseLabel":"المجادلة: 5","question":"ماذا يضيف تشبيههم بالذين من قبلهم في ﴿كَمَا كُبِتَ الَّذِينَ مِنْ قَبْلِهِمْ﴾؟","answer":"يجعل مصيرهم سنة تاريخية مشاهدة؛ فكما أذل السابقون بسبب المحادة، يلحق اللاحقون بهم بلا استثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص454–455، تحت عنوان «دلالة التشبيه بالكاف»","url":""}]},{"id":"s58-18","number":18,"surah":58,"verses":[6],"references":[{"surah":58,"verses":[6]}],"verseLabel":"المجادلة: 6","question":"لماذا عُبِّر عن حفظ الأعمال بقوله: ﴿أَحْصَاهُ اللَّهُ﴾؟","answer":"شُبه علم الله المحيط بأعمالهم بإحصاء دقيق لا يفوته عدد ولا تفصيل، فيوقن السامع أن كل صغيرة محفوظة للحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص463، تحت عنوان «بلاغة المجاز بلفظ الإحصاء»","url":""}]},{"id":"s58-42","number":42,"surah":58,"verses":[6],"references":[{"surah":58,"verses":[6]}],"verseLabel":"المجادلة: 6","question":"ما دلالة الجمع بين ﴿أَحْصَاهُ اللَّهُ﴾ و﴿نَسُوهُ﴾؟","answer":"تقيم مقابلة بين ضعف ذاكرة البشر وكمال علم الله: ما أسقطوه من حسابهم بقي محفوظًا عنده وسيواجهون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص464، تحت عنوان «دلالة الواو في ﴿ونسوه﴾»","url":""}]},{"id":"s58-19","number":19,"surah":58,"verses":[7],"references":[{"surah":58,"verses":[7]}],"verseLabel":"المجادلة: 7","question":"ما معنى أن الله ﴿رَابِعُهُمْ﴾ و﴿سَادِسُهُمْ﴾ في النجوى؟","answer":"ليس دخوله في عدد أجسامهم، بل إحاطة علمه وسمعه بسرهم؛ فكل مجموعة يزيد عليها علم الله الحاضر الذي لا يخفى عليه حديثها.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص475، تحت عنوان «توجيه كونه تعالى ﴿رابعهم﴾ و﴿سادسهم﴾»","url":""}]},{"id":"s58-43","number":43,"surah":58,"verses":[7],"references":[{"surah":58,"verses":[7]}],"verseLabel":"المجادلة: 7","question":"ماذا يفيد قوله: ﴿أَيْنَ مَا كَانُوا﴾ بعد إثبات معية الله؟","answer":"يعم كل مكان يمكن أن يختبئوا فيه، فيقطع وهم أن البعد أو الخفاء يحجب نجواهم عن علم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص478، تحت عنوان «فائدة الظرف ﴿أين﴾»","url":""}]},{"id":"s58-20","number":20,"surah":58,"verses":[8],"references":[{"surah":58,"verses":[8]}],"verseLabel":"المجادلة: 8","question":"ما سرّ التعبير في قول ﴿ثُمَّ يَعُودُونَ لِمَا نُهُوا عَنْهُ﴾ بالمضارع؟","answer":"المضارع يصور العودة عادة متجددة، فلا يعرضها على أنها مخالفة عارضة انقضت. وفي استحضار المشهد تعجيب من قلة اكتراثهم بالنهي وإصرارهم على ما يفسد الجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص489، تحت عنوان «سر التعبير بالمضارع في ﴿يعودون﴾»","url":""}]},{"id":"s58-21","number":21,"surah":58,"verses":[8],"references":[{"surah":58,"verses":[8]}],"verseLabel":"المجادلة: 8","question":"لماذا وُصفت نجواهم أولًا بأنها ﴿بِالْإِثْمِ﴾؟","answer":"لأن الإثم اسم جامع للذنب الذي يضر صاحبه، فبدأ به ليقرر فساد أصل حديثهم وسوء طويتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص492، تحت عنوان «نكتة التعبير بالإثم»","url":""}]},{"id":"s58-44","number":44,"surah":58,"verses":[8],"references":[{"surah":58,"verses":[8]}],"verseLabel":"المجادلة: 8","question":"ماذا يضيف ﴿الْعُدْوَانِ﴾ بعد ﴿الْإِثْمِ﴾ في وصف النجوى؟","answer":"ينقل الذم من ذنب يعود ضرره عليهم إلى اعتداء يتجاوزهم فيؤذي الآخرين؛ فنجواهم فساد شخصي واجتماعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص492–493، تحت عنوان «نكتة عطف العدوان على الإثم»","url":""}]},{"id":"s58-45","number":45,"surah":58,"verses":[8],"references":[{"surah":58,"verses":[8]}],"verseLabel":"المجادلة: 8","question":"لماذا خُصت ﴿مَعْصِيَتِ الرَّسُولِ﴾ بعد الإثم والعدوان؟","answer":"لأنها أغلظ صور نجواهم وأشدها خطرًا على الجماعة، وفي تخصيصها تشنيع على تدبيرهم ما يخالف أمر الرسول ﷺ ويؤذيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص493، تحت عنوان «نكتة عطف ﴿ومعصيت الرسول﴾»","url":""}]},{"id":"s58-22","number":22,"surah":58,"verses":[8],"references":[{"surah":58,"verses":[8]}],"verseLabel":"المجادلة: 8","question":"كيف سمّى القرآن قول اليهود المؤذي للنبي ﷺ تحية؟","answer":"سمّاه تحية على سبيل كشف المفارقة والتهكم؛ فقد حرّفوا السلام إلى لفظ يوهم التحية ويضمر الدعاء بالموت، ففضح التعبير سوءهم مع إبقاء صورة الفعل الذي تظاهروا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص495، تحت عنوان «نكتة التعبير بالتحية»","url":""}]},{"id":"s58-46","number":46,"surah":58,"verses":[8],"references":[{"surah":58,"verses":[8]}],"verseLabel":"المجادلة: 8","question":"ماذا يفضح قوله ﴿بِمَا لَمْ يُحَيِّكَ بِهِ اللَّهُ﴾؟","answer":"يفضح أن تحيتهم لم تكن مجرد إساءة اجتماعية، بل مخالفة متعمدة لأدب شرعه الله وأمر به؛ فمن تجاوز التحية التي رضيها الله عرّض نفسه لسخطه.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص495–496، تحت عنوان «دلالة التعبير بالموصول وصلته في قوله: ﴿بما لم يحيك﴾»","url":""}]},{"id":"s58-23","number":23,"surah":58,"verses":[9],"references":[{"surah":58,"verses":[9]}],"verseLabel":"المجادلة: 9","question":"لماذا لم يكتف بالنهي عن نجوى الإثم، بل أمر بالنجوى بالبر والتقوى؟","answer":"لأن إصلاح المجتمع لا يكتمل بترك التآمر والعدوان، بل يحتاج أن تتحول المجالس الخفية نفسها إلى تشاور في الخير والإصلاح؛ فجمع السياق إزالة الشر وبناء البديل النافع.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص511، تحت عنوان «نكتة عطف ﴿وتناجوا بالبر والتقوى﴾»","url":""}]},{"id":"s58-47","number":47,"surah":58,"verses":[9],"references":[{"surah":58,"verses":[9]}],"verseLabel":"المجادلة: 9","question":"ماذا تضيف ﴿التَّقْوَى﴾ بعد الأمر بالتناجي بالبر؟","answer":"البر يشمل وجوه الخير الواسعة التي تنفع الناس، والتقوى تضيف رقابة القلب وخشيته لله؛ فيجتمع صلاح العمل الظاهر مع الدافع الباطن الذي يحفظه من الانحراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص512، تحت عنوان «نكتة عطف التقوى على البر»","url":""}]},{"id":"s58-24","number":24,"surah":58,"verses":[10],"references":[{"surah":58,"verses":[10]}],"verseLabel":"المجادلة: 10","question":"هل قوله ﴿إِنَّمَا النَّجْوَى مِنَ الشَّيْطَانِ﴾ يذم كل حديث سري؟","answer":"لا؛ التعريف يشير إلى النجوى المعهودة في السياق، وهي التناجي بالإثم والعدوان ومعصية الرسول. أما التشاور في الخير فمأمور به، وإنما ينسب إلى الشيطان ما كان وسيلة للشر والإفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص518، تحت عنوان «دلالة تعريف ﴿النجوى﴾»","url":""}]},{"id":"s58-48","number":48,"surah":58,"verses":[10],"references":[{"surah":58,"verses":[10]}],"verseLabel":"المجادلة: 10","question":"لماذا خُصَّ حزن المؤمنين غايةً للنجوى الشيطانية؟","answer":"لأن المتناجين قد لا يملكون إيقاع ضرر حقيقي، فيلجؤون إلى الإيهام والهمس ليوقعوا الريبة والخوف في قلوب المؤمنين؛ ففضح القرآن غايتهم النفسية حتى لا تستولي الحيلة على النفوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص519، تحت عنوان «سر تخصيص علة الحزن بالذكر»","url":""}]},{"id":"s58-49","number":49,"surah":58,"verses":[10],"references":[{"surah":58,"verses":[10]}],"verseLabel":"المجادلة: 10","question":"ماذا يقرر قوله إن النجوى لا تضر المؤمنين ﴿إِلَّا بِإِذْنِ اللَّهِ﴾؟","answer":"يقرر أن كيدها لا يستقل بإحداث شيء، وأن الضرر لا يقع في حال إلا بتقدير الله؛ فيقطع سلطان الوهم، ويدعو المؤمن إلى التوكل بدل الاستسلام للخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص521، تحت عنوان «بلاغة الحصر بالنفي والاستثناء»","url":""}]},{"id":"s58-25","number":25,"surah":58,"verses":[11],"references":[{"surah":58,"verses":[11]}],"verseLabel":"المجادلة: 11","question":"ماذا يطلب الأمر ﴿تَفَسَّحُوا فِي الْمَجَالِسِ﴾ وراء مجرد تحريك الأجساد؟","answer":"يطلب أن يتعمد المؤمن توسيع المكان لإخوانه بسماحة وكرم، فيزول التزاحم والضيق وتظهر المودة؛ فاللفظ يصور فسحة في الصدر قبل فسحة المجلس.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص532–533، تحت عنوان «بلاغة التعبير بالتفسح»","url":""}]},{"id":"s58-50","number":50,"surah":58,"verses":[11],"references":[{"surah":58,"verses":[11]}],"verseLabel":"المجادلة: 11","question":"لماذا عبّر عن القيام من المجلس بقوله ﴿انْشُزُوا﴾؟","answer":"لأن النشوز يدل على الارتفاع من موضع مستقر؛ فيحث على سرعة الاستجابة إذا دعت الحاجة إلى القيام، ويحوّل التنازل عن المكان إلى طاعة ترفع صاحبها عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص536، تحت عنوان «سر التعبير بالنشوز»","url":""}]},{"id":"s58-26","number":26,"surah":58,"verses":[11],"references":[{"surah":58,"verses":[11]}],"verseLabel":"المجادلة: 11","question":"ما الصورة في قوله ﴿يَرْفَعِ اللَّهُ الَّذِينَ آمَنُوا﴾؟","answer":"يصوّر علو المنزلة والكرامة كأنه ارتفاع حسي تراه العين؛ فمن ارتفع عن مكانه امتثالًا وتواضعًا رفعه الله في القدر والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص536–537، تحت عنوان «بلاغة الاستعارة في قوله: ﴿يرفع﴾»","url":""}]},{"id":"s58-51","number":51,"surah":58,"verses":[11],"references":[{"surah":58,"verses":[11]}],"verseLabel":"المجادلة: 11","question":"لماذا خُصَّ الذين أوتوا العلم بعد ذكر المؤمنين؟","answer":"لأن العلماء داخلون في المؤمنين، ثم خُصوا بالذكر تشريفًا وبيانًا لزيادة منزلتهم؛ فالإيمان يرفع، والعلم المصحوب به يفتح درجة أخرى من الفضل والعمل والتعليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص538، تحت عنوان «بلاغة عطف ﴿والذين أوتوا العلم﴾»","url":""}]},{"id":"s58-52","number":52,"surah":58,"verses":[11],"references":[{"surah":58,"verses":[11]}],"verseLabel":"المجادلة: 11","question":"ماذا يوحي جمع ﴿دَرَجَاتٍ﴾ وتنكيرها؟","answer":"يوحي بمراتب كثيرة عالية لا يحيط السامع بمقدارها، تتفاوت بحسب الإيمان والعلم والعمل؛ فالتنكير يعظمها والجمع يوسعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص540، تحت عنوان «غرض تنكير لفظ ﴿درجات﴾ وجمعه»","url":""}]},{"id":"s58-27","number":27,"surah":58,"verses":[19],"references":[{"surah":58,"verses":[19]}],"verseLabel":"المجادلة: 19","question":"ما النتيجة الأخطر لاستحواذ الشيطان عليهم في قوله ﴿فَأَنْسَاهُمْ ذِكْرَ اللَّهِ﴾؟","answer":"أن سيطرته لم تقف عند وسوسة عابرة، بل انتهت إلى طمس ذكر الله من قلوبهم وعقولهم؛ فالفاء تكشف أن الغفلة ثمرة مباشرة للتمادي في طاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص609، تحت عنوان «دلالة الفاء في ﴿فأنساهم﴾»","url":""}]},{"id":"s58-53","number":53,"surah":58,"verses":[19],"references":[{"surah":58,"verses":[19]}],"verseLabel":"المجادلة: 19","question":"لماذا سُمّي المنافقون ﴿حِزْبَ الشَّيْطَانِ﴾؟","answer":"لأن الحزب جماعة يجمعها قائد وغاية، وقد وحّدهم اتباع الشيطان ونصرة الباطل حتى صاروا كجنوده المنظمين؛ والاسم يفضح ولاءهم الحقيقي ومصيرهم معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص611، تحت عنوان «بلاغة التعبير بالحزب»","url":""}]},{"id":"s58-54","number":54,"surah":58,"verses":[19],"references":[{"surah":58,"verses":[19]}],"verseLabel":"المجادلة: 19","question":"لماذا صُوِّر مصير حزب الشيطان بالخسران؟","answer":"لأن الخسران في أصله ضياع رأس المال بعد انتظار الربح؛ وهؤلاء أضاعوا فطرتهم وأعمارهم ودينهم، فلم يفقدوا ربحًا عارضًا فحسب بل خسروا الأصل والمآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص613، تحت عنوان «بلاغة الاستعارة في لفظ الخسران»","url":""}]},{"id":"s59-1","number":1,"surah":59,"verses":[1],"references":[{"surah":59,"verses":[1]}],"verseLabel":"الحشر: 1","question":"ما سر تكرار «ما» في ﴿سبح لله ما في السماوات وما في الأرض﴾ في الحشر، بخلاف مطلع الحديد؟","answer":"في الحديد جُمعت الموجودات تحت موصول واحد لأن المقام للاستدلال بعموم الخلق على عظمة الله وصفاته. أما الحشر فتمهد لنعمة أرضية هي خذلان بني النضير، فخُص أهل الأرض بموصول ثانٍ لإبراز شأن هذه النعمة، مع شمول التسبيح للسماوات والأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص661–662، تحت عنوان «توجيه المتشابه اللفظي بين مطلعي سورة الحشر وسورة الحديد»","url":""}]},{"id":"s59-2","number":2,"surah":59,"verses":[2],"references":[{"surah":59,"verses":[2]}],"verseLabel":"الحشر: 2","question":"ما سرّ التعبير في قول ﴿هُوَ الَّذِي أَخْرَجَ الَّذِينَ كَفَرُوا﴾ ولم يسم بني النضير؟","answer":"عدل عن اسم بني النضير إلى الموصول وصلته لتشنيع صنيعهم وتسجيل وصف الكفر عليهم، والإيماء إلى أنه باعث الغدر والخيانة وسبب استحقاق الإخراج؛ فالتعبير يربط مصيرهم بعملهم، لا بمجرد انتسابهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص666، تحت عنوان «نكتة التعبير عن المفعول بالاسم الموصول»","url":""}]},{"id":"s59-3","number":3,"surah":59,"verses":[2],"references":[{"surah":59,"verses":[2]}],"verseLabel":"الحشر: 2","question":"لماذا قيل عن إخراج بني النضير: ﴿لِأَوَّلِ الْحَشْرِ﴾؟","answer":"لأنه كان أول إخراج جماعي لهم من جزيرة العرب، وفي وصفه بالأول إشعار بأن وراءه حشرًا آخر؛ فالكلمة لا تسجل الواقعة وحدها، بل تفتح أفق ما سيأتي بعدها من إجلاء وحشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص669، تحت عنوان «وجه التعبير بقوله: ﴿أول﴾»","url":""}]},{"id":"s59-4","number":4,"surah":59,"verses":[2],"references":[{"surah":59,"verses":[2]}],"verseLabel":"الحشر: 2","question":"ماذا تكشف مقابلة ظن المؤمنين بظن بني النضير في مطلع مشهد إخراجهم؟","answer":"تكشف انقلاب الموازين الذي أحدثه نصر الله: المؤمنون استبعدوا خروجهم لقوة حصونهم، وهم جزموا أن الحصون ستحميهم؛ ثم أبطل الواقع الظنين معًا، فظهر أن التقدير الإلهي يأتي من وراء حساب الطرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص672، تحت عنوان «بلاغة الطباق بين فعلي الظن»","url":""}]},{"id":"s59-5","number":5,"surah":59,"verses":[2],"references":[{"surah":59,"verses":[2]}],"verseLabel":"الحشر: 2","question":"ماذا يضيف نفي الاحتساب في قوله: ﴿فَأَتَاهُمُ اللَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا﴾؟","answer":"يصور مباغتة التدبير الإلهي لهم من جهة لم تدخل أصلًا في حسابهم؛ فقد حصّنوا ما توقعوا أن يأتيهم منه الخطر، فجاء انهيارهم من داخل النفوس حين قذف الله الرعب في قلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص677، تحت عنوان «دلالة التعبير بفعل الاحتساب منفيًا»","url":""}]},{"id":"s59-23","number":23,"surah":59,"verses":[2],"references":[{"surah":59,"verses":[2]}],"verseLabel":"الحشر: 2","question":"ما الصورة التي يرسمها قوله: ﴿فَأَتَاهُمُ اللَّهُ مِنْ حَيْثُ لَمْ يَحْتَسِبُوا﴾؟","answer":"يمثل حال نزول أمر الله وعقابه بهم بحال قوة تأتي المحاصَر من منفذ لم يراقبه، فتجاوز التعبير ذكر السبب المباشر إلى تصوير المفاجأة والإحاطة والعجز عن دفع القضاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص678، تحت عنوان «بلاغة الاستعارة التمثيلية»","url":""}]},{"id":"s59-6","number":6,"surah":59,"verses":[2],"references":[{"surah":59,"verses":[2]}],"verseLabel":"الحشر: 2","question":"لماذا قيل: ﴿يُخْرِبُونَ بُيُوتَهُمْ﴾ لا يهدمونها؟","answer":"لأن التخريب أوسع دلالة من مجرد إسقاط البناء؛ فهو إفساد للعمران وإخراج له عن الانتفاع، ويصور أنهم شاركوا بأيديهم في تحويل حصون ظنوها مصدر أمن إلى بيوت معطلة مهدمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص681، تحت عنوان «بلاغة استعمال مفردة ﴿يخربون﴾»","url":""}]},{"id":"s59-24","number":24,"surah":59,"verses":[2],"references":[{"surah":59,"verses":[2]}],"verseLabel":"الحشر: 2","question":"ماذا يكشف جمع ﴿بِأَيْدِيهِمْ وَأَيْدِي الْمُؤْمِنِينَ﴾ في تخريب البيوت؟","answer":"يكشف اشتراك الفريقين في النتيجة مع اختلاف القصد: كان اليهود ينقضون ما يمكن حمله أو يحرمون المسلمين الانتفاع به، وكان المؤمنون يفتحون الحصون ويزيلون موانعها؛ فاجتمعت الأيدي على إسقاط ما عُدَّ سببًا للمنعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص684، تحت عنوان «بلاغة العطف بالواو»","url":""}]},{"id":"s59-7","number":7,"surah":59,"verses":[2],"references":[{"surah":59,"verses":[2]}],"verseLabel":"الحشر: 2","question":"لماذا قيل: ﴿فَاعْتَبِرُوا﴾ ولم يقل: فاتعظوا؟","answer":"لأن الاعتبار عبور من الواقعة المشاهدة إلى حكم يتجاوزها؛ فيقيس الناظر أحواله على مصير من اغتروا بقوتهم، أما الاتعاظ فقد يقف عند التأثر العابر. فالمطلوب قراءة السنن لا مجرد الانفعال بالمشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص685، تحت عنوان «بلاغة استعمال مفردة الاعتبار دون الاتعاظ»","url":""}]},{"id":"s59-8","number":8,"surah":59,"verses":[3],"references":[{"surah":59,"verses":[3]}],"verseLabel":"الحشر: 3","question":"ما دلالة مقابلة العذاب في الدنيا بعذاب النار في الآخرة في الحشر: 3؟","answer":"المقابلة تبين أن عقابهم لا ينحصر في الدنيا. فجملة ﴿ولهم في الآخرة عذاب النار﴾ تحتاط من توهم أن الجلاء أو التعذيب الدنيوي بدل من عذاب الآخرة، وذكر النار يزيد تصوير شدته؛ فلكل من الدارين عذابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص697، تحت عنوان «بلاغة الطباق بين ﴿الدنيا﴾ و﴿الآخرة﴾»","url":""}]},{"id":"s59-9","number":9,"surah":59,"verses":[4],"references":[{"surah":59,"verses":[4]}],"verseLabel":"الحشر: 4","question":"ما دلالة التعبير بالمضارع في قوله ﴿ومن يشاق الله فإن الله شديد العقاب﴾؟","answer":"المضارع يستحضر تجدد المشاقة ويجعل الوعيد متوجهًا إلى كل من يستمر في عداوة الله ورسوله بعد معرفته ما حل ببني النضير؛ فليس المقصود حكاية ماضٍ انقضى وحده، بل التحذير من تجدد سببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص701، تحت عنوان «دلالة التعبير بالمضارع: ﴿يشاق﴾»","url":""}]},{"id":"s59-10","number":10,"surah":59,"verses":[5],"references":[{"surah":59,"verses":[5]}],"verseLabel":"الحشر: 5","question":"ما سرّ التعبير في قول ﴿مَا قَطَعْتُمْ مِنْ لِينَةٍ﴾ ولم يقل «نخلة»؟","answer":"تذكر الموسوعة في «اللينة» أوجهًا: النخل سوى بعض أنواعه، أو النخلة الكريمة، أو مطلق النخلة. فعلى تخصيصها بنوع يكون ذكرها أشد في تصوير ما أصابهم من غيظ بقطع نخيلهم، وعلى العموم يجري اللفظ على استعمال أهل المدينة؛ فلا يجزم الجواب بنوع واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص708–709، تحت عنوان «نكتة التعبير بـ﴿لينة﴾ نكرة»","url":""}]},{"id":"s59-11","number":11,"surah":59,"verses":[6],"references":[{"surah":59,"verses":[6]}],"verseLabel":"الحشر: 6","question":"لماذا عُبّر عن السعي بالخيل والركاب بـ﴿أَوْجَفْتُمْ﴾؟","answer":"لأن الإيجاف هو الإسراع الذي يجهد الدابة ويثير حركة الغزو؛ فنفيه ينفي عن المسلمين كلفة القتال والسعي العسكري، ويبين أن المال حصل بتسليط الله لا بقوة جيشهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص720، تحت عنوان «بلاغة التعبير بفعل الإيجاف دون غيره»","url":""}]},{"id":"s59-25","number":25,"surah":59,"verses":[6],"references":[{"surah":59,"verses":[6]}],"verseLabel":"الحشر: 6","question":"لماذا سُمّي مال بني النضير فيئًا لا غنيمة؟","answer":"لأنه آل إلى المسلمين من غير قتال ولا إيجاف، فكأنه رجع إلى الجهة التي تصرفه في مصالح الجماعة، بخلاف الغنيمة التي تُنال بالمواجهة ويكون للغانمين فيها نصيب مقرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص726–727، تحت عنوان «الفيء والغنيمة»","url":""}]},{"id":"s59-12","number":12,"surah":59,"verses":[7],"references":[{"surah":59,"verses":[7]}],"verseLabel":"الحشر: 7","question":"لماذا عُللت مصارف الفيء بقوله: ﴿كَيْ لَا يَكُونَ دُولَةً بَيْنَ الْأَغْنِيَاءِ مِنْكُمْ﴾؟","answer":"ليبين أن توزيع الفيء ليس قائمة عطاءات منفصلة، بل سياسة تمنع احتباس المال في دائرة الأقوياء؛ فالمقصد أن يتحرك المال في المجتمع وألا يزيد الغنى تركّزًا والفقر حرمانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص735، تحت عنوان «سر المجيء بالجملة التعليلية»","url":""}]},{"id":"s59-26","number":26,"surah":59,"verses":[7],"references":[{"surah":59,"verses":[7]}],"verseLabel":"الحشر: 7","question":"ماذا يفيد تنكير ﴿دُولَةً﴾ في تعليل توزيع الفيء؟","answer":"يفيد العموم؛ فيمنع أن يصير المال أيَّ صورة من صور التداول المحتكر بين الأغنياء، قليلة كانت أو كثيرة. فالحكم لا يعالج واقعة مخصوصة، بل يغلق كل طريق يعيد الثروة إلى الحلقة نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص737–738، تحت عنوان «دلالة استعمال مفردة ﴿دولة﴾ نكرة»","url":""}]},{"id":"s59-13","number":13,"surah":59,"verses":[7],"references":[{"surah":59,"verses":[7]}],"verseLabel":"الحشر: 7","question":"ماذا يحقق التقابل بين ﴿فَخُذُوهُ﴾ و﴿فَانْتَهُوا﴾؟","answer":"يجمع الطاعة من جهتيها: قبول ما يأتي به الرسول والعمل به، والكف عما يمنع منه. فليس الاتباع انتقاءً للأوامر المحبوبة، بل استجابة كاملة في الفعل والترك.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص741–742، تحت عنوان «بلاغة العطف بين الجمل المتقابلة»","url":""}]},{"id":"s59-14","number":14,"surah":59,"verses":[8,9],"references":[{"surah":59,"verses":[8,9]}],"verseLabel":"الحشر: 8–9","question":"كيف تبوأ الأنصار ﴿الدَّارَ وَالْإِيمَانَ﴾ مع أن الإيمان لا يُسكن؟","answer":"جُعل الإيمان كأنه منزل استقروا فيه وتمكنوا منه كما استقروا في المدينة؛ فالعطف يصور سبقهم إلى الإيمان وثباتهم فيه، ويجعل بيئتهم المكانية والروحية مأوى واحدًا استقبلوا منه المهاجرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص765، تحت عنوان «توجيه عطف ﴿والإيمان﴾ على ﴿الدار﴾»","url":""}]},{"id":"s59-15","number":15,"surah":59,"verses":[9],"references":[{"surah":59,"verses":[9]}],"verseLabel":"الحشر: 9","question":"ما الذي تكني عنه عبارة ﴿وَلَا يَجِدُونَ فِي صُدُورِهِمْ حَاجَةً مِمَّا أُوتُوا﴾؟","answer":"تكني عن نقاء الأنصار من الحسد والضيق حين خُص المهاجرون بالفيء؛ فنفى النص حتى الإحساس الباطن بالحاجة والحرج، لا مجرد الاعتراض الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص769، تحت عنوان «بلاغة الكناية في نفي الحاجة»","url":""}]},{"id":"s59-16","number":16,"surah":59,"verses":[9],"references":[{"surah":59,"verses":[9]}],"verseLabel":"الحشر: 9","question":"ماذا يكشف اختيار ﴿وَيُؤْثِرُونَ﴾ في وصف الأنصار؟","answer":"يكشف أنهم لا يعطون من الفاضل عن حاجتهم فحسب، بل يقدّمون غيرهم على أنفسهم عن قصد؛ وصيغة المضارع تصور الإيثار خلقًا متجددًا لا موقفًا عابرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص773، تحت عنوان «دلالة التعبير بـ﴿ويؤثرون﴾ مادة وصيغة»","url":""}]},{"id":"s59-27","number":27,"surah":59,"verses":[9],"references":[{"surah":59,"verses":[9]}],"verseLabel":"الحشر: 9","question":"لماذا سُميت حاجتهم ﴿خَصَاصَةً﴾؟","answer":"لأن أصل الخصاصة الفُرجة والخلل؛ فصورت الحاجة كأنها فجوة ظاهرة في معاشهم، ومع ذلك سدوا حاجة إخوانهم قبل حاجتهم. وهذا يجعل الإيثار أبلغ من مجرد الكرم مع السعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص777، تحت عنوان «بلاغة التعبير بمفردة ﴿خصاصة﴾ مادة وصيغة»","url":""}]},{"id":"s59-17","number":17,"surah":59,"verses":[9],"references":[{"surah":59,"verses":[9]}],"verseLabel":"الحشر: 9","question":"لماذا قيل: ﴿شُحَّ نَفْسِهِ﴾ لا بخل نفسه؟","answer":"لأن الشح أغلظ من البخل؛ فهو حرص داخلي شديد على المنع والاستئثار، وقد يدفع صاحبه إلى طلب ما ليس له، أما البخل فيظهر غالبًا في منع ما عنده. فالنجاة من الشح تحرير لمنبع السلوك قبل ظاهره.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص778، تحت عنوان «بلاغة التعبير بالـ﴿شح﴾»","url":""}]},{"id":"s59-18","number":18,"surah":59,"verses":[10],"references":[{"surah":59,"verses":[10]}],"verseLabel":"الحشر: 10","question":"لماذا بدأ اللاحقون بطلب المغفرة لأنفسهم قبل إخوانهم؟","answer":"لأن الداعي يبدأ بإصلاح نفسه والاعتراف بحاجته، فيكون أصدق دعاءً وأبعد عن تزكية الذات، ثم يوسع الرحمة لإخوانه. فالتقديم ترتيب أدب لا استئثار بالمغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص790–791، تحت عنوان «لطيفة تقديم الدعاء للنفس على الدعاء للآخرين»","url":""}]},{"id":"s59-28","number":28,"surah":59,"verses":[10],"references":[{"surah":59,"verses":[10]}],"verseLabel":"الحشر: 10","question":"لماذا وصف السابقون في الإيمان بأنهم ﴿إِخْوَانِنَا﴾؟","answer":"ليقرر أن رابطة الإيمان تتجاوز اختلاف الأزمنة والديار، وتجعل المؤمنين أمة واحدة يدعو لاحقها لسابقها. وفي الوصف أيضًا وفاء لأهل الفضل وتطهير للقلب من الغل عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج60، ص791، تحت عنوان «فائدة وصف المؤمنين السابقين بالإخوة»","url":""}]},{"id":"s59-19","number":19,"surah":59,"verses":[11],"references":[{"surah":59,"verses":[11]}],"verseLabel":"الحشر: 11","question":"لماذا سمّى القرآن يهود بني النضير إخوانًا للمنافقين؟","answer":"لأن الفريقين اجتمعا على الكفر برسالة النبي ﷺ وعداوة الإسلام والتناصر عليه؛ فهي أخوة ولاء ومصلحة لا أخوة نسب، ويفضح الاسم حقيقة التحالف المستتر وراء اختلاف الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص15، تحت عنوان «وجه التعبير عن اليهود بلفظ: ﴿لإخوانهم﴾»","url":""}]},{"id":"s59-29","number":29,"surah":59,"verses":[11],"references":[{"surah":59,"verses":[11]}],"verseLabel":"الحشر: 11","question":"ماذا يفضح وصف إخوان المنافقين بأنهم ﴿الَّذِينَ كَفَرُوا﴾؟","answer":"يصرح بالصفة التي قامت عليها أخوتهم: الكفر، فلا تبقى علاقتهم مجرد جوار أو مصلحة سياسية؛ كما يكشف أن نفاق المتكلمين لا يحجب اشتراكهم الباطني مع الكافرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص16، تحت عنوان «دلالة التعبير بالاسم الموصول»","url":""}]},{"id":"s59-20","number":20,"surah":59,"verses":[14],"references":[{"surah":59,"verses":[14]}],"verseLabel":"الحشر: 14","question":"ماذا يكشف قوله ﴿تَحْسَبُهُمْ جَمِيعًا﴾ عن وحدة أعداء المؤمنين؟","answer":"يكشف أنها وحدة في المظهر والحساب الخارجي فقط؛ فمن يراهم يظنهم كتلة متماسكة، ثم يفضح الواقع أن اجتماع الأجساد والصفوف لا يعني اتحاد القلوب والغايات.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص51، تحت عنوان «بلاغة التعبير بـ﴿تحسبهم﴾»","url":""}]},{"id":"s59-30","number":30,"surah":59,"verses":[14],"references":[{"surah":59,"verses":[14]}],"verseLabel":"الحشر: 14","question":"ماذا توحي كلمة ﴿شَتَّى﴾ في وصف قلوبهم؟","answer":"توحي بتفرق شديد متعدد الصور؛ ليست قلوبهم مختلفة في أمر عابر، بل موزعة بين أهواء وأحقاد وغايات لا يجمعها مقصد ثابت، ولذلك تنهار وحدتهم عند الاختبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص53، تحت عنوان «بلاغة التعبير بلفظ ﴿شتى﴾»","url":""}]},{"id":"s59-21","number":21,"surah":59,"verses":[16],"references":[{"surah":59,"verses":[16]}],"verseLabel":"الحشر: 16","question":"لماذا شُبّه المنافقون بالشيطان الذي يأمر الإنسان بالكفر ثم يتبرأ منه؟","answer":"لأن كليهما يغري ضحيته بالباطل ويعدها النصرة، ثم يخذلها عند حلول العاقبة: حرّض المنافقون اليهود ووعدوهم، فلما جدّ الخطر تركوهم كما يتبرأ الشيطان ممن أطاعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص78، تحت عنوان «بلاغة تشبيه المنافقين بالشيطان»","url":""}]},{"id":"s59-22","number":22,"surah":59,"verses":[18,19,20,21,22,23,24],"references":[{"surah":59,"verses":[18,19,20,21,22,23,24]}],"verseLabel":"الحشر: 18–24","question":"كيف يلتقي ختام سورة الحشر بمطلعها؟","answer":"افتتحت بتسبيح الله في السماوات والأرض، وختمت بأن الخلائق كلها تسبح له بعد عرض أسمائه الحسنى؛ فيعود آخر السورة إلى أولها وتصبح آياتها كلها شاهدًا على كماله واستحقاقه للتنزيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص149، تحت عنوان «بلاغة رد عجز السورة على صدرها»","url":""}]},{"id":"s60-1","number":1,"surah":60,"verses":[1],"references":[{"surah":60,"verses":[1]}],"verseLabel":"الممتحنة: 1","question":"ما سرّ التعبير في قوله ﴿لَا تَتَّخِذُوا عَدُوِّي وَعَدُوَّكُمْ أَوْلِيَاءَ﴾ فقدم عداوته سبحانه؟","answer":"قدم عداوتهم لله لأنها الأصل والأعظم، ومنها تنشأ عداوتهم لأهل الإيمان، فكان تقديمها أبلغ في التنفير من موالاتهم. ثم عطف ﴿وعدوكم﴾ ليذكر المؤمنين بأن ضرر هذه العداوة متوجه إليهم أيضًا، وليقوي داعي اجتنابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص165، تحت عنوان «دلالة عطف (عدوكم) على ﴿عدوي﴾»","url":""}]},{"id":"s60-2","number":2,"surah":60,"verses":[1],"references":[{"surah":60,"verses":[1]}],"verseLabel":"الممتحنة: 1","question":"كيف صوّر قوله ﴿تُلْقُونَ إِلَيْهِمْ بِالْمَوَدَّةِ﴾ وضع المودة في غير موضعها؟","answer":"استعار الإلقاء، وهو طرح الشيء المحسوس، لإيصال المودة؛ فبدت المودة كشيء يرمى إلى العدو، وفي هذه الصورة تقبيح لوضعها حيث لا ينبغي.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص167–168، تحت عنوان «بلاغة الاستعارة في لفظة الإلقاء»","url":""}]},{"id":"s60-18","number":18,"surah":60,"verses":[1],"references":[{"surah":60,"verses":[1]}],"verseLabel":"الممتحنة: 1","question":"كيف ناسب لفظ ﴿تُلْقُونَ﴾ خفاء رسالة حاطب وسرعة إيصالها؟","answer":"يلمح الإلقاء إلى سرعة نقل الرسالة وخفة إيصالها في خفاء؛ فاختير لفظ يصور الحركة العاجلة التي جرى بها بث المودة إلى المشركين.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص168، تحت عنوان «مناسبة استعمال مفردة الإلقاء لسبب النزول»","url":""}]},{"id":"s60-3","number":3,"surah":60,"verses":[1],"references":[{"surah":60,"verses":[1]}],"verseLabel":"الممتحنة: 1","question":"كيف تكشف جملة الحال ﴿وَقَدْ كَفَرُوا بِمَا جَاءَكُمْ مِنَ الْحَقِّ﴾ تناقض مودتهم؟","answer":"تستحضر كفرهم الثابت بالحق حال إلقاء المودة إليهم؛ فتجعل الموالاة مستنكرة لأنهم يعادون أصل الإيمان الذي جاء المؤمنين، لا لأن خلافهم أمر عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص171، تحت عنوان «بلاغة جملة الحال ﴿وقد كفروا﴾ ببيان صاحبها»","url":""}]},{"id":"s60-4","number":4,"surah":60,"verses":[1],"references":[{"surah":60,"verses":[1]}],"verseLabel":"الممتحنة: 1","question":"لماذا تقدّم النهي عن موالاة الأعداء على شرط ﴿إِنْ كُنْتُمْ خَرَجْتُمْ جِهَادًا فِي سَبِيلِي﴾؟","answer":"لأن قطع الموالاة هو المقصود الأهم والأعجل، ثم جاء الشرط لتهييج المؤمنين وتذكيرهم بأن خروجهم لله وطلب مرضاته يقتضي حتمًا ترك موالاة عدوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص179–180، تحت عنوان «السر البلاغي في تقديم النهي على الشرط دون العكس»","url":""}]},{"id":"s60-19","number":19,"surah":60,"verses":[1],"references":[{"surah":60,"verses":[1]}],"verseLabel":"الممتحنة: 1","question":"هل يشكك شرط ﴿إِنْ كُنْتُمْ خَرَجْتُمْ جِهَادًا فِي سَبِيلِي﴾ في صدق المؤمنين؟","answer":"لا؛ فالشرط جيء به للتحذير من فعل يناقض الخروج في سبيل الله، وليصور الموالاة كأمر لا يُتوقع ممن تحقق منه الجهاد وابتغاء مرضاة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص181، تحت عنوان «بلاغة المجاز المرسل المركب في أسلوب الشرط»","url":""}]},{"id":"s60-5","number":5,"surah":60,"verses":[2],"references":[{"surah":60,"verses":[2]}],"verseLabel":"الممتحنة: 2","question":"ما سرّ التعبير في قوله ﴿إِنْ يَثْقَفُوكُمْ﴾ لا «إن يظفروا بكم»؟","answer":"«يثقفوكم» تتضمن الظفر مع الحذق وسرعة الإدراك والإحكام؛ فتصور ترصدهم للمؤمنين وحرصهم على التمكن منهم. وهذه المعاني تزيد على مطلق الظفر، وتلائم ما يترتب عليه من إظهار العداوة والاعتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص199، تحت عنوان «نكتة استعمال مفردة ﴿يثقفوكم﴾»","url":""}]},{"id":"s60-6","number":6,"surah":60,"verses":[3],"references":[{"surah":60,"verses":[3]}],"verseLabel":"الممتحنة: 3","question":"لماذا قيل للمؤمنين ﴿لَنْ تَنْفَعَكُمْ أَرْحَامُكُمْ وَلَا أَوْلَادُكُمْ﴾؟","answer":"لإبطال الدافع الذي قد يحملهم على موالاة العدو طلبًا لحماية الأقارب والأولاد؛ فهذه الروابط لا تدفع حكم الله يوم القيامة، ولا تبرر مخالفة أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص211، تحت عنوان «فائدة النفي وغرضه»","url":""}]},{"id":"s60-20","number":20,"surah":60,"verses":[3],"references":[{"surah":60,"verses":[3]}],"verseLabel":"الممتحنة: 3","question":"لماذا خُصّ الأولاد بالذكر بعد ﴿أَرْحَامُكُمْ﴾؟","answer":"لأن الأولاد داخلون في الأرحام، لكنهم ألصق بالنفس وأشد استدعاء للعطف؛ فإفرادهم بعد العام يستوعب أقوى دوافع الموالاة ويؤكد أن قربهم لا ينفع يوم القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص213، تحت عنوان «بلاغة التتميم في عطف الخاص على العام»","url":""}]},{"id":"s60-7","number":7,"surah":60,"verses":[4],"references":[{"surah":60,"verses":[4]}],"verseLabel":"الممتحنة: 4","question":"لماذا قيل ﴿أُسْوَةٌ حَسَنَةٌ فِي إِبْرَاهِيمَ﴾ لا «بإبراهيم»؟","answer":"صوّر حرف الظرفية إبراهيم والذين معه كأنهم محل مستقر للأسوة؛ فالقدوة ليست وصفًا عابرًا، بل موقف متجسد في براءتهم من الشرك وأهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص224، تحت عنوان «بلاغة استعمال حرف الظرفية»","url":""}]},{"id":"s60-8","number":8,"surah":60,"verses":[4],"references":[{"surah":60,"verses":[4]}],"verseLabel":"الممتحنة: 4","question":"ما الذي أخرجه الاستثناء في ﴿إِلَّا قَوْلَ إِبْرَاهِيمَ لِأَبِيهِ لَأَسْتَغْفِرَنَّ لَكَ﴾ من الاقتداء؟","answer":"أخرج هذا القول الخاص من الأسوة؛ فلا يتخذ المؤمنون وعد إبراهيم لأبيه المشرك ذريعة للاستغفار للمشركين، مع بقاء الاقتداء به في البراءة من الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص235–236، تحت عنوان «نوع الاستثناء ودلالته»","url":""}]},{"id":"s60-21","number":21,"surah":60,"verses":[4],"references":[{"surah":60,"verses":[4]}],"verseLabel":"الممتحنة: 4","question":"لماذا وُجّه الاستثناء إلى وعد إبراهيم لأبيه بالاستغفار؟","answer":"لأن الوعد جاء مؤكدًا بالقسم والنون، فنهى الاستثناء عن الاقتداء بهذا الالتزام ابتداءً، ومنع تبعًا له ما يفضي إليه من الاستغفار للمشركين.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص236، تحت عنوان «توجيه الاستثناء للوعد لا للاستغفار»","url":""}]},{"id":"s60-9","number":9,"surah":60,"verses":[7],"references":[{"surah":60,"verses":[7]}],"verseLabel":"الممتحنة: 7","question":"لماذا فُصل رجاء المودة في ﴿عَسَى اللَّهُ أَنْ يَجْعَلَ بَيْنَكُمْ﴾ عما قبله؟","answer":"جاء استئنافًا يؤنس المؤمنين بعد شدة الأمر بالبراءة، ويفتح لهم باب الرجاء بأن تتحول عداوة المشركين إلى مودة إذا هداهم الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص269، تحت عنوان «نكتة فصل الجملة عن السابق»","url":""}]},{"id":"s60-22","number":22,"surah":60,"verses":[7],"references":[{"surah":60,"verses":[7]}],"verseLabel":"الممتحنة: 7","question":"ماذا تحمل ﴿عَسَى﴾ من الله في وعد تبدل العداوة مودة؟","answer":"تحمل الإطماع والوعد القريب؛ فإذا أسند الرجاء إلى الله لم يبق مجرد احتمال مضطرب، بل صار باعثًا على الأمل في هداية من كان عدوًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص269–270، تحت عنوان «بلاغة استعمال الفعل ﴿عسى﴾»","url":""}]},{"id":"s60-23","number":23,"surah":60,"verses":[7],"references":[{"surah":60,"verses":[7]}],"verseLabel":"الممتحنة: 7","question":"لماذا قيل ﴿أَنْ يَجْعَلَ بَيْنَكُمْ... مَوَدَّةً﴾؟","answer":"لأن الجعل يصور نقل العلاقة من حال العداوة إلى حال المودة، وهو تحول عجيب لا يقدر عليه إلا الله؛ فأسند إليه لإظهار قدرته ولطف تدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص270–271، تحت عنوان «نكتة التعبير بالفعل ﴿يجعل﴾»","url":""}]},{"id":"s60-10","number":10,"surah":60,"verses":[8,9],"references":[{"surah":60,"verses":[8,9]}],"verseLabel":"الممتحنة: 8–9","question":"لماذا استؤنف قوله ﴿لَا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ﴾؟","answer":"ليقرر حكمًا مستقلًا يرفع توهم أن البراءة من عداوة الكافرين تعني منع البر والعدل مع كل غير محارب؛ فبيّن أن المسالمين بابهم غير باب المعتدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص280، تحت عنوان «علة فصل جملة ﴿لا ينهاكم الله﴾»","url":""}]},{"id":"s60-24","number":24,"surah":60,"verses":[8,9],"references":[{"surah":60,"verses":[8,9]}],"verseLabel":"الممتحنة: 8–9","question":"ما الذي يحصره قوله ﴿إِنَّمَا يَنْهَاكُمُ اللَّهُ﴾ في الممتحنة؟","answer":"يحصر النهي عن التولي في الذين قاتلوا المؤمنين وأخرجوهم وأعانوا على إخراجهم؛ فيميز بوضوح بين معاملة المسالمين وبين موالاة المعتدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص293، تحت عنوان «نوع القصر وبلاغته في قوله: ﴿إنما ينهاكم الله﴾ الآية»","url":""}]},{"id":"s60-25","number":25,"surah":60,"verses":[8,9],"references":[{"surah":60,"verses":[8,9]}],"verseLabel":"الممتحنة: 8–9","question":"لماذا عبّرت الآية عن المحظور بـ﴿أَنْ تَوَلَّوْهُمْ﴾ لا «أن تبروهم»؟","answer":"لأن التولي هو النصرة والموالاة التي تذيب موقف المؤمن في صف المعتدي، أما البر والإنصاف فليسَا ولاءً؛ فاختيار اللفظ يرسم الحد الفاصل بين الإحسان المشروع والموالاة المنهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص297، تحت عنوان «دلالة استعمال مفردة التولي دون البر»","url":""}]},{"id":"s60-11","number":11,"surah":60,"verses":[8],"references":[{"surah":60,"verses":[8]}],"verseLabel":"الممتحنة: 8","question":"لماذا اختير ﴿أَنْ تَبَرُّوهُمْ﴾ في معاملة غير المحاربين؟","answer":"لأن البر لفظ واسع يجمع الإحسان والإكرام وحسن المعاملة، فلا يقف الحكم عند مجرد ترك الأذى، بل يفتح أبواب الصلة التي لا تتعارض مع الولاء لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص286–287، تحت عنوان «نكتة التعبير بمفردة ﴿تبروهم﴾»","url":""}]},{"id":"s60-26","number":26,"surah":60,"verses":[8],"references":[{"surah":60,"verses":[8]}],"verseLabel":"الممتحنة: 8","question":"لماذا قُدِّم البر على الإقساط في ﴿أَنْ تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ﴾؟","answer":"لأن البر أوسع وجوه الإحسان، ثم خُص العدل بالذكر لعظم شأنه ولئلا يظن أن اختلاف الدين يسوغ الجور؛ فانتقل النظم من العام إلى ما يحتاج إلى توكيد خاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص289، تحت عنوان «سر تقديم البر على الإقساط»","url":""}]},{"id":"s60-12","number":12,"surah":60,"verses":[10],"references":[{"surah":60,"verses":[10]}],"verseLabel":"الممتحنة: 10","question":"لماذا اعترض قوله ﴿اللَّهُ أَعْلَمُ بِإِيمَانِهِنَّ﴾ بين امتحان المهاجرات والحكم عليهن؟","answer":"ليحدد حد الامتحان البشري: يُبنى الحكم على العلامات الظاهرة، أما حقيقة الإيمان في القلوب فعلمها لله وحده؛ فلا يوهم الأمر بالامتحان إمكان كشف السرائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص310–311، تحت عنوان «بلاغة الجملة الاعتراضية»","url":""}]},{"id":"s60-27","number":27,"surah":60,"verses":[10],"references":[{"surah":60,"verses":[10]}],"verseLabel":"الممتحنة: 10","question":"كيف قيل ﴿فَإِنْ عَلِمْتُمُوهُنَّ مُؤْمِنَاتٍ﴾ مع أن حقيقة الإيمان لا يعلمها إلا الله؟","answer":"أطلق العلم على الظن الغالب الذي تقوم عليه الأحكام بعد الامتحان؛ فالمطلوب تحقق بشري معتبر بالقرائن، لا يقين يحيط بما في القلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص313، تحت عنوان «بلاغة إطلاق العلم على الظن الغالب»","url":""}]},{"id":"s60-13","number":13,"surah":60,"verses":[10],"references":[{"surah":60,"verses":[10]}],"verseLabel":"الممتحنة: 10","question":"لماذا نُفي الحل من الجانبين في ﴿لَا هُنَّ حِلٌّ لَهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ﴾؟","answer":"لقطع كل توهم ببقاء رابطة الزواج من جهة أحد الزوجين؛ فالنفي الثاني يتمم الأول ويؤكد أن الانفصال واقع على الطرفين بلا استثناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص316–317، تحت عنوان «دلالة العطف بين التتميم والتأكيد»","url":""}]},{"id":"s60-28","number":28,"surah":60,"verses":[10],"references":[{"surah":60,"verses":[10]}],"verseLabel":"الممتحنة: 10","question":"ما أثر عكس ترتيب الضمائر في ﴿لَا هُنَّ حِلٌّ لَهُمْ وَلَا هُمْ يَحِلُّونَ لَهُنَّ﴾؟","answer":"صنع تقابلًا محكمًا يواجه كل طرف بالآخر، ثم يعكس موضعيهما في الجملة الثانية؛ فتتجسد المباعدة المتبادلة وانقطاع الحل بين الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص317، تحت عنوان «بلاغة العكس في النظم بين الجمل المتقابلة»","url":""}]},{"id":"s60-14","number":14,"surah":60,"verses":[10],"references":[{"surah":60,"verses":[10]}],"verseLabel":"الممتحنة: 10","question":"ما الصورة التي يرسمها قوله ﴿وَلَا تُمْسِكُوا بِعِصَمِ الْكَوَافِرِ﴾ لرابطة الزواج؟","answer":"يصوّر عقد الزواج بحبل يعصم الزوجين ويربط أحدهما بالآخر، ثم يصور بقاء الزوج متمسكًا بذلك الحبل؛ فجاء النهي إعلانًا لقطع الرابطة بعد اختلاف الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص325–326، تحت عنوان «بلاغة الاستعارة»","url":""}]},{"id":"s60-29","number":29,"surah":60,"verses":[10],"references":[{"surah":60,"verses":[10]}],"verseLabel":"الممتحنة: 10","question":"من المراد بـ﴿الْكَوَافِرِ﴾ في سياق ﴿وَلَا تُمْسِكُوا بِعِصَمِ الْكَوَافِرِ﴾؟","answer":"المراد في هذا السياق المشركات الوثنيات اللاتي قامت الآية بقطع عصمتهن من المؤمنين، فلا يحمل اللفظ هنا على كل كافرة بلا نظر إلى الأحكام الأخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص326، تحت عنوان «معنى تعريف لفظ ﴿الكوافر﴾»","url":""}]},{"id":"s60-15","number":15,"surah":60,"verses":[12],"references":[{"surah":60,"verses":[12]}],"verseLabel":"الممتحنة: 12","question":"لماذا بدأت منهيات بيعة النساء بترك الشرك؟","answer":"لأن التوحيد أصل صحة الإيمان والعمل، فلا يستقيم إصلاح بقية السلوك مع فساد الاعتقاد؛ ثم إنه كان أظهر المفاسد وأشيعها في ذلك المجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص350، تحت عنوان «دلالة البدء بترك الشرك»","url":""}]},{"id":"s60-30","number":30,"surah":60,"verses":[12],"references":[{"surah":60,"verses":[12]}],"verseLabel":"الممتحنة: 12","question":"لماذا ذُكرت السرقة بعد الشرك في بيعة النساء؟","answer":"لأن الشرك تضييع لحق الله، وأعقبه الاعتداء على أموال الناس بوصفه تضييعًا لحقوق العباد؛ فانتقل السياق من أصل الدين إلى أول مظاهر العدوان الاجتماعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص353، تحت عنوان «بلاغة ذكر السرقة بعد الشرك»","url":""}]},{"id":"s60-31","number":31,"surah":60,"verses":[12],"references":[{"surah":60,"verses":[12]}],"verseLabel":"الممتحنة: 12","question":"لماذا جاء النهي عن قتل الأولاد بعد النهي عن الزنا؟","answer":"لأن الزنا قد يفضي إلى حمل واختلاط نسب ثم إلى التخلص من الولد بالقتل، فذكر المسبب بعد سببه، مع كون الزنا أشيع يومئذ فجاء ترتيبه أولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص354، تحت عنوان «نكتة ذكر جريمة القتل بعد فاحشة الزنا»","url":""}]},{"id":"s60-32","number":32,"surah":60,"verses":[12],"references":[{"surah":60,"verses":[12]}],"verseLabel":"الممتحنة: 12","question":"لماذا خُتمت منهيات البيعة بقوله ﴿وَلَا يَعْصِينَكَ فِي مَعْرُوفٍ﴾؟","answer":"ليجمع ما لم تفصله المنهيات السابقة تحت قاعدة عامة: طاعة النبي ﷺ في كل معروف وترك كل معصية؛ فكان الختام جامعًا لما تقدم وما يستجد.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص360، تحت عنوان «مناسبة ختم المنهيات بترك العصيان»","url":""}]},{"id":"s60-16","number":16,"surah":60,"verses":[13],"references":[{"surah":60,"verses":[13]}],"verseLabel":"الممتحنة: 13","question":"كيف أعاد استئناف ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَتَوَلَّوْا قَوْمًا﴾ ختام السورة إلى مطلعها؟","answer":"استأنف نهيًا جديدًا يرسخ مقصد السورة؛ فكما بدأت بمنع موالاة أعداء الله، ختمت بمنع تولي قوم غضب الله عليهم، فانتظم أولها وآخرها في التحذير نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص370، تحت عنوان «دلالة جملة الاستئناف»","url":""}]},{"id":"s60-33","number":33,"surah":60,"verses":[13],"references":[{"surah":60,"verses":[13]}],"verseLabel":"الممتحنة: 13","question":"لماذا عاد نداء المؤمنين في ختام سورة الممتحنة؟","answer":"ليجدد استدعاء إيمانهم عند آخر وصية، ويعمم الخطاب لكل المؤمنين في كل زمان ومكان؛ فيبقى النهي حاضرًا بعد انقضاء سبب النزول.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص370–371، تحت عنوان «دلالة نداء المؤمنين في الختام»","url":""}]},{"id":"s60-17","number":17,"surah":60,"verses":[13],"references":[{"surah":60,"verses":[13]}],"verseLabel":"الممتحنة: 13","question":"كيف يغيّر معنى ﴿مِنْ﴾ في ﴿كَمَا يَئِسَ الْكُفَّارُ مِنْ أَصْحَابِ الْقُبُورِ﴾ وجه التشبيه؟","answer":"إن كانت لابتداء الغاية فالصورة ليأس الكفار الأحياء من عودة أصحاب القبور، وإن كانت بيانية فالمراد كفار القبور أنفسهم وقد انقطع رجاؤهم من نعيم الآخرة؛ وفي الوجهين يبرز انقطاع الأمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص376–377، تحت عنوان «دلالة الحرف ﴿من﴾ وأثره في توجيه التشبيه البلاغي»","url":""}]},{"id":"s60-34","number":34,"surah":60,"verses":[13],"references":[{"surah":60,"verses":[13]}],"verseLabel":"الممتحنة: 13","question":"ماذا يضيف تشبيه يأسهم من الآخرة بيأس الكفار من أصحاب القبور؟","answer":"يجعل انقطاع رجائهم محسوسًا كحال من تيقن فوات ما يطلبه: إما يأس الحي من رجوع الميت، أو يأس الميت الكافر من نعيم الآخرة؛ فيشدد صورة الإعراض وعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص377–378، تحت عنوان «بلاغة التشبيه ودلالته»","url":""}]},{"id":"s61-1","number":1,"surah":61,"verses":[1],"references":[{"surah":61,"verses":[1]}],"verseLabel":"الصف: 1","question":"ما سرّ افتتاح سورة الصف بالفعل الماضي ﴿سَبَّحَ﴾؟","answer":"الماضي يقرر تحقق التسبيح وثبوته، ولا يحصره في زمن انتهى؛ فالمبحث يوجهه إلى الدوام والاستمرار، لأن تنزيه الخلق لخالقهم لا ينقطع. وفي صيغة «سبّح» مبالغة في التنزيه، فيفتتح الخطاب بإعلان خضوع الكون لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص390–391، تحت عنوان «دلالة التعبير بالفعل ﴿سبح﴾ مادة وصيغة»","url":""}]},{"id":"s61-2","number":2,"surah":61,"verses":[2],"references":[{"surah":61,"verses":[2]}],"verseLabel":"الصف: 2","question":"ما سرّ التعبير في قوله ﴿لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ﴾ ولم يقل «لم لا تفعلون ما تقولون»؟","answer":"وجه الإنكار إلى القول لأن إطلاق الدعوى أو الوعد يجعل صاحبه كأنه متعهد بالوفاء، ثم يكشف قوله ﴿ما لا تفعلون﴾ مخالفة هذا التعهد. فالتوبيخ متعلق بقول لا يصدقه العمل، وهو تنبيه إلى خطورة الالتزام باللسان ثم ترك الوفاء، لا مجرد السؤال عن ترك فعلٍ من الأفعال.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص408–409، تحت عنوان «دلالة اسم الاستفهام (ما)، وتعيين المستفهم عنه»","url":""}]},{"id":"s61-3","number":3,"surah":61,"verses":[3],"references":[{"surah":61,"verses":[3]}],"verseLabel":"الصف: 3","question":"ما سر أن قيل ﴿كَبُرَ مَقْتًا عِنْدَ اللَّهِ﴾ بدل «كبر المقت»؟","answer":"يجعل النظم السامع يترقب أولًا: ما الذي كبر؟ ثم يأتي ﴿مقتًا﴾ بيانًا بعد إبهام، فيهوّل شأن هذا القول ويعظّم قبحه في النفس. واختيار المقت، وهو أشد البغض، يزيد التشنيع على أن يقول الإنسان ما لا يفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص414–415، تحت عنوان «الموقع الإعرابي لـ﴿مقتًا﴾ ودلالته»","url":""}]},{"id":"s61-4","number":4,"surah":61,"verses":[4],"references":[{"surah":61,"verses":[4]}],"verseLabel":"الصف: 4","question":"ما الصورة التي يرسمها تشبيه صف المؤمنين بالبنيان؟","answer":"يصورهم أجزاء متساندة من بناء واحد، يشد بعضها بعضًا ولا تترك للعدو ثغرة. فالتشبيه ينقل انتظام الصف ووحدة القصد والثبات من معنى معنوي إلى مشهد محسوس قوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص430، تحت عنوان «دلالة (كأن) التشبيهية»","url":""}]},{"id":"s61-16","number":16,"surah":61,"verses":[4],"references":[{"surah":61,"verses":[4]}],"verseLabel":"الصف: 4","question":"ماذا يضيف وصف بنيان المؤمنين بأنه ﴿مَرْصُوصٌ﴾؟","answer":"يدل على إحكام اتصال أجزائه حتى لا يبقى بينها خلل، فيصور تماسك المؤمنين ظاهرًا وباطنًا، وثباتهم أمام العدو كأنهم جسم واحد لا يتفكك.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص432، تحت عنوان «دلالة الصفة ﴿مرصوص﴾»","url":""}]},{"id":"s61-5","number":5,"surah":61,"verses":[5],"references":[{"surah":61,"verses":[5]}],"verseLabel":"الصف: 5","question":"ماذا يضيف قوله ﴿وَقَدْ تَعْلَمُونَ أَنِّي رَسُولُ اللَّهِ﴾ إلى إنكار موسى أذاهم؟","answer":"يجعل أذاهم واقعًا مع علمهم برسالته، فيشتد الإنكار؛ لأن مقتضى هذا العلم تصديقه وتعظيمه لا إيذاءه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص442، تحت عنوان «معنى (الواو) ودلالتها في ﴿وقد﴾»","url":""}]},{"id":"s61-6","number":6,"surah":61,"verses":[5],"references":[{"surah":61,"verses":[5]}],"verseLabel":"الصف: 5","question":"لماذا تعلقت عقوبة الزيغ بقلوبهم في قوله ﴿أَزَاغَ اللَّهُ قُلُوبَهُمْ﴾؟","answer":"لأنهم اختاروا الميل عن الحق مع معرفته، فبلغ الجزاء موضع الإدراك والإيمان فيهم. وإزاغة القلوب تعني حرمانها التوفيق والثبات بعد إصرار أصحابها، فتظهر خطورة الانحراف المتعمد حين يتحول إلى طبع مستقر.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص448، تحت عنوان «دلالة تعليق الإزاغة بالقلوب»","url":""}]},{"id":"s61-7","number":7,"surah":61,"verses":[6],"references":[{"surah":61,"verses":[6]}],"verseLabel":"الصف: 6","question":"لماذا نادى عيسى قومه ﴿يَا بَنِي إِسْرَائِيلَ﴾ بدل «يا قوم»؟","answer":"يذكرهم باسم أبيهم الكريم وما يقتضيه الانتساب إليه من طاعة الله، ويستعطفهم بما يجمعهم من أصل معروف. ومن وجوه العدول أيضًا أن عيسى لا أب له فينسب نفسه إليهم بقول «يا قوم»، فاختير النداء الذي يحقق التذكير والاستمالة معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص459، تحت عنوان «دلالة العدول من (القوم) إلى (بني إسرائيل)»","url":""}]},{"id":"s61-8","number":8,"surah":61,"verses":[6],"references":[{"surah":61,"verses":[6]}],"verseLabel":"الصف: 6","question":"ماذا يقرر وصف عيسى نفسه بأنه ﴿مُصَدِّقًا﴾ للتوراة؟","answer":"يقرر أن رسالته ليست قطيعة مع الوحي السابق، بل جاءت مؤيدة لأصله الحق ومبينة له؛ ولذلك كان تصديقه للتوراة حجة على بني إسرائيل ودعوة إلى قبول الرسول الذي وافق ما عرفوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص461، تحت عنوان «دلالة ﴿مصدقًا﴾ موقعًا ومادة»","url":""}]},{"id":"s61-17","number":17,"surah":61,"verses":[6],"references":[{"surah":61,"verses":[6]}],"verseLabel":"الصف: 6","question":"كيف جمع عيسى بين تصديق التوراة والتبشير برسول يأتي بعده؟","answer":"جمع بين حفظ صلة الرسالة بماضي الوحي وفتحها على خاتمته: يصدق ما قبله ويبشر بما بعده. فالعطف يكشف وحدة مصدر الرسالات وتكاملها، وينفي توهم التناقض أو الانقطاع بينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص463–464، تحت عنوان «معنى (الواو) ودلالتها في ﴿ومبشرًا﴾»","url":""}]},{"id":"s61-9","number":9,"surah":61,"verses":[6],"references":[{"surah":61,"verses":[6]}],"verseLabel":"الصف: 6","question":"لماذا صرحت بشارة عيسى باسم الرسول ﴿أَحْمَدُ﴾؟","answer":"ليتعين المبشر به تعيينًا يزيل الإبهام ويمنع صرف البشارة إلى غيره؛ فذكر الاسم العلم يجعل العلامة أوضح وأقوى في إقامة الحجة على من عرف البشارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص467، تحت عنوان «دلالة التعبير بالاسم العلم ﴿أحمد﴾»","url":""}]},{"id":"s61-18","number":18,"surah":61,"verses":[6],"references":[{"surah":61,"verses":[6]}],"verseLabel":"الصف: 6","question":"ما الدلالة التي يحملها اسم ﴿أَحْمَدُ﴾ في البشارة؟","answer":"يجمع الاسم معنى كثرة الحمد أو شدة استحقاقه؛ فهو أكثر حمدًا لربه، وأجمع للخصال التي يُحمد عليها. وبذلك يطابق الاسم كمال صفته ورسالة الخير التي جاء بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص469، تحت عنوان «دلالة الاسم ﴿أحمد﴾»","url":""}]},{"id":"s61-10","number":10,"surah":61,"verses":[8],"references":[{"surah":61,"verses":[8]}],"verseLabel":"الصف: 8","question":"ما الصورة في محاولة إطفاء نور الله بالأفواه؟","answer":"تمثل محاولتهم إبطال الوحي وإخماد الدعوة بمن ينفخ بفمه في نور عظيم ليطفئه؛ فتفضح ضآلة الوسيلة أمام قوة الحق، وتسخر من وهم قدرتهم على منع تمام نور الله وانتشاره.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص496، تحت عنوان «دلالة الاستعارة التمثيلية»","url":""}]},{"id":"s61-11","number":11,"surah":61,"verses":[9],"references":[{"surah":61,"verses":[9]}],"verseLabel":"الصف: 9","question":"ماذا يعني وعد الله أن ﴿يُظْهِرَهُ﴾ على الدين؟","answer":"يعني أن يعلي دين الحق ويبين حجته حتى يظهر صدقه وبطلان ما يخالفه، ويشمل علو البرهان وانتشار الدين وغلبته؛ فلا ينحصر الوعد في صورة واحدة من صور الظهور.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص514، تحت عنوان «دلالة الكناية في (يظهره)»","url":""}]},{"id":"s61-19","number":19,"surah":61,"verses":[9],"references":[{"surah":61,"verses":[9]}],"verseLabel":"الصف: 9","question":"ماذا يضيف التوكيد بـ﴿كُلِّهِ﴾ في وعد إظهار دين الحق؟","answer":"يؤكد أن الوعد لا يقتصر على بعض الأديان أو بعض المواطن، بل يتعلق بجنس الدين المخالف كله؛ فيستغرق المقابلة ويزيل احتمال التخصيص.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص517، تحت عنوان «دلالة التوكيد بـ﴿كله﴾»","url":""}]},{"id":"s61-12","number":12,"surah":61,"verses":[10],"references":[{"surah":61,"verses":[10]}],"verseLabel":"الصف: 10","question":"كيف يصبح الإيمان والجهاد ﴿تِجَارَةً﴾ رابحة؟","answer":"شُبها بالتجارة لأن المؤمن يبذل ماله ونفسه في طاعة الله وينال في المقابل نجاة ومغفرة وجنة. والصورة تخاطب رغبة الإنسان في الربح، ثم ترتقي بها من المكسب العاجل إلى صفقة لا خسارة فيها ولا نفاد لعوضها.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص526–527، تحت عنوان «دلالة الاستعارة في ﴿تجارة﴾»","url":""}]},{"id":"s61-13","number":13,"surah":61,"verses":[11],"references":[{"surah":61,"verses":[11]}],"verseLabel":"الصف: 11","question":"ما سرّ تقديم الأموال على الأنفس في الجهاد؟","answer":"تقديم الأموال ثم الأنفس يصور الترقي في مراتب البذل إلى ما هو أشق وأعظم، وتذكر الموسوعة أن المال وسيلة يستعان بها في الإنفاق وإعانة النفس. فترتيبهما يجمع البدء بما يعين على الجهاد ثم بلوغ غايته ببذل النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص536–537، تحت عنوان «معنى (الواو) ودلالتها في ﴿وأنفسكم﴾»","url":""}]},{"id":"s61-14","number":14,"surah":61,"verses":[13],"references":[{"surah":61,"verses":[13]}],"verseLabel":"الصف: 13","question":"لماذا سُمّي النصر والفتح ﴿أُخْرَى﴾ بعد المغفرة والجنة؟","answer":"لأنهما نعمة أخرى عاجلة تضاف إلى الجزاء الأخروي ولا تساويه رتبة؛ فالمغفرة والجنة الأصل الأعظم، ثم يأتي النصر والفتح زيادةً تقوي المؤمنين في الدنيا وتبشرهم بقرب الثمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص551–552، تحت عنوان «دلالة صيغة (أخرى)»","url":""}]},{"id":"s61-20","number":20,"surah":61,"verses":[13],"references":[{"surah":61,"verses":[13]}],"verseLabel":"الصف: 13","question":"لماذا وُصفت نعمة النصر والفتح بأنها ﴿تُحِبُّونَهَا﴾؟","answer":"لمراعاة ميل النفوس إلى رؤية ثمرة قريبة محسوسة، فتزداد رغبتها في الجهاد والثبات. ولا يعني ذلك أن النصر الدنيوي أفضل من نعيم الآخرة، بل هو حافز عاجل بعد الوعد الأعظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص552–553، تحت عنوان «دلالة النعت بالجملة الفعلية المضارعية ﴿تحبونها﴾»","url":""}]},{"id":"s61-15","number":15,"surah":61,"verses":[14],"references":[{"surah":61,"verses":[14]}],"verseLabel":"الصف: 14","question":"ماذا يطلب الأمر ﴿كُونُوا أَنْصَارَ اللَّهِ﴾ فوق مجرد فعل النصرة مرة؟","answer":"يطلب أن تصبح النصرة صفة ثابتة وهوية ملازمة للمؤمنين، فيقيموا على حماية الدين والدعوة إليه والطاعة، لا أن تكون استجابتهم موقفًا عابرًا ينتهي بزوال سببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص564–565، تحت عنوان «دلالة فعل الكون أمرًا»","url":""}]},{"id":"s61-21","number":21,"surah":61,"verses":[14],"references":[{"surah":61,"verses":[14]}],"verseLabel":"الصف: 14","question":"لماذا قُربت دعوة المؤمنين إلى النصرة بمثال حواريي عيسى؟","answer":"ليتحول الأمر إلى قدوة تاريخية مجربة: دعا عيسى أنصاره فاستجاب الحواريون بوضوح، فكان موقفهم مثالًا للصدق والثبات يحفز أمة محمد ﷺ إلى جواب مماثل.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص567، تحت عنوان «نوع التشبيه في ﴿كما قال﴾ والغرض منه»","url":""}]},{"id":"s61-22","number":22,"surah":61,"verses":[14],"references":[{"surah":61,"verses":[14]}],"verseLabel":"الصف: 14","question":"ماذا تبشر به خاتمة قصة الحواريين في قوله ﴿فَأَيَّدْنَا الَّذِينَ آمَنُوا﴾؟","answer":"تبشر بأن نصرة دين الله لا تضيع؛ فقد قوى الله المؤمنين وثبتهم حتى غلبوا عدوهم وظهروا. والتعبير بالماضي يعرض تحقق الوعد في القصة دليلًا يطمئن المؤمنين إلى عاقبة النصرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص580–581، تحت عنوان «دلالة الفعل الماضي ﴿فأيدنا﴾ مادة وصيغة»","url":""}]},{"id":"s62-1","number":1,"surah":62,"verses":[1],"references":[{"surah":62,"verses":[1]}],"verseLabel":"الجمعة: 1","question":"كيف يمهّد افتتاح سورة الجمعة بقوله ﴿يُسَبِّحُ لِلَّهِ﴾ لمقصدها؟","answer":"يفتتح السورة بصورة الكون كله قائمًا بتعظيم الله، فيهيئ لإنكار من يترك ذكره عند نداء الجمعة وينفض إلى التجارة أو اللهو؛ فمن سبّح له الوجود كله أحق أن تُعظَّم عبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص600، تحت عنوان «براعة الاستهلال في جملة ﴿يسبح لله﴾ الآية»","url":""}]},{"id":"s62-15","number":15,"surah":62,"verses":[1],"references":[{"surah":62,"verses":[1]}],"verseLabel":"الجمعة: 1","question":"لماذا قيل في الجمعة ﴿يُسَبِّحُ﴾ بالمضارع، وفي الصف ﴿سَبَّحَ﴾ بالماضي؟","answer":"يستحضر المضارع دوام التسبيح وتجددَه، وهو أنسب بسورة تأمر بذكر الله وتنهى عن الانشغال عنه؛ أما الماضي في الصف فقرر وقوع التسبيح وثبوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص601، تحت عنوان «نكتة العدول عن الماضي ﴿سبح﴾ في سورة الصف إلى المضارع هنا ﴿يسبح﴾»","url":""}]},{"id":"s62-16","number":16,"surah":62,"verses":[1],"references":[{"surah":62,"verses":[1]}],"verseLabel":"الجمعة: 1","question":"ما مناسبة افتتاح السورة بأسماء الله ﴿الْمَلِكِ الْقُدُّوسِ الْعَزِيزِ الْحَكِيمِ﴾؟","answer":"تجمع كمال السلطان والتنزه والغلبة والحكمة: فهو الملك الذي تُقصد حضرته، المنزه عن النقص، العزيز الذي لا يُغلب، الحكيم في تشريعه. لذلك تقبح الغفلة عن ذكره لأجل تجارة أو لهو.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص606، تحت عنوان «مناسبة ذكر الصفات: ﴿الملك القدوس العزيز الحكيم﴾»","url":""}]},{"id":"s62-2","number":2,"surah":62,"verses":[2],"references":[{"surah":62,"verses":[2]}],"verseLabel":"الجمعة: 2","question":"لماذا وصف العرب الذين بُعث فيهم الرسول ﷺ بـ﴿الْأُمِّيِّينَ﴾؟","answer":"لإظهار عظم التحول الذي صنعته الرسالة في قوم لم يكونوا أهل كتاب وتعليم؛ فانتقلوا بالوحي إلى التلاوة والتزكية والحكمة، كما كانت أميته ﷺ برهانًا على أن هذا العلم وحي لا تعلم بشري.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص611–612، تحت عنوان «معنى (أل) في ﴿الأميين﴾، ونكتة إيثار التعبير بهذه اللفظة»","url":""}]},{"id":"s62-3","number":3,"surah":62,"verses":[2],"references":[{"surah":62,"verses":[2]}],"verseLabel":"الجمعة: 2","question":"ما سرّ تقديم ﴿يَتْلُو عَلَيْهِمْ آيَاتِهِ﴾ على التزكية والتعليم؟","answer":"يعرض الترتيب مراحل الدعوة: تبليغ الآيات وتدبرها، ثم تطهير النفوس من الكفر والرذائل، ثم ترسيخ العقيدة والشرائع والحكمة بالتعليم. فالتلاوة مدخل التغيير، والتزكية تهيئ النفس لبناء العلم والعمل، وهو من ترتيب مقاصد الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص621، تحت عنوان «دلالة ترتيب جمل الصفات الثلاث ﴿يتلو﴾، ﴿ويزكيهم﴾، ﴿ويعلمهم﴾»","url":""}]},{"id":"s62-5","number":5,"surah":62,"verses":[3],"references":[{"surah":62,"verses":[3]}],"verseLabel":"الجمعة: 3","question":"ماذا يفيد تنكير ﴿آخَرِينَ﴾ في امتداد بعثة النبي ﷺ؟","answer":"يفتح اللفظ الباب لأجيال وأقوام غير معينين يلتحقون بالأمة بعد السابقين، ومنهم غير العرب؛ فلا تحصر الرسالة في جماعة الميلاد الأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص629–630، تحت عنوان «دلالة التعبير بـ﴿وآخرين﴾، ولطيفة تنكيره»","url":""}]},{"id":"s62-17","number":17,"surah":62,"verses":[3],"references":[{"surah":62,"verses":[3]}],"verseLabel":"الجمعة: 3","question":"إلى من يعود الضمير في قوله ﴿آخَرِينَ مِنْهُمْ﴾؟","answer":"يحتمل عوده إلى الأميين، فيدخل من يأتي من العرب بعد السابقين، ويحتمل عوده إلى المؤمنين فيشمل كل من لحق بهم في الإيمان من العرب وغيرهم؛ وجامع الجميع الانتماء إلى أمة الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص630–631، تحت عنوان «مرجع الضمير في ﴿منهم﴾»","url":""}]},{"id":"s62-18","number":18,"surah":62,"verses":[3],"references":[{"surah":62,"verses":[3]}],"verseLabel":"الجمعة: 3","question":"ماذا توحي ﴿لَمَّا﴾ في قوله ﴿لَمَّا يَلْحَقُوا بِهِمْ﴾؟","answer":"تنفي أن اللاحقين أدركوا السابقين وقت نزول الآية، مع إشعار قوي بأن لحاقهم سيقع؛ فهي تجمع تأخرهم الزمني ووعد امتداد الأمة إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص633، تحت عنوان «معنى ﴿لما﴾ في جملة ﴿لما يلحقوا بهم﴾»","url":""}]},{"id":"s62-6","number":6,"surah":62,"verses":[5],"references":[{"surah":62,"verses":[5]}],"verseLabel":"الجمعة: 5","question":"لماذا قيل إن الحمار يحمل ﴿أَسْفَارًا﴾ لا «كتبًا»؟","answer":"الأسفار كتب عظيمة تكشف العلم، فاختيارها يعظم قيمة ما حُملوه ثم يضاعف المفارقة حين لا ينتفع الحامل بشيء منه. وتنكيرها يستكثر تلك الكتب وينوعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص654–655، تحت عنوان «دلالة التعبير بـ﴿أسفارًا﴾ دون غيرها كـ(كتبًا)، ونكتة تنكيرها»","url":""}]},{"id":"s62-19","number":19,"surah":62,"verses":[5],"references":[{"surah":62,"verses":[5]}],"verseLabel":"الجمعة: 5","question":"كيف يكشف مثل الحمار الحامل أسفارًا عيب العلم الذي لا يُعمل به؟","answer":"يشبه من أُلزم التوراة ثم عطلها بحمار يحمل كتبًا نفيسة ولا يدرك معناها ولا ينتفع بها؛ فالذم ليس في حمل العلم، بل في بقاء أثره خارج القلب والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص656–657، تحت عنوان «نوع التشبيه، وبلاغته في قوله: ﴿مثل الذين حملوا﴾ الآية»","url":""}]},{"id":"s62-7","number":7,"surah":62,"verses":[5],"references":[{"surah":62,"verses":[5]}],"verseLabel":"الجمعة: 5","question":"ماذا يعني أنهم ﴿حُمِّلُوا التَّوْرَاةَ﴾؟","answer":"يعني أنهم كُلّفوا حفظها وفهمها والعمل بأحكامها وتبليغها، لا مجرد امتلاك نصها؛ فالتحميل يصور أمانة ثقيلة ضيعوا حقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص649–650، تحت عنوان «دلالة التعبير بالتحميل في جملة ﴿حملوا﴾، ولطيفة صوغه ماضيًا»","url":""}]},{"id":"s62-20","number":20,"surah":62,"verses":[5],"references":[{"surah":62,"verses":[5]}],"verseLabel":"الجمعة: 5","question":"لماذا بُني ﴿حُمِّلُوا التَّوْرَاةَ﴾ للمجهول؟","answer":"لصرف التركيز إلى خيانتهم للأمانة التي أُلزموها، مع تنزيه اسم الله عن أن يذكر في سياق تشبيههم بالحمار وإهانة صنيعهم؛ فالفاعل معلوم من المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص650، تحت عنوان «نكتة بناء الفعل ﴿حملوا﴾ لما لم يسم فاعله»","url":""}]},{"id":"s62-8","number":8,"surah":62,"verses":[6],"references":[{"surah":62,"verses":[6]}],"verseLabel":"الجمعة: 6","question":"لماذا تحداهم بتمني الموت إن كانوا ﴿أَوْلِيَاءَ لِلَّهِ مِنْ دُونِ النَّاسِ﴾؟","answer":"جاء الأمر بتمني الموت للتعجيز وكشف بطلان دعوى اختصاصهم بالولاية؛ فلو صدقوا في الاطمئنان إلى كرامتهم عند الله لما خافوا المصير إليه. وامتناعهم عن التمني حجة تكشف كذب الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص678، تحت عنوان «غرض الأمر في قوله: ﴿فتمنوا﴾»","url":""}]},{"id":"s62-9","number":9,"surah":62,"verses":[8],"references":[{"surah":62,"verses":[8]}],"verseLabel":"الجمعة: 8","question":"ما الصورة في قوله عن الموت ﴿فَإِنَّهُ مُلَاقِيكُمْ﴾؟","answer":"يجعل الموت كطالب يسير نحو الفارين حتى يلقاهم؛ فليست المسألة أنهم يقبلون عليه أو يبتعدون عنه، بل هو آتٍ يدركهم مهما فروا.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص695، تحت عنوان «بلاغة المجاز في قوله: ﴿فإنه ملاقيكم﴾»","url":""}]},{"id":"s62-10","number":10,"surah":62,"verses":[9],"references":[{"surah":62,"verses":[9]}],"verseLabel":"الجمعة: 9","question":"ما المقصود بالسعي إلى الجمعة في قوله ﴿فَاسْعَوْا إِلَى ذِكْرِ اللَّهِ﴾؟","answer":"هو الجد في القصد والمبادرة وترك الشواغل، لا الجري الذي يخل بالسكينة؛ فيأتي المصلي بوقار لكنه يقدم الجمعة على غيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص717–718، تحت عنوان «دلالة السعي، وغرض الأمر في جملة ﴿فاسعوا﴾»","url":""}]},{"id":"s62-21","number":21,"surah":62,"verses":[9],"references":[{"surah":62,"verses":[9]}],"verseLabel":"الجمعة: 9","question":"لماذا عُبّر عن صلاة الجمعة وخطبتها بقوله ﴿ذِكْرِ اللَّهِ﴾؟","answer":"لأن الصلاة والخطبة قائمتان على ذكر الله وتذكير الناس به، فسميت العبادة بأبرز ما تشتمل عليه؛ واللفظ يسع الخطبة والصلاة معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص718–719، تحت عنوان «بلاغة المجاز في التعبير بـ﴿ذكر الله﴾»","url":""}]},{"id":"s62-11","number":11,"surah":62,"verses":[9],"references":[{"surah":62,"verses":[9]}],"verseLabel":"الجمعة: 9","question":"ماذا يفيد الأمر ﴿وَذَرُوا الْبَيْعَ﴾ عند النداء للجمعة؟","answer":"يفيد ترك البيع وقطعه فورًا لا مجرد تخفيفه، لأن حق النداء مقدم على صفقة قائمة أو ربح منتظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص720–721، تحت عنوان «دلالة التعبير بلفظة (ذروا)، وغرض الأمر منه»","url":""}]},{"id":"s62-22","number":22,"surah":62,"verses":[9],"references":[{"surah":62,"verses":[9]}],"verseLabel":"الجمعة: 9","question":"لماذا قيل ﴿وَذَرُوا الْبَيْعَ﴾ ولم يقل «التجارة»؟","answer":"خُص البيع لأنه أبرز معاملة تشغل وقت النداء، وأريد به ما يشمل البيع والشراء وسائر ما يصد عن الجمعة؛ فذكر الصورة الأظهر لينبه إلى جنس الشاغل كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص721، تحت عنوان «معنى (أل) في ﴿البيع﴾، ووجه المجاز فيه»","url":""}]},{"id":"s62-12","number":12,"surah":62,"verses":[10],"references":[{"surah":62,"verses":[10]}],"verseLabel":"الجمعة: 10","question":"هل الأمر ﴿فَانْتَشِرُوا فِي الْأَرْضِ﴾ بعد الجمعة يوجب الخروج للكسب؟","answer":"لا؛ جاء الأمر بعد منع البيع لرفع الحظر وإعادة الإباحة، فيجوز أن ينتشروا لمصالحهم ويجوز أن يبقوا، وليس كل مصلٍّ مأمورًا بالتجارة وجوبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص729، تحت عنوان «غرض الأمر في جملة ﴿فانتشروا﴾، ولطيفة إسناده إلى ضمير الجماعة»","url":""}]},{"id":"s62-23","number":23,"surah":62,"verses":[10],"references":[{"surah":62,"verses":[10]}],"verseLabel":"الجمعة: 10","question":"لماذا جُمع طلب الرزق بعد الجمعة مع الأمر بكثرة ذكر الله؟","answer":"حتى لا يتحول الانتشار في المعاش إلى غفلة؛ فيأخذ المؤمن بالأسباب ولسانه وقلبه موصولان بالله، فتجتمع عمارة الدنيا وعبادة المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص733، تحت عنوان «معنى (الواو) في جملة ﴿واذكروا الله كثيرًا﴾»","url":""}]},{"id":"s62-13","number":13,"surah":62,"verses":[11],"references":[{"surah":62,"verses":[11]}],"verseLabel":"الجمعة: 11","question":"لماذا قُدّمت التجارة على اللهو في مشهد الانفضاض من الجمعة؟","answer":"لأن التجارة كانت المقصودة أصلًا عند قدوم العير، أما اللهو فكان تابعًا لها ومناديًا إليها؛ فبدأ بما حمل أكثرهم على الخروج.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص744، تحت عنوان «نكتة تقديم رؤية التجارة على اللهو»","url":""}]},{"id":"s62-24","number":24,"surah":62,"verses":[11],"references":[{"surah":62,"verses":[11]}],"verseLabel":"الجمعة: 11","question":"لماذا قُدّم اللهو على التجارة في قوله ﴿خَيْرٌ مِنَ اللَّهْوِ وَمِنَ التِّجَارَةِ﴾؟","answer":"لأن اللهو أوضح ذمًا ولا منفعة معتبرة فيه، فبدأ به في المفاضلة، ثم ذكر التجارة ليقرر أن ما عند الله خير حتى من الكسب الذي يرجون نفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص751–752، تحت عنوان «براعة تقديم ﴿من اللهو﴾ على (من التجارة)»","url":""}]},{"id":"s62-14","number":14,"surah":62,"verses":[11],"references":[{"surah":62,"verses":[11]}],"verseLabel":"الجمعة: 11","question":"ما سرّ التعبير في قوله ﴿انْفَضُّوا إِلَيْهَا﴾ بالإفراد مع ذكر التجارة واللهو؟","answer":"عاد الضمير إلى التجارة لأنها المقصود الأهم في الانفضاض، وكان اللهو المصاحب لظهورها تابعًا لها. وتذكر الموسوعة أيضًا وجه الحذف لدلالة المذكور على الآخر؛ فإفراد الضمير يبرز الغرض الرئيس، ولا ينفي دخول اللهو في الذم.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص746–747، تحت عنوان «مرجع الضمير في ﴿إليها﴾»","url":""}]},{"id":"s63-1","number":1,"surah":63,"verses":[1],"references":[{"surah":63,"verses":[1]}],"verseLabel":"المنافقون: 1","question":"ما براعة افتتاح سورة المنافقون بجملة شرطية؟","answer":"يفتتح بمشهد مجيئهم إلى النبي ﷺ ونطقهم بالشهادة، ثم يأتي الجواب الإلهي كاشفًا كذبهم؛ فيضع القارئ مباشرة أمام التناقض بين الظاهر والباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص769، تحت عنوان «براعة الاستهلال بالجملة الشرطية»","url":""}]},{"id":"s63-2","number":2,"surah":63,"verses":[1],"references":[{"surah":63,"verses":[1]}],"verseLabel":"المنافقون: 1","question":"لماذا حشد المنافقون المؤكدات في قولهم ﴿نَشْهَدُ إِنَّكَ لَرَسُولُ اللَّهِ﴾؟","answer":"بالغوا في توثيق كلامهم بلفظ الشهادة و﴿إن﴾ واللام والجملة الاسمية ليستروا كذب باطنهم وراء صورة اليقين. فكثرة المؤكدات هنا لا تدل على صدقهم، بل تكشف حاجتهم إلى إقناع السامع بما لا يعتقدونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص773، تحت عنوان «فائدة تتابع المؤكدات في الجملة»","url":""}]},{"id":"s63-3","number":3,"surah":63,"verses":[1],"references":[{"surah":63,"verses":[1]}],"verseLabel":"المنافقون: 1","question":"لماذا توسط قوله ﴿وَاللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُ﴾ بين دعوى المنافقين وتكذيبهم؟","answer":"لئلا يوهم تكذيب المنافقين أن مضمون قولهم في الرسالة كاذب؛ فأثبت الله حقيقة رسالة نبيه أولًا، ثم بيّن أن الكذب في ادعائهم الشهادة الصادقة بما لا يوافق قلوبهم. فالجملة تحمي الحقيقة وتحدد موضع الكذب بدقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص773–774، تحت عنوان «دلالة الواو في صدر الجملة وأثرها الدلالي»","url":""}]},{"id":"s63-4","number":4,"surah":63,"verses":[1],"references":[{"surah":63,"verses":[1]}],"verseLabel":"المنافقون: 1","question":"لماذا قيل ﴿إِنَّ الْمُنَافِقِينَ لَكَاذِبُونَ﴾ ولم يقل: إنهم لكاذبون؟","answer":"أظهر وصفهم بدل الضمير ليقرر أن النفاق هو سبب كذبهم، ويثبت هذه الصفة عليهم في مقام فضحهم. كما يحول الحكم من الإشارة إلى أشخاص حاضرِين إلى قاعدة تكشف حقيقة المنافق أينما تكرر وصفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص777، تحت عنوان «دلالة التعبير بالإظهار موضع الإضمار»","url":""}]},{"id":"s63-18","number":18,"surah":63,"verses":[1],"references":[{"surah":63,"verses":[1]}],"verseLabel":"المنافقون: 1","question":"كيف قابلت شهادة الله شهادة المنافقين في مطلع السورة؟","answer":"كرر السياق لفظ الشهادة على سبيل المشاكلة، لكن شهادتهم دعوى تخالف باطنهم، وشهادة الله خبر حق يكشف كذبهم. فالتشابه اللفظي يزيد المفارقة وضوحًا: صورة القول واحدة، والحقيقة متقابلة تمامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص776، تحت عنوان «بلاغة المشاكلة في الآية»","url":""}]},{"id":"s63-5","number":5,"surah":63,"verses":[2],"references":[{"surah":63,"verses":[2]}],"verseLabel":"المنافقون: 2","question":"لماذا سميت أيمان المنافقين ﴿جُنَّةً﴾؟","answer":"شُبهت أيمانهم الكاذبة بالترس الذي يتقي به المقاتل الضرب؛ فقد احتموا بها من انكشاف كفرهم ومن أحكامه، وجعلوها وسيلة لاكتساب الثقة والأمان. والصورة تكشف أنهم لم يقسموا طلبًا للحق بل دفاعًا عن باطلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص779، تحت عنوان «بلاغة التشبيه في قوله: ﴿جنة﴾»","url":""}]},{"id":"s63-6","number":6,"surah":63,"verses":[3],"references":[{"surah":63,"verses":[3]}],"verseLabel":"المنافقون: 3","question":"كيف قيل عن المنافقين ﴿آمَنُوا ثُمَّ كَفَرُوا﴾؟","answer":"لأنهم أظهروا الإيمان بألسنتهم ثم كشف سلوكهم ما استقر من كفرهم، وقيل: دخل بعضهم في الإيمان ثم ارتد. وفي الوجهين يبين التعبير أن الانتساب الظاهر لا ينفع إذا نقضه القلب والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص786، تحت عنوان «دلالة التعبير بالفعل ﴿آمنوا﴾ مادة وصيغة»","url":""}]},{"id":"s63-7","number":7,"surah":63,"verses":[3],"references":[{"surah":63,"verses":[3]}],"verseLabel":"المنافقون: 3","question":"ما الذي تصوره عبارة ﴿طُبِعَ عَلَى قُلُوبِهِمْ﴾، ولماذا لا يفقهون؟","answer":"تصور العبارة القلب كشيء خُتم عليه فانغلق عن قبول الحق؛ فإذا انسد طريق الهدى إلى القلب فقد صاحبه الفقه والبصيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص788، تحت عنوان «بلاغة المجاز في الطبع على القلوب»","url":""}]},{"id":"s63-8","number":8,"surah":63,"verses":[4],"references":[{"surah":63,"verses":[4]}],"verseLabel":"المنافقون: 4","question":"لماذا قيل ﴿تُعْجِبُكَ أَجْسَامُهُمْ﴾ لا «أشخاصهم»؟","answer":"لأن لفظ الأجسام يلفت إلى البنية الظاهرة وحدها، كأن ما يثير الإعجاب فيهم قشرة جسمية بلا روح إيمان ولا عقل نافع. فاختيار اللفظ يمهد للمفارقة بين حسن الهيئة وفراغ الباطن التي يكشفها تشبيههم بالخشب.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص797، تحت عنوان «دلالة التعبير بلفظ الأجسام دون غيره»","url":""}]},{"id":"s63-9","number":9,"surah":63,"verses":[4],"references":[{"surah":63,"verses":[4]}],"verseLabel":"المنافقون: 4","question":"لماذا شُبّه المنافقون بالخشب؟","answer":"لأن لهم أجسامًا ومناظر قد تعجب، لكنهم خالون من الفهم النافع كما أن الخشب له جرم ولا يعقل. فالتشبيه يهدم الواجهة الجذابة ويصور جمود قلوبهم وعجزهم عن الانتفاع بما يسمعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص801–802، تحت عنوان «بلاغة التشبيه في قوله ﴿كأنهم خشب مسندة﴾»","url":""}]},{"id":"s63-19","number":19,"surah":63,"verses":[4],"references":[{"surah":63,"verses":[4]}],"verseLabel":"المنافقون: 4","question":"ماذا يضيف وصف الخشب بأنها ﴿مُسَنَّدَةٌ﴾ إلى صورة المنافقين؟","answer":"يصوّر أجسامًا مصفوفة تستند إلى الجدار ولا تقوم بنفسها ولا تؤدي نفعًا، مع أن منظرها قد يبدو مستقيمًا. وكذلك المنافقون يعتمدون على غيرهم ويتزينون بالمظهر، لكنهم فارغون من الثبات والعمل النافع.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص803–804، تحت عنوان «نكتة وصف الخشب بأنها ﴿مسندة﴾»","url":""}]},{"id":"s63-10","number":10,"surah":63,"verses":[4],"references":[{"surah":63,"verses":[4]}],"verseLabel":"المنافقون: 4","question":"لماذا كان المنافقون يحسبون ﴿كُلَّ صَيْحَةٍ﴾ واقعةً عليهم؟","answer":"لأن خوف انكشافهم جعلهم يترقبون العقوبة في كل صوت مرتفع أو خبر مفاجئ، فلا تمر صيحة إلا ظنوها تفضحهم أو تستدعي قتالهم. ولفظ ﴿كل﴾ يصور دوام هلعهم واتساعه مهما اختلف سبب الصوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص805، تحت عنوان «نكتة التعبير بلفظ ﴿كل﴾»","url":""}]},{"id":"s63-11","number":11,"surah":63,"verses":[4],"references":[{"surah":63,"verses":[4]}],"verseLabel":"المنافقون: 4","question":"لماذا قيل عن المنافقين ﴿هُمُ الْعَدُوُّ﴾ مع أن للمؤمنين أعداء غيرهم؟","answer":"المقصود إبراز أنهم العدو الأشد خطرًا في هذا المقام، لأنهم يخفون العداوة ويخالطون المؤمنين ويعرفون أسرارهم، بخلاف العدو الظاهر الذي يُعرف موضع الحذر منه. فالقصر للمبالغة في التحذير لا لنفي كل عدو سواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج61، ص807–808، تحت عنوان «بلاغة القصر بتعريف طرفي الإسناد»","url":""}]},{"id":"s63-12","number":12,"surah":63,"verses":[5],"references":[{"surah":63,"verses":[5]}],"verseLabel":"المنافقون: 5","question":"لماذا صُوّر إعراض المنافقين بقوله ﴿لَوَّوْا رُءُوسَهُمْ﴾؟","answer":"لأن ليّ الرأس حركة مرئية تجمع الإعراض بالاستكبار والاستهزاء، وهي أبلغ من مجرد القول إنهم أعرضوا. فالصورة تستحضر رفضهم الاستغفار وإظهارهم أنهم لا يبالون بالدعوة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص16، تحت عنوان «سر التعبير بـ﴿لووا رؤوسهم﴾»","url":""}]},{"id":"s63-13","number":13,"surah":63,"verses":[6],"references":[{"surah":63,"verses":[6]}],"verseLabel":"المنافقون: 6","question":"لماذا فُصل قوله ﴿إِنَّ اللَّهَ لَا يَهْدِي الْقَوْمَ الْفَاسِقِينَ﴾ عما قبله؟","answer":"لأنه يأتي تعليلًا مستقلًا لعدم المغفرة في هذا المقام: إصرارهم على الفسق هو الذي حرمهم طريق الهداية، لا قصور الاستغفار لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص25، تحت عنوان «نكتة فصل قوله ﴿إن الله لا يهدي القوم الفاسقين﴾»","url":""}]},{"id":"s63-14","number":14,"surah":63,"verses":[7,8],"references":[{"surah":63,"verses":[7,8]}],"verseLabel":"المنافقون: 7–8","question":"لماذا وصف المنافقين مرة بأنهم ﴿لَا يَفْقَهُونَ﴾ ومرة بأنهم ﴿لَا يَعْلَمُونَ﴾؟","answer":"نُفي عنهم الفقه حين كان المطلوب فهم أن خزائن الله ورزقه لا يملكها المنافقون، وهو معنى يحتاج إلى تدبر. ونُفي عنهم العلم حين جهلوا الحقيقة الظاهرة أن العزة لله ورسوله والمؤمنين؛ فجمع السياق فقدان الفهم العميق والجهل بالحق الواضح.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص47–48، تحت عنوان «نكتة تكرار نفي العلم عنهم بعد نفي الفقه»","url":""}]},{"id":"s63-15","number":15,"surah":63,"verses":[9],"references":[{"surah":63,"verses":[9]}],"verseLabel":"المنافقون: 9","question":"كيف نسبت الآية الإلهاء إلى الأموال والأولاد في قوله ﴿لَا تُلْهِكُمْ أَمْوَالُكُمْ وَلَا أَوْلَادُكُمْ﴾؟","answer":"أسند الإلهاء إلى المال والولد لأنهما سببه الظاهر، أما الفاعل الحقيقي فهو الإنسان حين يفرط في التعلق بهما ويقدمهما على ذكر الله. فالمجاز يحذر من تحويل النعمة إلى شاغل، ولا يذم المال والولد في ذاتهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص56، تحت عنوان «بلاغة المجاز العقلي»","url":""}]},{"id":"s63-16","number":16,"surah":63,"verses":[10],"references":[{"surah":63,"verses":[10]}],"verseLabel":"المنافقون: 10","question":"لماذا كانت الصدقة أول ما تمناه المحتضر في قوله ﴿فَأَصَّدَّقَ وَأَكُنْ مِنَ الصَّالِحِينَ﴾؟","answer":"لأن سياق الآيات حذّر من أن تلهي الأموال عن ذكر الله والإنفاق، فكان أول ما يندم عليه المحتضر ما أمسكه ولم يقدمه. وتقديم الصدقة يكشف أن المال الذي شغله صار عند انكشاف النهاية أحب شيء إليه أن يبذله قبل فوات العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص70–71، تحت عنوان «سر تقديم الصدقة»","url":""}]},{"id":"s63-17","number":17,"surah":63,"verses":[10],"references":[{"surah":63,"verses":[10]}],"verseLabel":"المنافقون: 10","question":"ماذا تكشف الفاء في أمنية المحتضر ﴿فَأَصَّدَّقَ﴾ عن غرضه من طلب التأخير؟","answer":"تكشف أنه لا يطلب مهلةً ليزداد من الدنيا، بل يجعل التأخير سببًا مباشرًا لإيقاع الصدقة وتحقيق الصلاح. كما تصور وعده بالمبادرة فورًا إلى تدارك ما فاته، لأن الأجل المطلوب قريب والفرصة لا تحتمل إبطاءً.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص68، تحت عنوان «دلالة التعبير بالفاء»","url":""}]},{"id":"s64-1","number":1,"surah":64,"verses":[1],"references":[{"surah":64,"verses":[1]}],"verseLabel":"التغابن: 1","question":"ماذا يفيد تكرار ﴿لَهُ﴾ في قوله ﴿لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ﴾؟","answer":"يفيد قصر الملك والحمد الكاملين على الله، ويقرر استقلال كل حقيقة منهما: فهو وحده المالك المتصرف، وهو وحده المستحق للحمد على نعمه وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص92–93، تحت عنوان «فائدة تقديم شبه الجملة على المسند إليه»","url":""}]},{"id":"s64-18","number":18,"surah":64,"verses":[1],"references":[{"surah":64,"verses":[1]}],"verseLabel":"التغابن: 1","question":"لماذا اقترن الحمد بالملك في مطلع سورة التغابن؟","answer":"لأن الملك يثبت تمام القدرة والتصرف، والحمد يثبت كمال الحكمة والإحسان؛ فليس ملكه قهرًا مجردًا، بل تدبيرًا يستحق الحمد في كل حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص95، تحت عنوان «مناسبة اقتران الحمد بالملك»","url":""}]},{"id":"s64-2","number":2,"surah":64,"verses":[2],"references":[{"surah":64,"verses":[2]}],"verseLabel":"التغابن: 2","question":"ما سرّ التعبير في قوله ﴿فَمِنْكُمْ كَافِرٌ وَمِنْكُمْ مُؤْمِنٌ﴾ وقدم الكافر؟","answer":"قدم الكافر لأن المقام مقام تعريض به وتوبيخ له على كفره مع أن الله خالقه، فكان ذكره أولًا أنسب بغرض الإنذار. وتذكر الموسوعة كذلك كثرة الكافرين في بيان وجه هذا التقديم.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص103، تحت عنوان «فائدة تقديم ذكر ﴿كافر﴾ على ﴿مؤمن﴾»","url":""}]},{"id":"s64-3","number":3,"surah":64,"verses":[3],"references":[{"surah":64,"verses":[3]}],"verseLabel":"التغابن: 3","question":"ماذا يفيد قوله عن صور الناس ﴿فَأَحْسَنَ صُوَرَكُمْ﴾؟","answer":"يفيد أنه أوجد صورهم على هيئة متقنة مستقيمة تلائم وظائفهم، فالإحسان يشمل جمال الخِلقة وكمال التهيئة لا مجرد حسن المنظر.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص114، تحت عنوان «دلالة التعبير بفعل ﴿فأحسن﴾»","url":""}]},{"id":"s64-4","number":4,"surah":64,"verses":[4],"references":[{"surah":64,"verses":[4]}],"verseLabel":"التغابن: 4","question":"لماذا تكرر فعل ﴿يَعْلَمُ﴾ عند ذكر السماوات والأرض ثم السر والجهر؟","answer":"لاختلاف مجالات العلم وتنوعها؛ فيستقل كل مجال بالتقرير، ويتجدد التذكير بإحاطة علم الله بالكون وبأعمال الناس الظاهرة والخفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص121، تحت عنوان «دلالة تكرار فعل: (يعلم)»","url":""}]},{"id":"s64-19","number":19,"surah":64,"verses":[4],"references":[{"surah":64,"verses":[4]}],"verseLabel":"التغابن: 4","question":"لماذا خُصَّ ﴿مَا فِي الصُّدُورِ﴾ بعد قوله ﴿يَعْلَمُ مَا تُسِرُّونَ وَمَا تُعْلِنُونَ﴾؟","answer":"لأن ما في الصدور أخفى طبقات السر؛ فذكره بعد العموم يؤكد أن علم الله يبلغ النيات والخواطر والدوافع التي لا يطلع عليها البشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص122–123، تحت عنوان «دلالة عطف الخاص على العام»","url":""}]},{"id":"s64-20","number":20,"surah":64,"verses":[4],"references":[{"surah":64,"verses":[4]}],"verseLabel":"التغابن: 4","question":"ماذا يقرر ختام الآية بقوله ﴿وَاللَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ﴾؟","answer":"يقرر ثبوت علم الله وإحاطته الدائمة بما استقر في القلوب، فيجعل التذييل قاعدة عامة تبعث على مراقبته والخوف من خفايا النيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص124، تحت عنوان «غرض التذييل بصفة العلم»","url":""}]},{"id":"s64-5","number":5,"surah":64,"verses":[5],"references":[{"surah":64,"verses":[5]}],"verseLabel":"التغابن: 5","question":"ما الصورة في قوله عن المكذبين ﴿فَذَاقُوا وَبَالَ أَمْرِهِمْ﴾؟","answer":"صُورت عاقبة الكفر بطعام مر يذوقونه مباشرة؛ فالذوق يجعل العقوبة تجربة محسوسة بعد أن كانت وعيدًا يسمعونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص132، تحت عنوان «بلاغة الاستعارة في فعل الذوق»","url":""}]},{"id":"s64-21","number":21,"surah":64,"verses":[5],"references":[{"surah":64,"verses":[5]}],"verseLabel":"التغابن: 5","question":"لماذا أضيف الوبال إلى أمرهم في ﴿وَبَالَ أَمْرِهِمْ﴾؟","answer":"للدلالة على أن سوء العاقبة تولد من شأنهم الذي اختاروه، أي كفرهم وعنادهم؛ فالعذاب ثمرة عملهم لا ظلم واقع عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص133، تحت عنوان «نوع الإضافة ودلالتها»","url":""}]},{"id":"s64-6","number":6,"surah":64,"verses":[6],"references":[{"surah":64,"verses":[6]}],"verseLabel":"التغابن: 6","question":"ماذا يكشف تقديم ﴿بَشَرٌ﴾ في قولهم ﴿أَبَشَرٌ يَهْدُونَنَا﴾؟","answer":"يجعل بشرية الرسل نفسها محور الإنكار، كأنهم يستبعدون أن يكون الهادي إنسانًا مثلهم؛ فيفضح تعاليهم عن اتباع الحق لا ضعف دليله.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص143، تحت عنوان «نكتة تقديم المسند إليه على المسند الفعلي»","url":""}]},{"id":"s64-7","number":7,"surah":64,"verses":[6],"references":[{"surah":64,"verses":[6]}],"verseLabel":"التغابن: 6","question":"لماذا عُطف التولي على الكفر في قوله ﴿فَكَفَرُوا وَتَوَلَّوْا﴾؟","answer":"ليجمع بين رفض الحق في الباطن والإعراض عن سماعه واتباعه في الظاهر؛ فالتولي أثر عملي يزيد الكفر ظهورًا وقبحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص144، تحت عنوان «نكتة عطف التولي على الكفر»","url":""}]},{"id":"s64-22","number":22,"surah":64,"verses":[6],"references":[{"surah":64,"verses":[6]}],"verseLabel":"التغابن: 6","question":"ماذا يفيد قوله ﴿وَاسْتَغْنَى اللَّهُ﴾ جملةً اسمية بعد كفرهم وتوليهم؟","answer":"يفيد ثبوت غنى الله الدائم عن إيمانهم وطاعتهم؛ فكفرهم لا ينقص ملكه، وهم المحتاجون إليه في كل حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص145، تحت عنوان «نكتة التعبير بالجملة الاسمية»","url":""}]},{"id":"s64-23","number":23,"surah":64,"verses":[6],"references":[{"surah":64,"verses":[6]}],"verseLabel":"التغابن: 6","question":"لماذا خُتم الحديث عن استغناء الله بوصفه ﴿غَنِيٌّ حَمِيدٌ﴾؟","answer":"الغني يقرر أنه لا يحتاج إلى خلقه، والحميد يبين أنه مستحق للحمد بذاته ونعمه سواء حمدوه أم كفروا؛ فيجتمع كمال الاستغناء وكمال الاستحقاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص146، تحت عنوان «مناسبة التذييل بصفتي: ﴿غني حميد﴾»","url":""}]},{"id":"s64-8","number":8,"surah":64,"verses":[7],"references":[{"surah":64,"verses":[7]}],"verseLabel":"التغابن: 7","question":"ماذا يكشف اختيار ﴿زَعَمَ﴾ في قوله ﴿زَعَمَ الَّذِينَ كَفَرُوا أَنْ لَنْ يُبْعَثُوا﴾؟","answer":"يشعر بأن قولهم دعوى باطلة بلا برهان، ويستنكر جرأتهم على الجزم بنفي البعث مع افتقارهم إلى العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص149، تحت عنوان «بلاغة استعمال مفردة: ﴿زعم﴾»","url":""}]},{"id":"s64-24","number":24,"surah":64,"verses":[7],"references":[{"surah":64,"verses":[7]}],"verseLabel":"التغابن: 7","question":"لماذا جاء الرد على نفي البعث بـ﴿بَلَى﴾؟","answer":"لأنها تنقض النفي السابق وتقلبه إلى إثبات مؤكد: سيبعثون حتمًا. فهي جواب موجز يهدم أصل دعواهم قبل إقامة القسم والدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص150–151، تحت عنوان «معنى ﴿بلى﴾ ودلالة استعمالها»","url":""}]},{"id":"s64-25","number":25,"surah":64,"verses":[7],"references":[{"surah":64,"verses":[7]}],"verseLabel":"التغابن: 7","question":"ما غرض القسم في ﴿قُلْ بَلَى وَرَبِّي لَتُبْعَثُنَّ﴾؟","answer":"لتوكيد البعث بأقوى أساليب التقرير، وربطه بربوبية الله وقدرته التي خلق بها أول مرة؛ فيواجه إنكارهم بقسم ووعد لا يتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص151، تحت عنوان «بلاغة القسم وغرضه الارتباطي»","url":""}]},{"id":"s64-9","number":9,"surah":64,"verses":[8],"references":[{"surah":64,"verses":[8]}],"verseLabel":"التغابن: 8","question":"لماذا صُوّر القرآن بأنه ﴿النُّورِ﴾؟","answer":"لأنه يكشف حقائق الإيمان ويهدي من ظلمات الجهل والشك كما يكشف النور المرئيات ويهدي في الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص160، تحت عنوان «بلاغة الاستعارة في لفظ (النور)»","url":""}]},{"id":"s64-26","number":26,"surah":64,"verses":[8],"references":[{"surah":64,"verses":[8]}],"verseLabel":"التغابن: 8","question":"ماذا يضيف قوله عن القرآن ﴿الَّذِي أَنْزَلْنَا﴾ بعد وصفه بالنور؟","answer":"يميز هذا النور بأنه وحي منزل من عند الله، ويعظم شأن إنزاله ويذكر بنعمة وصول الهداية إلى الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص161، تحت عنوان «غرض التعبير بالاسم الموصول»","url":""}]},{"id":"s64-10","number":10,"surah":64,"verses":[9],"references":[{"surah":64,"verses":[9]}],"verseLabel":"التغابن: 9","question":"لماذا سُمي يوم القيامة ﴿يَوْمُ التَّغَابُنِ﴾؟","answer":"لأنه اليوم الذي يظهر فيه الربح والخسران الحقيقيان: يرى المؤمنون فوزهم، ويرى الكافرون أنهم باعوا الآخرة بالدنيا وخسروا أنفسهم ومنازلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص168–169، تحت عنوان «بلاغة الاستعارة والمجاز والتمثيل في لفظ: ﴿التغابن﴾»","url":""}]},{"id":"s64-27","number":27,"surah":64,"verses":[9],"references":[{"surah":64,"verses":[9]}],"verseLabel":"التغابن: 9","question":"ماذا يفيد تعريف الطرفين في قوله ﴿ذَلِكَ يَوْمُ التَّغَابُنِ﴾؟","answer":"يقصر التغابن الكامل الحقيقي على ذلك اليوم؛ فما يعده الناس ربحًا وخسارة في الدنيا يتضاءل أمام انكشاف المصير الأبدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص169، تحت عنوان «بلاغة القصر بتعريف طرفي الإسناد»","url":""}]},{"id":"s64-11","number":11,"surah":64,"verses":[10],"references":[{"surah":64,"verses":[10]}],"verseLabel":"التغابن: 10","question":"ما الصورة في قوله عن المؤمن ﴿يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ﴾؟","answer":"تفيد ﴿عن﴾ المجاوزة، فتصور السيئات وقد أُبعدت عنه ومحيت آثارها، فلا تبقى حاجزًا بينه وبين رحمة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص172، تحت عنوان «دلالة حرف (عن)»","url":""}]},{"id":"s64-28","number":28,"surah":64,"verses":[10],"references":[{"surah":64,"verses":[10]}],"verseLabel":"التغابن: 10","question":"لماذا جُمع للمؤمن بين تكفير السيئات وإدخال الجنات؟","answer":"ليجتمع له دفع الضرر وجلب النفع: تزول تبعات الذنب أولًا، ثم ينال الرحمة والنعيم الدائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص172، تحت عنوان «نوع الواو ودلالتها»","url":""}]},{"id":"s64-29","number":29,"surah":64,"verses":[10],"references":[{"surah":64,"verses":[10]}],"verseLabel":"التغابن: 10","question":"ماذا يوحي وصف الكافرين بأنهم ﴿أَصْحَابُ النَّارِ﴾؟","answer":"يوحي بملازمتهم النار ودوام مقامهم فيها؛ فالصاحب يلازم صاحبه، وفيه تقريع يقابل دخول المؤمنين في الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص182، تحت عنوان «دلالة التعبير بلفظ ﴿أصحاب﴾»","url":""}]},{"id":"s64-12","number":12,"surah":64,"verses":[11],"references":[{"surah":64,"verses":[11]}],"verseLabel":"التغابن: 11","question":"ماذا يقرر القصر في قوله ﴿مَا أَصَابَ مِنْ مُصِيبَةٍ إِلَّا بِإِذْنِ اللَّهِ﴾؟","answer":"يقرر أن كل مصيبة تقع بعلم الله وتقديره، لا فوضى ولا خروجًا عن سلطانه؛ فيورث المؤمن طمأنينة وتسليمًا لا استسلامًا للأسباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص188، تحت عنوان «بلاغة القصر في الآية»","url":""}]},{"id":"s64-30","number":30,"surah":64,"verses":[11],"references":[{"surah":64,"verses":[11]}],"verseLabel":"التغابن: 11","question":"لماذا قُدم الإيمان بالله على هداية القلب عند المصيبة؟","answer":"لأن التصديق بأن المصيبة بإذن الله هو السبب الذي يفتح القلب للرضا والصبر وحسن الفهم؛ فالهداية ثمرة الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص192، تحت عنوان «سر تقديم الإيمان على الهداية»","url":""}]},{"id":"s64-31","number":31,"surah":64,"verses":[11],"references":[{"surah":64,"verses":[11]}],"verseLabel":"التغابن: 11","question":"لماذا خُص القلب بالهداية في قوله ﴿يَهْدِ قَلْبَهُ﴾؟","answer":"لأن القلب موضع الجزع والرضا ومركز ثبات الإنسان؛ فإذا هداه الله عند المصيبة استقام الجسد والعمل، وتحولت المحنة إلى يقين وصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص195–196، تحت عنوان «سر التنصيص على القلب وجعله مفعول الهداية»","url":""}]},{"id":"s64-13","number":13,"surah":64,"verses":[12],"references":[{"surah":64,"verses":[12]}],"verseLabel":"التغابن: 12","question":"ماذا تضيف نسبة الرسول إلى الله في قوله ﴿رَسُولِنَا﴾؟","answer":"تشرف الرسول وتعظم قدره وتقرر وجوب طاعته؛ لأنه مبعوث الله المؤتمن على بلاغ رسالته، لا متحدث من عند نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج62، ص207، تحت عنوان «دلالة إضافة الرسول إلى ضمير العظمة ﴿رسولنا﴾»","url":""}]}]);
